"""G6. Encryption: compact JWE (RSA-OAEP-256 + A256GCM out, allow-listed algorithms in)."""

from __future__ import annotations

import base64
import binascii
import json
import re
from typing import Any

from authlib.jose import JsonWebEncryption
from cryptography import x509
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import rsa

OUT_ALG = "RSA-OAEP-256"
OUT_ENC = "A256GCM"
IN_ALGS = ("RSA-OAEP-256", "RSA-OAEP")
IN_ENCS = (
    "A256GCM",
    "A128GCM",
    "A192GCM",
    "A256CBC-HS512",
    "A128CBC-HS256",
    "A192CBC-HS384",
)
DROPPED_HEADERS = ("alg", "enc", "typ")
NOT_COMPACT = "payload is not a compact JWE (expected five dot-separated parts)"
COMPACT_PARTS = 5

_PEM_RE = re.compile(
    r"-----BEGIN ([A-Z0-9 ]+)-----\s*(.*?)\s*-----END \1-----", re.DOTALL
)

_jwe_out = JsonWebEncryption(algorithms=[OUT_ALG, OUT_ENC])
_jwe_in = JsonWebEncryption(algorithms=[*IN_ALGS, *IN_ENCS])


class CryptoError(Exception):
    """Plain error with the verbatim G6S message; callers wrap it."""


def _b64url_decode(s: str) -> bytes:
    s = s.strip().rstrip("=")
    return base64.urlsafe_b64decode(s + "=" * (-len(s) % 4))


def _b64url_encode(b: bytes) -> str:
    return base64.urlsafe_b64encode(b).rstrip(b"=").decode("ascii")


def is_compact_jwe(s: Any) -> bool:
    if not isinstance(s, str):
        return False
    parts = s.strip().split(".")
    return len(parts) == COMPACT_PARTS and parts[0] != ""


def flattened_to_compact(obj: Any) -> str | None:
    """A flattened JSON JWE as the compact string, or None when `obj` is not one.

    The knowledge source (nhcx.decision.jwe-serialisation) asks receivers to parse
    either serialisation; G8 hands the compact form on.
    """
    if not isinstance(obj, dict):
        return None
    keys = ("protected", "encrypted_key", "iv", "ciphertext", "tag")
    if not all(isinstance(obj.get(k), str) for k in keys) or obj.get("aad"):
        return None
    return ".".join(obj[k] for k in keys)


def encrypt(payload: bytes | str, public_key: Any, headers: dict | None) -> str:
    if public_key is None:
        raise CryptoError("no recipient public key")
    if isinstance(payload, str):
        payload = payload.encode("utf-8")
    if not payload:
        raise CryptoError("payload is empty")
    protected = {"alg": OUT_ALG, "enc": OUT_ENC}
    for k, v in (headers or {}).items():
        if k not in DROPPED_HEADERS:
            protected[k] = v
    try:
        out = _jwe_out.serialize_compact(protected, payload, public_key)
    except Exception as e:
        raise CryptoError(f"encrypt: {e}") from e
    return out.decode("ascii") if isinstance(out, bytes) else out


def parse_header(compact: str) -> dict:
    if not is_compact_jwe(compact):
        raise CryptoError(NOT_COMPACT)
    first = compact.strip().split(".")[0]
    try:
        raw = _b64url_decode(first)
    except (binascii.Error, ValueError) as e:
        raise CryptoError(f"decode JWE header: {e}") from e
    try:
        out = json.loads(raw)
    except ValueError as e:
        raise CryptoError(f"JWE header is not a JSON object: {e}") from e
    if not isinstance(out, dict):
        raise CryptoError("JWE header is not a JSON object: not an object")
    return out


def decrypt(compact: str, private_key: Any) -> bytes:
    if private_key is None:
        raise CryptoError("no private key")
    if not is_compact_jwe(compact):
        raise CryptoError(NOT_COMPACT)
    try:
        header = parse_header(compact)
    except CryptoError as e:
        raise CryptoError(f"parse JWE: {e}") from e
    alg, enc = header.get("alg"), header.get("enc")
    if alg not in IN_ALGS:
        raise CryptoError(f"parse JWE: unsupported key algorithm {alg!r}")
    if enc not in IN_ENCS:
        raise CryptoError(f"parse JWE: unsupported content encryption {enc!r}")
    if "zip" in header:
        raise CryptoError("parse JWE: compressed payloads are not accepted")
    try:
        out = _jwe_in.deserialize_compact(compact.strip(), private_key)
    except Exception as e:
        raise CryptoError(f"decrypt: {e}") from e
    return out["payload"]


def decode_key_material(text: str) -> str:
    text = (text or "").strip()
    if "-----BEGIN" in text:
        return text
    compact = "".join(text.split())
    for decoder in (
        lambda s: base64.b64decode(s, validate=True),
        lambda s: base64.b64decode(s + "=" * (-len(s) % 4), validate=True),
        lambda s: base64.urlsafe_b64decode(s),
        lambda s: base64.urlsafe_b64decode(s + "=" * (-len(s) % 4)),
    ):
        try:
            out = decoder(compact).decode("utf-8")
        except (binascii.Error, ValueError, UnicodeDecodeError):
            continue
        if "-----BEGIN" in out:
            return out.strip()
    return text


def _first_block(text: str) -> tuple[str, bytes] | None:
    m = _PEM_RE.search(decode_key_material(text))
    if not m:
        return None
    label = m.group(1)
    body = "".join(m.group(2).split())
    pem = f"-----BEGIN {label}-----\n{body}\n-----END {label}-----\n"
    return label, pem.encode("ascii")


def parse_private_key(text: str) -> rsa.RSAPrivateKey:
    block = _first_block(text)
    if block is None:
        raise CryptoError("no PEM block found in private key material")
    label, pem = block
    try:
        key = serialization.load_pem_private_key(
            pem.replace(label.encode(), b"PRIVATE KEY")
            if label != "PRIVATE KEY"
            else pem,
            password=None,
        )
    except (ValueError, TypeError):
        key = None
    if key is not None:
        if not isinstance(key, rsa.RSAPrivateKey):
            raise CryptoError("private key is not an RSA key")
        return key
    try:
        rsa_pem = pem.replace(label.encode(), b"RSA PRIVATE KEY")
        key = serialization.load_pem_private_key(rsa_pem, password=None)
    except (ValueError, TypeError) as e:
        raise CryptoError(f"private key is neither PKCS#8 nor PKCS#1: {e}") from e
    if not isinstance(key, rsa.RSAPrivateKey):
        raise CryptoError("private key is not an RSA key")
    return key


def parse_public_key(text: str) -> rsa.RSAPublicKey:
    block = _first_block(text)
    if block is None:
        raise CryptoError("no PEM block found in certificate material")
    label, pem = block
    if label in ("PUBLIC KEY", "RSA PUBLIC KEY"):
        try:
            key = serialization.load_pem_public_key(pem)
        except (ValueError, TypeError) as e:
            raise CryptoError(f"parse public key: {e}") from e
        if not isinstance(key, rsa.RSAPublicKey):
            raise CryptoError("public key is not an RSA key")
        return key
    try:
        cert = x509.load_pem_x509_certificate(
            pem.replace(label.encode(), b"CERTIFICATE")
        )
    except (ValueError, TypeError) as e:
        raise CryptoError(f"parse certificate: {e}") from e
    key = cert.public_key()
    if not isinstance(key, rsa.RSAPublicKey):
        raise CryptoError("certificate public key is not an RSA key")
    return key


def public_numbers_equal(a: Any, b: Any) -> bool:
    if a is None or b is None:
        return False
    try:
        return a.public_numbers() == b.public_numbers()
    except AttributeError:
        return False


__all__ = [
    "CryptoError",
    "decode_key_material",
    "decrypt",
    "encrypt",
    "flattened_to_compact",
    "is_compact_jwe",
    "parse_header",
    "parse_private_key",
    "parse_public_key",
    "public_numbers_equal",
]


def _unused(_: Any) -> str:  # pragma: no cover - keeps _b64url_encode importable
    return _b64url_encode(b"")

"""D3 extension: a patient's ABHA number and address as CARE patient identifiers.

Both live in ``emr.PatientIdentifier`` under instance-level
``emr.PatientIdentifierConfig`` rows (created by migration 0002) whose
``config.system`` is :data:`ABHA_NUMBER_SYSTEM` / :data:`ABHA_ADDRESS_SYSTEM`.
ABHA numbers are compared digits only.
"""

import re

from django.db import models, transaction

from care.emr.models.patient import (
    Patient,
    PatientIdentifier,
    PatientIdentifierConfig,
    PatientIdentifierConfigCache,
)

ABHA_NUMBER_SYSTEM = "https://healthid.abdm.gov.in"
ABHA_ADDRESS_SYSTEM = "https://healthid.abdm.gov.in/address"
ABHA_NUMBER_REGEX = r"^\d{2}-?\d{4}-?\d{4}-?\d{4}$"
ABHA_ADDRESS_REGEX = r"^[A-Za-z0-9._]+(@[A-Za-z0-9.]+)?$"
DUPLICATE_ABHA_MESSAGE = "Another patient is already registered with that ABHA number"


def _identifier_config(use, system, display, description, regex):
    return {
        "use": use,
        "description": description,
        "system": system,
        "required": False,
        "unique": True,
        "regex": regex,
        "display": display,
        "retrieve_config": {
            "retrieve_with_dob": False,
            "retrieve_with_year_of_birth": True,
            "retrieve_with_otp": False,
            "retrieve_partial_search": False,
        },
        "default_value": None,
        "auto_maintained": False,
    }


ABHA_NUMBER_CONFIG = _identifier_config(
    "official",
    ABHA_NUMBER_SYSTEM,
    "ABHA Number",
    "Ayushman Bharat Health Account number (14 digits)",
    ABHA_NUMBER_REGEX,
)
ABHA_ADDRESS_CONFIG = _identifier_config(
    "secondary",
    ABHA_ADDRESS_SYSTEM,
    "ABHA Address",
    "Ayushman Bharat Health Account address",
    ABHA_ADDRESS_REGEX,
)


def abha_digits(value) -> str:
    return re.sub(r"\D", "", value or "")


def _get_config(system: str, config: dict) -> PatientIdentifierConfig:
    found = PatientIdentifierConfig.objects.filter(
        facility__isnull=True, config__system=system
    ).first()
    if found:
        return found
    created = PatientIdentifierConfig.objects.create(
        facility=None, status="active", config=config
    )
    PatientIdentifierConfigCache.clear_cache()
    return created


def get_abha_number_config() -> PatientIdentifierConfig:
    return _get_config(ABHA_NUMBER_SYSTEM, ABHA_NUMBER_CONFIG)


def get_abha_address_config() -> PatientIdentifierConfig:
    return _get_config(ABHA_ADDRESS_SYSTEM, ABHA_ADDRESS_CONFIG)


def _value(patient, system: str) -> str | None:
    identifier = (
        PatientIdentifier.objects.filter(
            patient=patient, config__facility__isnull=True, config__config__system=system
        )
        .order_by("-modified_date")
        .first()
    )
    return identifier.value if identifier else None


def get_abha_number(patient) -> str | None:
    """The patient's ABHA number as stored (with or without dashes)."""
    return _value(patient, ABHA_NUMBER_SYSTEM)


def get_abha_address(patient) -> str | None:
    return _value(patient, ABHA_ADDRESS_SYSTEM)


def _digits_only(expression):
    return models.Func(
        expression,
        models.Value(r"[^0-9]"),
        models.Value(""),
        models.Value("g"),
        function="regexp_replace",
        output_field=models.CharField(),
    )


def find_patients_by_abha(number):
    """Patients whose ABHA number equals ``number``, compared digits only."""
    digits = abha_digits(number)
    if not digits:
        return Patient.objects.none()
    patient_ids = (
        PatientIdentifier.objects.filter(
            config__facility__isnull=True, config__config__system=ABHA_NUMBER_SYSTEM
        )
        .annotate(digits=_digits_only(models.F("value")))
        .filter(digits=digits)
        .values("patient_id")
    )
    return Patient.objects.filter(id__in=patient_ids)


def _put(patient, config, value):
    identifier = PatientIdentifier.objects.filter(patient=patient, config=config).first()
    if not value:
        if identifier:
            identifier.delete()
        return
    if identifier:
        identifier.value = value
        identifier.save(update_fields=["value", "modified_date"])
    else:
        PatientIdentifier.objects.create(patient=patient, config=config, value=value)


def set_abha(patient, number=None, address=None):
    """Write the patient's ABHA number and/or address (``None`` leaves it as
    is, ``""`` removes it) and rebuild the patient's identifier cache.

    Raises ``ValueError`` with the spec's message when another patient holds
    the same ABHA number.
    """
    with transaction.atomic():
        if number is not None:
            if number and find_patients_by_abha(number).exclude(id=patient.id).exists():
                raise ValueError(DUPLICATE_ABHA_MESSAGE)
            _put(patient, get_abha_number_config(), number.strip())
        if address is not None:
            _put(patient, get_abha_address_config(), address.strip())
        patient.build_instance_identifiers()
        patient.save()

"""G2. Configuration and participants."""

from __future__ import annotations

import json
import os
import re
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any
from urllib.parse import urlparse

from care.nhcx.gateway import crypto
from care.nhcx.gateway.headers import normalize_code

DEFAULT_MAX_BODY = 100 * 1024 * 1024
DEFAULT_TIMEOUT = 30
DEFAULT_TOKEN_TTL = 1200
DEFAULT_CERT_HOURS = 24
DEFAULT_LEDGER_DIR = "data/ledger"

ENV_TABLE = {
    "sandbox": {
        "nhcx": "https://apisbx.abdm.gov.in/hcx/v1",
        "participant": "https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice",
        "sessions": "https://dev.abdm.gov.in/api/hiecm/gateway/v3/sessions",
        "cmId": "sbx",
    },
    "production": {
        "nhcx": "",
        "participant": "https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice",
        "sessions": "https://apis.abdm.gov.in/api/hiecm/gateway/v3/sessions",
        "cmId": "abdm",
    },
}

ENV_OVERRIDES = (
    ("NHCX_ENV", ("env",)),
    ("NHCX_URL", ("urls", "nhcx")),
    ("NHCX_PARTICIPANT_URL", ("urls", "participant")),
    ("NHCX_SESSIONS_URL", ("urls", "sessions")),
    ("NHCX_PUBLIC_URL", ("publicUrl",)),
    ("NHCX_CM_ID", ("cmId",)),
)

KEY_HINT = (
    "  generate one with: openssl genpkey -algorithm RSA -pkeyopt "
    "rsa_keygen_bits:2048 -out nhcx-private.pem"
)

# Strict schema. `None` accepts any JSON value: the standalone-only keys the
# embedded gateway carries but neither reads nor validates (G2D).
_ANY = None
_PARTICIPANT = {
    "participantId": str,
    "name": str,
    "clientId": str,
    "clientSecret": str,
    "privateKey": str,
    "callback": _ANY,
    "callbackUrl": _ANY,
}
_SCHEMA = {
    "env": str,
    "publicUrl": str,
    "cmId": str,
    "participant": _PARTICIPANT,
    "participants": [_PARTICIPANT],
    "guests": {"callback": _ANY},
    "ledger": {
        "enabled": bool,
        "dir": str,
        "retentionDays": int,
        "storeBodies": bool,
    },
    "certs": {"cacheHours": (int, float), "refuseSelfKey": bool},
    "outboundTimeoutSeconds": (int, float),
    "maxBodyBytes": int,
    "auth": {"mode": str, "tokenTtlSeconds": int},
    "urls": {"nhcx": str, "participant": str, "sessions": str},
    "log": {"level": str, "format": _ANY},
    "callback": _ANY,
    "apiKey": str,
    "requireApiKey": _ANY,
    "listen": _ANY,
    "tls": _ANY,
    "panel": _ANY,
    "certificate": _ANY,
}

_VAR_RE = re.compile(r"\$\{([A-Za-z_][A-Za-z0-9_]*)\}")


class ConfigError(Exception):
    pass


def _check(value: Any, schema: Any, where: str) -> None:
    """Reject unknown keys and wrong types. `$comment` keys are allowed anywhere."""
    if schema is _ANY:
        return
    if isinstance(schema, dict):
        if not isinstance(value, dict):
            msg = f"{where or 'config'}: expected an object"
            raise ConfigError(msg)
        for k, v in value.items():
            if k.startswith("$comment"):
                continue
            if k not in schema:
                msg = f'unknown field "{k}"' + (f" in {where}" if where else "")
                raise ConfigError(msg)
            _check(v, schema[k], f"{where}.{k}" if where else k)
        return
    if isinstance(schema, list):
        if not isinstance(value, list):
            msg = f"{where}: expected an array"
            raise ConfigError(msg)
        for i, item in enumerate(value):
            _check(item, schema[0], f"{where}[{i}]")
        return
    types = schema if isinstance(schema, tuple) else (schema,)
    if value is None:
        return
    if isinstance(value, bool) and bool not in types:
        msg = f"{where}: wrong type"
        raise ConfigError(msg)
    if not isinstance(value, types):
        msg = f"{where}: wrong type"
        raise ConfigError(msg)


@dataclass
class ParticipantEntry:
    participantId: str = ""  # noqa: N815
    name: str = ""
    clientId: str = ""  # noqa: N815
    clientSecret: str = ""  # noqa: N815
    privateKey: str = ""  # noqa: N815

    @classmethod
    def from_dict(cls, d: dict | None) -> ParticipantEntry:
        d = d or {}
        return cls(
            participantId=d.get("participantId") or "",
            name=d.get("name") or "",
            clientId=d.get("clientId") or "",
            clientSecret=d.get("clientSecret") or "",
            privateKey=d.get("privateKey") or "",
        )


@dataclass
class Config:
    path: str = ""
    env: str = ""
    publicUrl: str = ""  # noqa: N815
    cmId: str = ""  # noqa: N815
    participant: ParticipantEntry = field(default_factory=ParticipantEntry)
    participants: list[ParticipantEntry] = field(default_factory=list)
    guests: bool = False
    ledger_enabled: bool = True
    ledger_dir: str = ""
    ledger_retention_days: int = 0
    ledger_store_bodies: bool = True
    cert_cache_hours: float = 0
    refuse_self_key: bool | None = None
    outbound_timeout: float = 0
    max_body_bytes: int = 0
    auth_mode: str = ""
    token_ttl_seconds: int = 0
    url_nhcx: str = ""
    url_participant: str = ""
    url_sessions: str = ""
    log_level: str = ""
    api_key: str = ""

    def all_participants(self) -> list[ParticipantEntry]:
        out = [self.participant]
        d = self.participant
        for p in self.participants:
            q = ParticipantEntry(**p.__dict__)
            if q.clientId == "" and q.clientSecret == "":
                q.clientId, q.clientSecret = d.clientId, d.clientSecret
            if q.privateKey.strip() == "":
                q.privateKey = d.privateKey
            out.append(q)
        return out

    def codes(self) -> list[str]:
        return [p.participantId for p in self.all_participants() if p.participantId]


def _expand(raw: str) -> tuple[str, list[str]]:
    missing: list[str] = []

    def sub(m: re.Match) -> str:
        name = m.group(1)
        if name not in os.environ:
            if name not in missing:
                missing.append(name)
            return ""
        return json.dumps(os.environ[name])[1:-1]

    return _VAR_RE.sub(sub, raw), missing


def _num(v: Any, default: float) -> Any:
    return v if isinstance(v, (int, float)) and not isinstance(v, bool) and v > 0 else default


def load_config(path: str | os.PathLike) -> Config:
    path = str(path)
    try:
        raw = Path(path).read_text(encoding="utf-8")
    except OSError as e:
        msg = f"read config: {e}"
        raise ConfigError(msg) from e
    text, missing = _expand(raw)
    if missing:
        msg = f"{path}: environment variable(s) not set: {', '.join(missing)}"
        raise ConfigError(msg)
    try:
        data = json.loads(text)
        _check(data, _SCHEMA, "")
    except (ValueError, ConfigError) as e:
        msg = f"{path}: parse config: {e}"
        raise ConfigError(msg) from e

    for var, fld in ENV_OVERRIDES:
        if var in os.environ:
            target = data
            for k in fld[:-1]:
                target = target.setdefault(k, {})
            target[fld[-1]] = os.environ[var].strip()

    cfg = _apply_defaults(path, data)

    base = Path(path).resolve().parent
    entries = [("participant", cfg.participant)] + [
        (f"participants[{i}]", p) for i, p in enumerate(cfg.participants)
    ]
    for label, entry in entries:
        key = entry.privateKey.strip()
        if key.startswith("@"):
            p = Path(key[1:])
            if not p.is_absolute():
                p = base / p
            try:
                entry.privateKey = p.read_text(encoding="utf-8")
            except OSError as e:
                msg = f"{label}.privateKey: {e}"
                raise ConfigError(msg) from e

    errors = validate(cfg)
    if errors:
        raise ConfigError(f"{path}: " + "\n".join(errors))
    return cfg


def _apply_defaults(path: str, data: dict) -> Config:
    ledger = data.get("ledger") or {}
    certs = data.get("certs") or {}
    auth = data.get("auth") or {}
    urls = data.get("urls") or {}
    log = data.get("log") or {}
    env = (data.get("env") or "").strip().lower() or "sandbox"
    table = ENV_TABLE["production" if env == "production" else "sandbox"]
    ledger_dir = (ledger.get("dir") or "").strip() or DEFAULT_LEDGER_DIR
    if not Path(ledger_dir).is_absolute():
        ledger_dir = str(Path(path).resolve().parent / ledger_dir)
    retention = ledger.get("retentionDays") or 0
    cfg = Config(
        path=path,
        env=env,
        publicUrl=(data.get("publicUrl") or "").strip(),
        cmId=(data.get("cmId") or "").strip() or table["cmId"],
        participant=ParticipantEntry.from_dict(data.get("participant")),
        participants=[ParticipantEntry.from_dict(p) for p in data.get("participants") or []],
        guests=isinstance(data.get("guests"), dict),
        ledger_enabled=ledger.get("enabled") is not False,
        ledger_dir=ledger_dir,
        ledger_retention_days=max(retention, 0),
        ledger_store_bodies=ledger.get("storeBodies") is not False,
        cert_cache_hours=_num(certs.get("cacheHours"), DEFAULT_CERT_HOURS),
        refuse_self_key=certs.get("refuseSelfKey"),
        outbound_timeout=_num(data.get("outboundTimeoutSeconds"), DEFAULT_TIMEOUT),
        max_body_bytes=_num(data.get("maxBodyBytes"), DEFAULT_MAX_BODY),
        auth_mode=(auth.get("mode") or "").strip() or "sessions",
        token_ttl_seconds=_num(auth.get("tokenTtlSeconds"), DEFAULT_TOKEN_TTL),
        url_nhcx=(urls.get("nhcx") or "").strip() or table["nhcx"],
        url_participant=(urls.get("participant") or "").strip() or table["participant"],
        url_sessions=(urls.get("sessions") or "").strip(),
        log_level=(log.get("level") or "").strip() or "info",
        api_key=(data.get("apiKey") or "").strip(),
    )
    if cfg.refuse_self_key is None:
        cfg.refuse_self_key = env == "production"
    if cfg.url_sessions == "":
        cfg.url_sessions = (
            cfg.url_participant.rstrip("/") + "/get/session"
            if cfg.auth_mode == "get-session"
            else table["sessions"]
        )
    for p in [cfg.participant, *cfg.participants]:
        p.participantId = normalize_code(p.participantId.strip())
    return cfg


def url_error(u: str) -> str | None:
    if not u:
        return "is required"
    try:
        parsed = urlparse(u)
    except ValueError:
        parsed = None
    if parsed is None or parsed.scheme not in ("http", "https") or not parsed.netloc:
        return f'"{u}" is not an absolute http(s) URL'
    return None


def validate(cfg: Config) -> list[str]:
    errs: list[str] = []
    if cfg.env not in ("sandbox", "production"):
        errs.append(f'env must be "sandbox" or "production", got "{cfg.env}"')
    d = cfg.participant
    if not d.participantId:
        errs.append("participant.participantId is required")
    if not d.clientId or not d.clientSecret:
        errs.append("participant.clientId and participant.clientSecret are required")
    if not d.privateKey.strip():
        errs.append(
            "participant.privateKey is required (PEM, base64 PEM, or @file)\n" + KEY_HINT
        )
    else:
        try:
            crypto.parse_private_key(d.privateKey)
        except crypto.CryptoError as e:
            errs.append(f"participant.privateKey is not a valid RSA private key: {e}")
    seen: dict[str, int] = {}
    for i, p in enumerate(cfg.participants):
        code = p.participantId
        if not code:
            errs.append(f"participants[{i}].participantId is required")
        else:
            low = code.lower()
            if d.participantId and low == d.participantId.lower():
                errs.append(
                    f"participants[{i}].participantId {code} duplicates participant.participantId"
                )
            elif low in seen:
                errs.append(
                    f"participants[{i}].participantId {code} duplicates participants[{seen[low]}]"
                )
            else:
                seen[low] = i
        if p.privateKey.strip():
            try:
                crypto.parse_private_key(p.privateKey)
            except crypto.CryptoError as e:
                errs.append(
                    f"participants[{i}].privateKey is not a valid RSA private key: {e}"
                )
        if bool(p.clientId) != bool(p.clientSecret):
            errs.append(
                f"participants[{i}]: clientId and clientSecret must be set together "
                "(or both left blank to inherit)"
            )
    if cfg.auth_mode not in ("sessions", "get-session"):
        errs.append(f'auth.mode must be "sessions" or "get-session", got "{cfg.auth_mode}"')
    for name, u in (
        ("urls.nhcx", cfg.url_nhcx),
        ("urls.participant", cfg.url_participant),
        ("urls.sessions", cfg.url_sessions),
    ):
        e = url_error(u)
        if e:
            errs.append(f"{name}: {e}")
    if cfg.log_level.lower() not in ("debug", "info", "warn", "warning", "error"):
        errs.append(f'log.level must be debug, info, warn or error, got "{cfg.log_level}"')
    return errs


def validate_serve(cfg: Config) -> list[str]:
    if cfg.publicUrl:
        e = url_error(cfg.publicUrl)
        if e:
            return [f"publicUrl: {e}"]
    return []


@dataclass
class Profile:
    participant: ParticipantEntry
    key: Any
    default: bool

    @property
    def code(self) -> str:
        return self.participant.participantId

    @property
    def public_key(self) -> Any:
        return self.key.public_key()


class Profiles:
    def __init__(self, profiles: list[Profile]):
        self.profiles = profiles
        self.default = profiles[0]
        self._index = {p.code.lower(): p for p in profiles if p.code}

    def __iter__(self):
        return iter(self.profiles)

    def codes(self) -> list[str]:
        return [p.code for p in self.profiles if p.code]

    def by_code(self, code: Any) -> Profile | None:
        c = normalize_code(code)
        return self._index.get(c.lower()) if c else None

    def resolve(self, code: Any) -> Profile:
        return self.by_code(code) or self.default

    def is_local(self, code: Any) -> bool:
        return self.by_code(code) is not None

    def owns_key(self, public_key: Any) -> bool:
        if public_key is None:
            return False
        return any(
            crypto.public_numbers_equal(p.public_key, public_key) for p in self.profiles
        )


def build_profiles(cfg: Config) -> Profiles:
    parsed: dict[str, Any] = {}
    out: list[Profile] = []
    for i, entry in enumerate(cfg.all_participants()):
        label = "participant" if i == 0 else f"participants[{i - 1}]"
        key = parsed.get(entry.privateKey)
        if key is None:
            try:
                key = crypto.parse_private_key(entry.privateKey)
            except crypto.CryptoError as e:
                msg = f"{label}.privateKey: {e}"
                raise ConfigError(msg) from e
            parsed[entry.privateKey] = key
        out.append(Profile(participant=entry, key=key, default=i == 0))
    return Profiles(out)

"""G3. Session token: one ABDM session per client id, and the authenticated POST."""

from __future__ import annotations

import hashlib
import json
import logging
import threading
import time
import uuid
from datetime import UTC, datetime
from typing import Any

import requests

from care.nhcx.gateway.errors import GatewayError, clip, retryable_status

logger = logging.getLogger("care.nhcx.gateway")

FRESH_MARGIN = 60.0
HTTP_UNAUTHORIZED = 401


def utc_ms_timestamp(now: datetime | None = None) -> str:
    now = now or datetime.now(UTC)
    return now.strftime("%Y-%m-%dT%H:%M:%S.") + f"{now.microsecond // 1000:03d}Z"


def _first_string(out: dict, *keys: str) -> str:
    for k in keys:
        v = out.get(k)
        if isinstance(v, str) and v.strip():
            return v.strip()
    return ""


def _first_number(out: dict, *keys: str) -> float:
    for k in keys:
        v = out.get(k)
        if isinstance(v, bool):
            continue
        if isinstance(v, (int, float)):
            return float(v)
        if isinstance(v, str):
            try:
                return float(v.strip())
            except ValueError:
                continue
    return 0.0


class TokenCache:
    """In-memory token map, guarded by one lock (G3D).

    `shared` is an optional Django-cache-like store (`get`/`set`) so the
    refresher in one process (the Celery role) warms the token for the web
    workers; nothing else is persisted.
    """

    def __init__(self, shared: Any = None):
        self.lock = threading.RLock()
        self.tokens: dict[str, tuple[str, float]] = {}
        self.shared = shared

    @staticmethod
    def _shared_key(key: str) -> str:
        return "nhcx:token:" + hashlib.sha256(key.encode()).hexdigest()

    def get(self, key: str) -> tuple[str, float] | None:
        e = self.tokens.get(key)
        if self.shared is not None and (e is None or e[1] - time.time() <= FRESH_MARGIN):
            try:
                s = self.shared.get(self._shared_key(key))
            except Exception:  # noqa: BLE001
                s = None
            if isinstance(s, (list, tuple)) and len(s) == 2 and (e is None or s[1] > e[1]):  # noqa: PLR2004
                e = (s[0], float(s[1]))
                self.tokens[key] = e
        return e

    def put(self, key: str, token: str, expires: float) -> None:
        self.tokens[key] = (token, expires)
        if self.shared is not None:
            try:
                self.shared.set(
                    self._shared_key(key),
                    (token, expires),
                    timeout=max(int(expires - time.time()), 1),
                )
            except Exception:  # noqa: BLE001
                logger.warning("nhcx: shared token cache unavailable", exc_info=True)


class AbdmClient:
    """The ABDM client acting as one profile (G2 `identity_for`)."""

    def __init__(self, gateway_ctx: Any, profile: Any):
        self.ctx = gateway_ctx
        self.profile = profile

    @property
    def code(self) -> str:
        return self.profile.code

    @property
    def cfg(self):
        return self.ctx.cfg

    def credentials(self) -> tuple[str, str, str]:
        cid, secret = self.profile.participant.clientId, self.profile.participant.clientSecret
        if cid == "":
            d = self.cfg.participant
            cid, secret = d.clientId, d.clientSecret
        key = cid if cid != "" else "\0" + self.code
        return cid, secret, key

    # ---- tokens ----

    def token(self) -> str:
        cache = self.ctx.tokens
        with cache.lock:
            _, _, key = self.credentials()
            e = cache.get(key)
            if e and e[0] and e[1] - time.time() > FRESH_MARGIN:
                return e[0]
            return self._fetch_locked()

    def refresh_token(self) -> str:
        with self.ctx.tokens.lock:
            return self._fetch_locked()

    def token_info(self) -> tuple[str, float]:
        self.token()
        cache = self.ctx.tokens
        with cache.lock:
            _, _, key = self.credentials()
            return cache.tokens[key]

    def token_valid(self) -> bool:
        cache = self.ctx.tokens
        with cache.lock:
            _, _, key = self.credentials()
            e = cache.get(key)
        return bool(e and e[0] and time.time() < e[1])

    def _fetch_locked(self) -> str:
        cfg = self.cfg
        cid, secret, key = self.credentials()
        started = time.monotonic()
        headers = {"Accept": "application/json"}
        try:
            if cfg.auth_mode == "get-session":
                headers["Content-Type"] = "application/x-www-form-urlencoded"
                kwargs = {
                    "data": {
                        "client_id": cid,
                        "client_secret": secret,
                        "grant_type": "client_credentials",
                    }
                }
            else:
                headers.update(
                    {
                        "Content-Type": "application/json",
                        "REQUEST-ID": str(uuid.uuid4()),
                        "TIMESTAMP": utc_ms_timestamp(),
                        "X-CM-ID": cfg.cmId,
                    }
                )
                kwargs = {
                    "data": json.dumps(
                        {
                            "clientId": cid,
                            "clientSecret": secret,
                            "grantType": "client_credentials",
                        }
                    )
                }
        except (TypeError, ValueError) as e:
            raise GatewayError("TOKEN_REQUEST", "build session request", cause=e) from e
        try:
            resp = self.ctx.http.post(
                cfg.url_sessions, headers=headers, timeout=cfg.outbound_timeout, **kwargs
            )
        except requests.RequestException as e:
            raise GatewayError(
                "TOKEN_UNREACHABLE",
                "session endpoint unreachable",
                retryable=True,
                cause=e,
            ) from e
        raw = resp.content
        status = resp.status_code
        if not 200 <= status < 300:  # noqa: PLR2004
            raise GatewayError(
                f"TOKEN_HTTP_{status}",
                "session endpoint rejected the credentials",
                retryable=retryable_status(status),
                status=status,
                body=clip(raw),
            )
        try:
            out = json.loads(raw)
            if not isinstance(out, dict):
                raise ValueError("not an object")  # noqa: TRY301, EM101
        except ValueError as e:
            raise GatewayError(
                "TOKEN_BAD_JSON",
                "session response is not JSON",
                retryable=True,
                status=status,
                body=clip(raw),
                cause=e,
            ) from e
        token = _first_string(out, "accessToken", "access_token")
        if token == "":
            raise GatewayError(
                "TOKEN_MISSING", "session response carried no access token", status=status
            )
        ttl = float(cfg.token_ttl_seconds)
        n = _first_number(out, "expiresIn", "expires_in")
        if n > 0:
            ttl = n
        self.ctx.tokens.put(key, token, time.time() + ttl)
        logger.info(
            "nhcx: session token refreshed participant=%s mode=%s ttl=%s took_ms=%d",
            self.code,
            cfg.auth_mode,
            int(ttl),
            int((time.monotonic() - started) * 1000),
        )
        return token

    # ---- authenticated POST ----

    def post_with_token(
        self, url: str, body: Any, label: str = "CERT_FETCH"
    ) -> tuple[int, bytes]:
        try:
            payload = json.dumps(body)
        except (TypeError, ValueError) as e:
            raise GatewayError("MARSHAL_ERROR", "encode request body", cause=e) from e
        for attempt in (0, 1):
            token = self.token()
            headers = {
                "Content-Type": "application/json",
                "Accept": "application/json",
                "bearer_auth": "Bearer " + token,
                "Authorization": "Bearer " + token,
            }
            try:
                resp = self.ctx.http.post(
                    url, data=payload, headers=headers, timeout=self.cfg.outbound_timeout
                )
            except (requests.exceptions.InvalidURL, requests.exceptions.MissingSchema) as e:
                raise GatewayError(f"{label}_REQUEST", "build request", cause=e) from e
            except requests.RequestException as e:
                raise GatewayError(
                    f"{label}_UNREACHABLE", f"{url} unreachable", retryable=True, cause=e
                ) from e
            try:
                raw = resp.content
            except Exception as e:  # noqa: BLE001
                raise GatewayError(
                    f"{label}_READ_ERROR", "read response", retryable=True, cause=e
                ) from e
            if resp.status_code == HTTP_UNAUTHORIZED and attempt == 0:
                logger.warning("nhcx: upstream answered 401, refreshing session token")
                self.refresh_token()
                continue
            return resp.status_code, raw
        return resp.status_code, raw  # pragma: no cover


def token_payload(client: AbdmClient, token: str, expires: float) -> dict:
    exp = datetime.fromtimestamp(expires, UTC).replace(microsecond=0)
    return {
        "token": token,
        "token_type": "Bearer",
        "expires_at": exp.strftime("%Y-%m-%dT%H:%M:%SZ"),
        "expires_in": max(int(expires - time.time()), 0),
        "participant": client.code,
    }

"""F1 Bundle: message kinds, wrapping, unwrapping and shared value helpers."""

import base64
import copy
import json
import uuid
from datetime import UTC, date, datetime, timedelta, timezone
from decimal import ROUND_HALF_UP, Decimal

from care.nhcx.fhir.codes import BASE_URL, PROFILES

IST = timezone(timedelta(hours=5, minutes=30))

# kind -> (bundle id, bundle profile, anchor path)
KINDS = {
    "coverage-validation": (
        "coverage-validation-request-generic",
        "CoverageEligibilityRequestBundle",
        "/coverage-eligibility/request",
    ),
    "coverage-benefits": (
        "coverage-benefits-request-generic",
        "CoverageEligibilityRequestBundle",
        "/coverage-eligibility/request",
    ),
    "coverage-discovery": (
        "coverage-discovery-request-generic",
        "CoverageEligibilityRequestBundle",
        "/coverage-eligibility/request",
    ),
    "coverage-auth-requirements": (
        "coverage-authrequirements-request-generic",
        "CoverageEligibilityRequestBundle",
        "/coverage-eligibility/request",
    ),
    "insurance-plan": ("insurance-request-generic", "TaskBundle", "/insurance/request"),
    "preauth": ("preauth-request-generic", "ClaimBundle", "/preauth/request"),
    "enhancement": (
        "preauth-enhancement-request-generic",
        "ClaimBundle",
        "/preauth/enhancement",
    ),
    "preauth-queryupdate": (
        "preauth-queryupdate-request-generic",
        "ClaimBundle",
        "/preauth/queryupdate",
    ),
    "predetermination": (
        "predetermination-request-generic",
        "ClaimBundle",
        "/predetermination/request",
    ),
    "claim": ("claim-request-generic", "ClaimBundle", "/claim/request"),
    "claim-queryupdate": (
        "claim-queryupdate-request-generic",
        "ClaimBundle",
        "/claim/queryupdate",
    ),
    "preauth-cancel": ("preauth-cancel-request-generic", "TaskBundle", "/preauth/cancel"),
    "preauth-status": ("preauth-status-request-generic", "TaskBundle", "/preauth/status"),
    "claim-status": ("claim-status-request-generic", "TaskBundle", "/claim/status"),
    "claim-reprocess": (
        "claim-reprocess-request-generic",
        "TaskBundle",
        "/claim/reprocess",
    ),
    "claim-release": ("claim-release-request-generic", "TaskBundle", "/claim/release"),
    "payment-ack": ("payment-notice-ack-generic", "TaskBundle", "/payment/notice-ack"),
}


def url(path):
    """Absolute NHCX fullUrl / reference for a path such as /patient."""
    return BASE_URL + (path if path.startswith("/") else "/" + path)


def ref(path, display=None):
    out = {"reference": url(path)}
    if display:
        out["display"] = display
    return out


def anchor_url(kind):
    return url(KINDS[kind][2])


def wrap(kind, entries):
    """Wrap (path, resource) pairs into the kind's collection bundle.

    The anchor resource must come first; it is given the anchor fullUrl.
    Other paths are made absolute under https://nhcx.abdm.gov.in.
    """
    bundle_id, bundle_profile, anchor = KINDS[kind]
    out = []
    for i, (path, resource) in enumerate(entries):
        full_url = url(anchor if i == 0 else path)
        out.append({"fullUrl": full_url, "resource": resource})
    return {
        "resourceType": "Bundle",
        "id": bundle_id,
        "meta": {"profile": [PROFILES[bundle_profile]]},
        "type": "collection",
        "entry": out,
    }


def unwrap(payload):
    """Return the bundle dict from a dict or JSON text (a ProtocolResponse too)."""
    if isinstance(payload, bytes | bytearray):
        payload = payload.decode()
    if isinstance(payload, str):
        payload = json.loads(payload) if payload.strip() else {}
    return payload or {}


def entries(bundle):
    return [e for e in (unwrap(bundle).get("entry") or []) if isinstance(e, dict)]


def find_resources(bundle, resource_type):
    return [
        e["resource"]
        for e in entries(bundle)
        if isinstance(e.get("resource"), dict)
        and e["resource"].get("resourceType") == resource_type
    ]


def find_resource(bundle, resource_type, last=False):
    found = find_resources(bundle, resource_type)
    if not found:
        return None
    return found[-1] if last else found[0]


def find_entry(bundle, resource_type, last=False):
    found = [
        e
        for e in entries(bundle)
        if (e.get("resource") or {}).get("resourceType") == resource_type
    ]
    if not found:
        return None
    return found[-1] if last else found[0]


def resolve_reference(bundle, reference):
    """Find the resource a reference points at, by fullUrl or by id."""
    if isinstance(reference, dict):
        reference = reference.get("reference")
    if not reference:
        return None
    for e in entries(bundle):
        if e.get("fullUrl") == reference:
            return e.get("resource")
    key = reference.removeprefix("urn:uuid:")
    tail = key.rstrip("/").rsplit("/", 1)[-1]
    for e in entries(bundle):
        res = e.get("resource") or {}
        rid = str(res.get("id") or "")
        if rid and (rid == key or rid == tail):
            return res
    return None


def is_protocol_response(payload):
    payload = unwrap(payload)
    return payload.get("type") == "ProtocolResponse" or (
        "x-hcx-error_details" in payload and payload.get("resourceType") != "Bundle"
    )


def protocol_error(payload):
    """'<code>: <message>' of a ProtocolResponse, else ''."""
    payload = unwrap(payload)
    details = payload.get("x-hcx-error_details") or {}
    if isinstance(details, str):
        try:
            details = json.loads(details)
        except ValueError:
            return details
    code = details.get("code") or ""
    message = details.get("message") or ""
    return f"{code}: {message}" if code and message else (code or message)


# value helpers


def new_uuid():
    return str(uuid.uuid4())


def _parse(value):
    if value is None or value == "":
        return None
    if isinstance(value, datetime):
        return value
    if isinstance(value, date):
        return datetime(value.year, value.month, value.day, tzinfo=IST)
    text = str(value).strip()
    if len(text) == 10:
        return datetime.fromisoformat(text).replace(tzinfo=IST)
    return datetime.fromisoformat(text.replace("Z", "+00:00"))


def to_instant(value):
    """YYYY-MM-DDThh:mm:ss+05:30; a bare date becomes midnight IST."""
    moment = _parse(value)
    if moment is None:
        return None
    if moment.tzinfo is None:
        moment = moment.replace(tzinfo=IST)
    return moment.astimezone(IST).replace(microsecond=0).isoformat()


def to_date(value):
    """YYYY-MM-DD (IST calendar date)."""
    instant = to_instant(value)
    return instant[:10] if instant else None


def now_instant():
    return to_instant(datetime.now(UTC))


def amount(value):
    """Round to 2 decimals; an int when whole."""
    if value is None or value == "":
        return None
    number = Decimal(str(value)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return int(number) if number == number.to_integral_value() else float(number)


def money(value):
    return {"value": amount(value) or 0, "currency": "INR"}


def b64(data):
    if data is None:
        return ""
    if isinstance(data, str):
        return data
    return base64.b64encode(bytes(data)).decode()


def deep_copy(value):
    return copy.deepcopy(value)

"""G4. Registry and certificates."""

from __future__ import annotations

import json
import logging
import threading
import time
from typing import Any

from care.nhcx.gateway import crypto
from care.nhcx.gateway.errors import GatewayError, clip, retryable_status
from care.nhcx.gateway.headers import normalize_code, same_code
from care.nhcx.gateway.token import AbdmClient

logger = logging.getLogger("care.nhcx.gateway")


class CertCache:
    """Shared by every profile; keyed by lowercased code. Failures are never cached."""

    def __init__(self):
        self.lock = threading.Lock()
        self.entries: dict[str, dict] = {}


def _first(rec: dict, *keys: str) -> str:
    for k in keys:
        v = rec.get(k)
        if isinstance(v, str) and v.strip():
            return v.strip()
    return ""


def _code_of(rec: Any) -> str:
    if not isinstance(rec, dict):
        return ""
    return _first(rec, "participant_code", "participantcode", "participantid")


def _ok(status: int) -> bool:
    return 200 <= status < 300  # noqa: PLR2004


def _parse_object(raw: bytes) -> dict | None:
    try:
        out = json.loads(raw)
    except (ValueError, TypeError):
        return None
    return out if isinstance(out, dict) else None


class RegistryClient(AbdmClient):
    def _registry_url(self, path: str) -> str:
        return self.cfg.url_participant.rstrip("/") + "/" + path.lstrip("/")

    def certificate(self, code: Any) -> tuple[Any, str]:
        code = normalize_code(code)
        if code == "":
            raise GatewayError("NO_RECIPIENT", "participant code is empty")
        cache = self.ctx.certs
        with cache.lock:
            entry = cache.entries.get(code.lower())
        if entry and time.time() < entry["expires"]:
            return entry["key"], entry["pem"]
        return self.fetch_certificate(code)

    def fetch_certificate(self, code: Any) -> tuple[Any, str]:
        code = normalize_code(code)
        if code == "":
            raise GatewayError("NO_RECIPIENT", "participant code is empty")
        status, raw = self.post_with_token(
            self._registry_url("/fetch/certs"), {"participantid": code}, "CERT_FETCH"
        )
        if not _ok(status):
            raise GatewayError(
                f"CERT_FETCH_HTTP_{status}",
                f"participant registry refused the certificate lookup for {code}",
                retryable=retryable_status(status),
                status=status,
                body=clip(raw),
            )
        out = _parse_object(raw)
        if out is None:
            raise GatewayError(
                "CERT_FETCH_BAD_JSON",
                "registry response is not JSON",
                retryable=True,
                status=status,
                body=clip(raw),
            )
        pem = _first(out, "encryption_cert", "encryptionCert", "cert")
        if pem == "":
            raise GatewayError(
                "CERT_NOT_FOUND", f"registry returned no encryption certificate for {code}"
            )
        try:
            pub = crypto.parse_public_key(pem)
        except crypto.CryptoError as e:
            raise GatewayError(
                "CERT_NOT_FOUND",
                f"registry returned no usable certificate for {code}: "
                + json.dumps(pem[:120], ensure_ascii=False),
                cause=e,
            ) from e
        profiles = self.ctx.profiles
        if profiles.owns_key(pub) and not profiles.is_local(code):
            if self.cfg.refuse_self_key:
                raise GatewayError(
                    "SELF_ENCRYPTION_KEY",
                    f"registry certificate for {code} is this adapter's own key; "
                    "a payload encrypted with it would be unreadable at the far end",
                )
            logger.warning(
                "nhcx: registry certificate is this adapter's own key participant=%s", code
            )
        with self.ctx.certs.lock:
            self.ctx.certs.entries[code.lower()] = {
                "pem": pem,
                "key": pub,
                "expires": time.time() + self.cfg.cert_cache_hours * 3600,
            }
        logger.info("nhcx: certificate fetched participant=%s", code)
        return pub, pem

    def forget_certificate(self, code: Any) -> None:
        with self.ctx.certs.lock:
            self.ctx.certs.entries.pop(normalize_code(code).lower(), None)

    def own_key(self) -> Any:
        return self.profile.public_key if self.profile else None

    def fetch_participant(self, code: Any) -> dict:
        code = normalize_code(code)
        status, raw = self.post_with_token(
            self._registry_url("/participant/search"),
            {"participant_code": code, "participantcode": code, "participantid": code},
            "CERT_FETCH",
        )
        if not _ok(status):
            raise GatewayError(
                f"PARTICIPANT_HTTP_{status}",
                f"participant registry refused the search for {code}",
                retryable=retryable_status(status),
                status=status,
                body=clip(raw),
            )
        out = _parse_object(raw)
        if out is None:
            raise GatewayError(
                "PARTICIPANT_BAD_JSON",
                "registry response is not JSON",
                status=status,
                body=clip(raw),
            )
        rec: Any = out
        if isinstance(out.get("participants"), list):
            items = out["participants"]
            rec = next((r for r in items if same_code(_code_of(r), code)), None)
            if rec is None and items:
                rec = items[0]
        if rec is None or _code_of(rec) == "":
            raise GatewayError("PARTICIPANT_NOT_FOUND", f"registry has no record for {code}")
        roles = [r for r in rec.get("roles") or [] if isinstance(r, str)] if isinstance(
            rec.get("roles"), list
        ) else []
        if not roles and isinstance(rec.get("role_code"), list):
            roles = [r for r in rec["role_code"] if isinstance(r, str)]
        return {
            "code": normalize_code(_code_of(rec)),
