ITEM_PURPOSES = {"benefits", "auth-requirements"}


def _is_tier(line):
    return (line.kind or "").lower() == "stratification"


def _quantity(value):
    return fb.amount(value if value not in (None, "") else 1)


def _items(lines, tier_offers):
    procedures = [ln for ln in lines if not _is_tier(ln)]
    riders = {id(p): [] for p in procedures}
    loose = []
    for tier in (ln for ln in lines if _is_tier(ln)):
        host = next((p for p in procedures if p.code == tier.parent_code), None)
        if host is None and tier.parent_code == "":
            host = next(
                (p for p in procedures if tier.code in (tier_offers.get(p.code) or ())),
                None,
            )
        if host is None:
            host = next(
                (p for p in procedures if tier.code in (tier_offers.get(p.code) or ())),
                procedures[0] if procedures else None,
            )
        if host is None:
            loose.append(tier)
        else:
            riders[id(host)].append(tier)
    items = []
    for line in procedures + loose:
        item = {}
        if line.category_code:
            item["category"] = {
                "coding": [
                    coding(NHCX_CATEGORY_CODE, line.category_code, line.category_display)
                ]
            }
        item["productOrService"] = {
            "coding": [coding(NHCX_PRODUCT_CODE, line.code, line.display)]
        }
        item["quantity"] = {"value": _quantity(line.quantity)}
        tiers = riders.get(id(line)) or []
        if tiers:
            item["modifier"] = [
                {"coding": [coding(None, t.code, t.display)]} for t in tiers
            ]
        items.append(item)
    return items


def build(data):
    """F2 bundle from an EligibilityInput. Raises FhirBuildError on a refusal."""
    purpose = (data.purpose or "").strip()
    if purpose not in ELIGIBILITY_PURPOSES:
        raise FhirBuildError(f"'{purpose}' is not a coverage eligibility purpose.")
    member_id = data.coverage.member_id or data.patient.member_id
    if not member_id:
        raise FhirBuildError("A coverage check needs the member id to ask about.")
    if not data.facility.identifier_value:
        raise FhirBuildError("A coverage check needs the facility's registry id.")
    if not organization.payer_code(data.payer.payer_id):
        raise FhirBuildError("A coverage check needs the payer's participant code.")

    request = {
        "resourceType": "CoverageEligibilityRequest",
        "meta": {"profile": [PROFILES["CoverageEligibilityRequest"]]},
        "identifier": [{"system": BASE_URL}],
        "status": "active",
        "priority": PRIORITY_NORMAL,
        "purpose": [purpose],
        "patient": fb.ref("/patient"),
        "created": fb.to_instant(data.created) or fb.now_instant(),
        "enterer": fb.ref("/practitioner-role"),
        "provider": fb.ref("/provider"),
        "insurer": fb.ref("/payer"),
        "facility": fb.ref("/location"),
        "insurance": [{"focal": True, "coverage": fb.ref("/coverage")}],
    }
    if purpose in ITEM_PURPOSES and data.lines:
        request["item"] = _items(list(data.lines), data.tier_offers or {})
    cov = coverage.build(data.coverage)
    cov["subscriberId"] = member_id
    kind = "coverage-" + purpose
    return fb.wrap(
        kind,
        [
            ("", request),
            ("/patient", patient.build(data.patient, variant="eligibility", purpose=purpose)),
            ("/provider", organization.build_provider(data.facility)),
            ("/payer", organization.build_payer(data.payer)),
            ("/location", other.build_location(data.facility)),
            ("/coverage", cov),
            ("/practitioner-role", practitioner.build_role()),
        ],
    )
