"""F7 QuestionnaireResponse: the answers to one payer form."""

from datetime import datetime, time

from care.nhcx.fhir import bundle as fb
from care.nhcx.fhir.codes import PROFILES
from care.nhcx.fhir.inputs import DocumentInput

TRUE_WORDS = {"yes", "true", "1", "y"}


def _text(answer):
    if answer is None:
        return ""
    return str(answer).strip()


def _value(item_type, answer):
    item_type = (item_type or "").lower()
    if item_type == "attachment":
        if isinstance(answer, DocumentInput):
            return {
                "valueAttachment": {
                    "contentType": answer.content_type or "application/pdf",
                    "title": answer.label or answer.filename,
                    "data": fb.b64(answer.data),
                }
            }
        if isinstance(answer, dict):
            return {"valueAttachment": answer}
        return {"valueString": _text(answer)}
    text = _text(answer)
    if item_type in ("date", "datetime", "instant"):
        try:
            return {"valueDateTime": fb.to_instant(answer)}
        except ValueError:
            return {"valueString": text}
    if item_type == "time":
        if isinstance(answer, time | datetime):
            return {"valueTime": answer.strftime("%H:%M:%S")}
        return {"valueTime": text}
    if item_type == "boolean":
        if isinstance(answer, bool):
            return {"valueBoolean": answer}
        return {"valueBoolean": text.lower() in TRUE_WORDS}
    if item_type == "integer":
        try:
            return {"valueInteger": int(text)}
        except ValueError:
            return {"valueString": text}
    if item_type in ("decimal", "quantity"):
        try:
            return {"valueDecimal": float(text)}
        except ValueError:
            return {"valueString": text}
    return {"valueString": text}


def _filled(question, saved):
    if question.get("linkId") in saved:
        answer = saved[question["linkId"]]
        if not (answer is None or (isinstance(answer, str) and not answer.strip())):
            return answer
    if (question.get("type") or "").lower() == "attachment":
        return None
    if question.get("initial"):
        return question["initial"]
    if question.get("options"):
        return question["options"][0]
    if (question.get("type") or "").lower() == "boolean":
        return "yes"
    return None


def build(form, answers, n, *, authored=None):
    """QuestionnaireResponse n for a FormInput and its FormAnswer rows.

    Returns None when no question has an answer (the form is skipped).
    """
    saved = {a.link_id: a.answer for a in answers if a.form_url == form.url}
    items = []
    for question in form.items or []:
        if (question.get("type") or "").lower() in ("group", "display"):
            continue
        answer = _filled(question, saved)
        if answer is None:
            continue
        item = {"linkId": question.get("linkId")}
        if question.get("text"):
            item["text"] = question["text"]
        item["answer"] = [_value(question.get("type"), answer)]
        items.append(item)
    if not items:
        return None
    return {
        "resourceType": "QuestionnaireResponse",
        "id": str(n),
        "meta": {"profile": [PROFILES["QuestionnaireResponse"]]},
        "questionnaire": form.url,
        "status": "completed",
        "subject": fb.ref("/patient"),
        "authored": fb.to_instant(authored) or fb.now_instant(),
        "item": items,
    }
