"""G9. Ledger: one JSON file per message under dated folders, indexed in memory.

Multi-process: CARE runs several web workers and a Celery worker against one
ledger directory. An `flock` on `<dir>/.lock` serialises id allocation, entry
writes and index appends; each process re-reads what the others appended to the
`index.jsonl` files (tracked per file by byte offset) before every read and
before allocating an id, and drops day folders another process pruned.
"""

from __future__ import annotations

import contextlib
import fcntl
import json
import logging
import os
import re
import shutil
import threading
from bisect import insort
from datetime import UTC, date, datetime, timedelta
from pathlib import Path
from typing import Any

from care.nhcx.gateway.errors import GatewayError
from care.nhcx.gateway.headers import (
    clean_path,
    entity_type,
    is_response_path,
    same_code,
)

logger = logging.getLogger("care.nhcx.gateway")

ALPHABET = "REDACTED"
ID_LEN = 8
LEGACY_ID_MIN = 24
RELATED_LIMIT = 500
LIST_MAX = 500
LIST_DEFAULT = 200
DAY_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
ID_RE = re.compile(r"^[0-9A-V]{8}$")
LEGACY_RE = re.compile(r"^\d{8}[A-Za-z0-9_-]{16,}$")

SUMMARY_FIELDS = (
    "id",
    "direction",
    "created_at",
    "path",
    "entity",
    "action",
    "kind",
    "format",
    "sender",
    "recipient",
    "correlation_id",
    "api_call_id",
    "request_id",
    "workflow_id",
    "hcx_status",
    "status",
    "error",
    "redelivery",
    "duration_ms",
)
ROW_FIELDS = (
    "id",
    "direction",
    "status",
    "sender",
    "recipient",
    "correlation_id",
    "api_call_id",
)


def b32(n: int, width: int) -> str:
    out = ""
    while n > 0:
        out = ALPHABET[n % 32] + out
        n //= 32
    return out.rjust(width, "0")


def unb32(s: str) -> int:
    n = 0
    for ch in s:
        n = n * 32 + ALPHABET.index(ch)
    return n


def day_code(t: datetime) -> str:
    t = t.astimezone(UTC)
    return b32((t.year % 100) * 10000 + t.month * 100 + t.day, 4)


def day_of_id(entry_id: str) -> str | None:
    """`YYYY-MM-DD` folder of an id (either scheme), or None if it is not an id."""
    if not isinstance(entry_id, str) or "/" in entry_id or "\\" in entry_id:
        return None
    if ID_RE.match(entry_id):
        n = unb32(entry_id[:4])
        yy, mm, dd = n // 10000, (n // 100) % 100, n % 100
        try:
            return date(2000 + yy, mm, dd).isoformat()
        except ValueError:
            return None
    if len(entry_id) >= LEGACY_ID_MIN and LEGACY_RE.match(entry_id):
        s = entry_id[:8]
        try:
            return date(int(s[:4]), int(s[4:6]), int(s[6:8])).isoformat()
        except ValueError:
            return None
    return None


def now_rfc3339(t: datetime | None = None) -> str:
    return (t or datetime.now(UTC)).astimezone().isoformat(timespec="milliseconds")


def parse_time(s: Any) -> datetime | None:
    if isinstance(s, datetime):
        return s if s.tzinfo else s.replace(tzinfo=UTC)
    if not isinstance(s, str) or not s:
        return None
    try:
        t = datetime.fromisoformat(s.replace("Z", "+00:00"))
    except ValueError:
        return None
    return t if t.tzinfo else t.replace(tzinfo=UTC)


def summarize(fhir: Any) -> dict | None:
    """`{resource_type, bundle_type, entries, resource_types, focus, identifier, patient, outcome}`."""
    if not isinstance(fhir, dict):
        return None
    out: dict[str, Any] = {"resource_type": fhir.get("resourceType")}
    resources = []
    if fhir.get("resourceType") == "Bundle":
        out["bundle_type"] = fhir.get("type")
        for e in fhir.get("entry") or []:
            r = e.get("resource") if isinstance(e, dict) else None
            if isinstance(r, dict):
                resources.append(r)
        out["entries"] = len(fhir.get("entry") or [])
    else:
        resources = [fhir]
    types: list[str] = []
    for r in resources:
        rt = r.get("resourceType")
        if isinstance(rt, str) and rt not in types:
            types.append(rt)
    out["resource_types"] = types
    focus = next(
        (
            r
            for r in resources
            if r.get("resourceType")
            in (
                "Claim",
                "ClaimResponse",
                "CoverageEligibilityRequest",
                "CoverageEligibilityResponse",
                "Task",
                "Communication",
                "CommunicationRequest",
                "PaymentNotice",
                "PaymentReconciliation",
                "InsurancePlan",
            )
        ),
        None,
    )
    if focus:
        out["focus"] = focus.get("resourceType")
        ident = focus.get("identifier")
        if isinstance(ident, list) and ident and isinstance(ident[0], dict):
            out["identifier"] = ident[0].get("value")
        elif isinstance(ident, dict):
            out["identifier"] = ident.get("value")
        pat = focus.get("patient")
        if isinstance(pat, dict):
            out["patient"] = pat.get("reference")
        if focus.get("outcome") is not None:
            out["outcome"] = focus.get("outcome")
    return out


class _FileLock:
    def __init__(self, path: Path):
        self.path = path
        self.local = threading.RLock()
        self.depth = 0
        self.fd: int | None = None

    def __enter__(self):
        self.local.acquire()
        if self.depth == 0:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            self.fd = os.open(self.path, os.O_RDWR | os.O_CREAT, 0o640)
            fcntl.flock(self.fd, fcntl.LOCK_EX)
        self.depth += 1
        return self

    def __exit__(self, *exc):
        self.depth -= 1
        if self.depth == 0 and self.fd is not None:
            try:
                fcntl.flock(self.fd, fcntl.LOCK_UN)
            finally:
                os.close(self.fd)
                self.fd = None
        self.local.release()


class Ledger:
    def __init__(
        self,
        directory: str | os.PathLike | None,
        *,
        enabled: bool = True,
        store_bodies: bool = True,
        retention_days: int = 0,
    ):
        self.enabled = bool(enabled and directory)
        self.dir = Path(directory) if directory else None
        self.store_bodies = store_bodies
        self.retention_days = max(int(retention_days or 0), 0)
        self.mu = threading.RLock()
        self.summaries: dict[str, dict] = {}
        self.ids: list[str] = []
        self.by_corr: dict[str, list[str]] = {}
        self.seen_set: set[str] = set()
        self.day_ids: dict[str, list[str]] = {}
        self.offsets: dict[str, int] = {}
        self.flock = _FileLock(self.dir / ".lock") if self.dir else None
        if self.enabled:
            self.dir.mkdir(parents=True, exist_ok=True)
            self.refresh()

    # ---- index maintenance ----

    def _drop_day(self, day: str) -> None:
        for i in self.day_ids.pop(day, []):
            s = self.summaries.pop(i, None)
            with contextlib.suppress(ValueError):
                self.ids.remove(i)
            if s:
                c = s.get("correlation_id") or ""
                lst = self.by_corr.get(c)
                if lst and i in lst:
                    lst.remove(i)
                    if not lst:
                        self.by_corr.pop(c, None)
                if s.get("api_call_id"):
                    self.seen_set.discard(f"{s.get('direction')}:{s.get('api_call_id')}")
        self.offsets.pop(day, None)

    def _index(self, s: dict, day: str) -> None:
        i = s.get("id")
        if not i or i in self.summaries:
            return
        self.summaries[i] = s
        if not self.ids or i > self.ids[-1]:
            self.ids.append(i)
        else:
            insort(self.ids, i)
        self.day_ids.setdefault(day, []).append(i)
        c = s.get("correlation_id") or ""
        if c:
            insort(self.by_corr.setdefault(c, []), i)
        if s.get("api_call_id"):
            self.seen_set.add(f"{s.get('direction')}:{s.get('api_call_id')}")

    def refresh(self) -> None:
        """Bring the in-memory indexes up to date with every process's appends."""
        if not self.enabled:
            return
        with self.mu:
            try:
                days = sorted(
                    p.name for p in self.dir.iterdir() if p.is_dir() and DAY_RE.match(p.name)
                )
            except FileNotFoundError:
                days = []
            for gone in set(self.offsets) - set(days):
                self._drop_day(gone)
            for day in days:
                idx = self.dir / day / "index.jsonl"
                off = self.offsets.get(day, 0)
                try:
                    size = idx.stat().st_size
                except FileNotFoundError:
                    continue
                if size < off:
                    self._drop_day(day)
                    off = 0
                if size == off:
                    self.offsets[day] = off
                    continue
                with idx.open("rb") as f:
                    f.seek(off)
                    data = f.read()
                end = data.rfind(b"\n") + 1
                for line in data[:end].splitlines():
                    if not line.strip():
                        continue
                    try:
                        s = json.loads(line)
                    except ValueError:
                        logger.warning("nhcx: unreadable ledger index line in %s", idx)
                        continue
                    if isinstance(s, dict):
                        self._index(s, day)
                self.offsets[day] = off + end

    # ---- writing ----

    def _next_id(self, t: datetime) -> str:
        day = day_code(t)
        top = 0
        lo = day + "0000"
        hi = day + "VVVV"
        for i in reversed(self.ids):
            if i <= hi and len(i) == ID_LEN:
                if i >= lo:
                    top = unb32(i[4:])
                break
        return day + b32(top + 1, 4)

    def record(self, e: dict) -> str | None:
        """Write one entry; returns its id. Errors propagate (the caller only logs)."""
        if not self.enabled:
            return None
        e = dict(e)
        t = parse_time(e.get("created_at")) or datetime.now(UTC)
        e["created_at"] = now_rfc3339(t)
        e["path"] = clean_path(e.get("path"))
        e["entity"] = e.get("entity") or entity_type(e["path"])
        e["action"] = e.get("action") or e["path"].split("/")[-1]
        e["kind"] = e.get("kind") or (
            "response" if is_response_path(e["path"]) else "request"
        )
        if e.get("fhir") is not None and not e.get("fhir_summary"):
            e["fhir_summary"] = summarize(e.get("fhir"))
        if not self.store_bodies:
            e["fhir"] = None
            if isinstance(e.get("peer"), dict):
                e["peer"] = {**e["peer"], "response": None}
        e.setdefault("redelivery", False)
        e.setdefault("duration_ms", 0)
        day = t.astimezone(UTC).date().isoformat()
        with self.mu, self.flock:
            self.refresh()
            if not e.get("id"):
                e["id"] = self._next_id(t)
            folder = self.dir / day
            folder.mkdir(parents=True, exist_ok=True)
            path = folder / f"{e['id']}.json"
            fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o640)
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(e, f, indent=2, ensure_ascii=False, default=str)
            summary = {k: e.get(k) for k in SUMMARY_FIELDS}
            with (folder / "index.jsonl").open("ab") as f:
                f.write(
                    json.dumps(summary, ensure_ascii=False, default=str).encode() + b"\n"
                )
            self.refresh()
        return e["id"]

    # ---- reads ----

    def _require(self) -> None:
        if not self.enabled:
            raise GatewayError("LEDGER_DISABLED", "the ledger is off")

    def get(self, entry_id: str) -> dict | None:
        self._require()
        day = day_of_id((entry_id or "").strip())
        if day is None:
            return None
        path = self.dir / day / f"{entry_id.strip()}.json"
        try:
            raw = path.read_bytes()
        except (FileNotFoundError, NotADirectoryError):
            return None
        try:
            out = json.loads(raw)
        except ValueError as e:
            raise GatewayError("LEDGER_CORRUPT", f"ledger entry {entry_id} is corrupt") from e
        return out

    def _entry(self, txn_id: str) -> dict:
        self._require()
        txn_id = (txn_id or "").strip() if isinstance(txn_id, str) else ""
        if not txn_id:
            raise GatewayError("NO_TXN_ID", "txn_id is required")
        e = self.get(txn_id)
        if e is None:
            raise GatewayError("TXN_NOT_FOUND", f"no transaction {txn_id} in the ledger")
        return e

    @staticmethod
    def row(s: dict) -> dict:
        out = {k: s.get(k) for k in ROW_FIELDS}
        out["type"] = s.get("entity")
        out["flow"] = s.get("action")
        out["created_at"] = s.get("created_at")
        return out

    def list_summaries(self, correlation_id: str | None = None, limit: int = 50) -> list[dict]:
        self.refresh()
        with self.mu:
            ids = self.by_corr.get(correlation_id, []) if correlation_id else self.ids
            return [self.summaries[i] for i in reversed(ids[-limit:]) if i in self.summaries]

    def related(self, txn_id: str) -> list[dict]:
        e = self._entry(txn_id)
        return [
            self.row(s)
            for s in self.list_summaries(e.get("correlation_id") or None, RELATED_LIMIT)
        ]

    def fhir(self, txn_id: str) -> dict:
        e = self._entry(txn_id)
        return {
            "meta": {
                "type": "in" if e.get("direction") == "in" else "out",
                "payloadType": e.get("format"),
                "path": e.get("path"),
                "time": e.get("created_at"),
            },
            "jwe_headers": e.get("headers"),
            "fhir": e.get("fhir"),
        }

    def dispatch(self, txn_id: str) -> dict:
        e = self._entry(txn_id)
        status = e.get("status")
        out: dict[str, Any] = {"txnId": e.get("id"), "status": status}
        if status in ("failed", "rejected"):
            out["status"] = "dispatch_failed"
        elif status in ("accepted", "delivered"):
            out["status"] = "dispatched"
        err = e.get("error")
        if isinstance(err, dict) and err:
            out["errorCode"] = err.get("code")
            out["errorMessage"] = err.get("message")
        return out

    def list(self, limit: Any = LIST_DEFAULT) -> list[dict]:
        if not self.enabled:
            return []
        if not isinstance(limit, int) or isinstance(limit, bool) or not 1 <= limit <= LIST_MAX:
            limit = LIST_DEFAULT
        return [self.row(s) for s in self.list_summaries(None, limit)]

    def seen(self, direction: str, api_call_id: str) -> bool:
        if not self.enabled or not api_call_id:
            return False
        self.refresh()
        with self.mu:
            return f"{direction}:{api_call_id}" in self.seen_set

    def last_inbound_request(
        self, entity: str, sender: str | None = None, workflow_id: str | None = None
    ) -> dict | None:
        if not self.enabled:
            return None
        self.refresh()
        with self.mu:
            for i in reversed(self.ids):
                s = self.summaries.get(i) or {}
                if (
                    s.get("direction") != "in"
                    or s.get("kind") != "request"
                    or s.get("entity") != entity
                    or not s.get("correlation_id")
                ):
                    continue
                if sender and not same_code(s.get("sender"), sender):
                    continue
                if workflow_id and s.get("workflow_id") != workflow_id:
                    continue
                return dict(s)
        return None

    def thread(self, correlation_id: str) -> dict | None:
        self._require()
        msgs = list(reversed(self.list_summaries(correlation_id, 10**6))) if correlation_id else []
        if not msgs:
            return None
        first = msgs[0]
        first_out = first.get("direction") == "out"
        if first.get("kind") == "response":
            first_out = not first_out
        state = "unknown"
        for m in msgs:
            hs = m.get("hcx_status") or ""
            is_resp = m.get("kind") == "response"
            if (
                m.get("status") in ("failed", "rejected")
                or (is_resp and m.get("status") == "delivery_failed")
                or m.get("format") == "protocol"
                or "error" in hs
            ):
                state = "error"
            elif not is_resp and m.get("direction") == "out":
                state = "awaiting_response"
            elif not is_resp and m.get("direction") == "in":
                state = "awaiting_our_response"
            elif is_resp and hs == "response.partial":
                state = "partial"
            elif is_resp:
                state = "completed"
        last = msgs[-1]
        counterparty = (
            first.get("recipient") if first.get("direction") == "out" else first.get("sender")
        )
        return {
            "correlation_id": correlation_id,
            "entity": first.get("entity"),
            "workflow_id": next((m.get("workflow_id") for m in msgs if m.get("workflow_id")), None),
            "counterparty": counterparty,
            "role": "initiator" if first_out else "responder",
            "state": state,
            "started": first.get("created_at"),
            "updated": last.get("created_at"),
            "messages": msgs,
        }

    def sweep(self, now: datetime | None = None) -> int:
        """Delete day folders older than the retention period; returns how many."""
        if not self.enabled or self.retention_days == 0:
            return 0
        now = now or datetime.now(UTC)
        cutoff = (now.astimezone(UTC) - timedelta(days=self.retention_days)).date().isoformat()
        removed = 0
        with self.mu, self.flock:
            for p in sorted(self.dir.iterdir()):
                if p.is_dir() and DAY_RE.match(p.name) and p.name < cutoff:
                    shutil.rmtree(p, ignore_errors=True)
                    self._drop_day(p.name)
                    removed += 1
        if removed:
            logger.info("nhcx: ledger pruned %d day folder(s) before %s", removed, cutoff)
        return removed

"""G7. Send: one FHIR payload to one encrypted NHCX message, synchronously."""

from __future__ import annotations

import json
import logging
import time
from dataclasses import asdict, dataclass, field
from datetime import UTC, datetime
from typing import TYPE_CHECKING, Any

from django.db import connections

from care.nhcx.gateway import crypto
from care.nhcx.gateway import headers as H  # noqa: N812
from care.nhcx.gateway.errors import (
    GatewayError,
    SendError,
    SendInTransactionError,
    as_gateway_error,
)

if TYPE_CHECKING:
    from care.nhcx.gateway.embedding import Gateway

logger = logging.getLogger("care.nhcx.gateway")

ALIASES = {
    "sender": H.SENDER_CODE,
    "recipient": H.RECIPIENT_CODE,
    "correlation_id": H.CORRELATION_ID,
    "request_id": H.REQUEST_ID,
    "api_call_id": H.API_CALL_ID,
    "workflow_id": H.WORKFLOW_ID,
    "status": H.STATUS,
}


@dataclass
class OutboundRequest:
    path: str
    headers: dict
    fhir: Any


@dataclass
class SendResult:
    ok: bool
    path: str
    url: str
    headers: dict
    gateway_status: int
    response: Any
    duration_ms: int
    ledger_id: str
    txn_id: str
    correlation_id: str
    api_call_id: str
    request_id: str
    extra: dict = field(default_factory=dict, repr=False)

    def to_dict(self) -> dict:
        out = asdict(self)
        out.pop("extra", None)
        return out

    @property
    def error_code(self) -> str | None:
        """NHCX's own error code when `ok` is false, else `GATEWAY_HTTP_<status>`."""
        if self.ok:
            return None
        err = self.response.get("error") if isinstance(self.response, dict) else None
        if isinstance(err, dict) and err.get("code"):
            return str(err["code"])
        return f"GATEWAY_HTTP_{self.gateway_status}"

    @property
    def error_message(self) -> str | None:
        if self.ok:
            return None
        err = self.response.get("error") if isinstance(self.response, dict) else None
        if isinstance(err, dict) and err.get("message"):
            return str(err["message"])
        return "NHCX did not accept the message"


def ensure_not_in_transaction() -> None:
    """Refuse to send inside a database transaction (G7D, SCAFFOLDING 8).

    Blocks opened by Django's TestCase (`_from_testcase`) are not the caller's
    transaction and are ignored, so services can be tested under TestCase.
    """
    for conn in connections.all(initialized_only=True):
        if not conn.in_atomic_block:
            continue
        if all(getattr(b, "_from_testcase", False) for b in conn.atomic_blocks):
            continue
        msg = (
            "gateway.send must not be called inside a database transaction "
            f"(connection {conn.alias!r} is in an atomic block): send first, "
            "outside any transaction, then write the leg in a transaction of its own"
        )
        raise SendInTransactionError(msg)


def _as_string(v: Any) -> str:
    if isinstance(v, str):
        return v
    return json.dumps(v).strip('"')


def _non_empty(v: Any) -> bool:
    if v is None:
        return False
    if isinstance(v, (str, dict, list)) and len(v) == 0:
        return False
    return not (isinstance(v, str) and v.strip() == "")


def parse_outbound(path: str, envelope: Any) -> OutboundRequest:
    if not isinstance(envelope, dict):
        raise SendError("INVALID_ENVELOPE", "body must be a JSON object")
    headers: dict = {}
    if "jwe_headers" in envelope:
        jh = envelope["jwe_headers"]
        if not isinstance(jh, dict):
            raise SendError("INVALID_ENVELOPE", "jwe_headers must be an object")
        headers.update(jh)
    for k in H.HCX_HEADERS:
        if k in envelope:
            headers[k] = _as_string(envelope[k])
    for alias, k in ALIASES.items():
        if alias in envelope:
            headers[k] = _as_string(envelope[alias])
    if _non_empty(envelope.get("fhir")):
        fhir = envelope["fhir"]
    elif _non_empty(envelope.get("payload")):
        fhir = envelope["payload"]
    else:
        raise SendError(
            "INVALID_ENVELOPE",
            'body needs a "fhir" object or must itself be a FHIR resource',
        )
    return OutboundRequest(path=path, headers=headers, fhir=fhir)


def _payload(fhir: Any) -> Any:
    if isinstance(fhir, (bytes, bytearray)):
        fhir = fhir.decode("utf-8", errors="replace")
    if isinstance(fhir, str):
        if fhir.strip() == "":
            raise SendError("INVALID_PAYLOAD", "fhir payload must be a JSON value")
        try:
            return json.loads(fhir)
        except ValueError as e:
            raise SendError(
                "INVALID_PAYLOAD", "fhir payload must be a JSON value"
            ) from e
    try:
        json.dumps(fhir)
    except (TypeError, ValueError) as e:
        raise SendError("INVALID_PAYLOAD", "fhir payload must be a JSON value") from e
    return fhir


def dispatch(client: Any, path: str, jwe: str) -> dict:
    url = H.target_url(client.cfg.url_nhcx, path)
    body: dict = {"payload": jwe}
    if H.is_response_path(path):
        body["type"] = "JWEPayload"
    start = time.monotonic()
    status, raw = client.post_with_token(url, body, label="GATEWAY")
    duration = int((time.monotonic() - start) * 1000)
    if raw in (None, b"", ""):
        parsed = None
    else:
        try:
            parsed = json.loads(raw)
        except (ValueError, TypeError):
            parsed = (
                raw.decode("utf-8", errors="replace") if isinstance(raw, bytes) else raw
            )
    return {"url": url, "status": status, "body": parsed, "duration": duration}


def send(gw: Gateway, path: str, envelope: Any) -> SendResult:
    ensure_not_in_transaction()
    req = parse_outbound(path, envelope)
    path = H.clean_path(req.path)
    if path == "":
        raise SendError("NO_PATH", "path is required (for example v1/preauth/submit)")
    fhir = _payload(req.fhir)

    hdrs = req.headers
    ledger = gw.ledger
    if (
        ledger.enabled
        and H.is_response_path(path)
        and not H.is_id(H.get_string(hdrs, H.CORRELATION_ID))
    ):
        try:
            prev = ledger.last_inbound_request(
                H.entity_type(path),
                H.get_string(hdrs, H.RECIPIENT_CODE) or None,
                H.get_string(hdrs, H.WORKFLOW_ID) or None,
            )
        except Exception:  # noqa: BLE001
            logger.warning("nhcx: response threading lookup failed", exc_info=True)
            prev = None
        if prev:
            hdrs[H.CORRELATION_ID] = prev["correlation_id"]
            if prev.get("workflow_id") and not H.get_string(hdrs, H.WORKFLOW_ID):
                hdrs[H.WORKFLOW_ID] = prev["workflow_id"]

    headers = H.build_protected_headers(hdrs, path)
    if not H.get_string(headers, H.SENDER_CODE):
        headers[H.SENDER_CODE] = gw.profiles.default.code
    sender = gw.identity_for(headers[H.SENDER_CODE])
    recipient = H.get_string(headers, H.RECIPIENT_CODE)
    started_at = datetime.now(UTC)
    start = time.monotonic()
    entry = {
        "direction": "out",
        "created_at": started_at.isoformat(),
        "path": path,
        "format": "fhir",
        "sender": headers[H.SENDER_CODE],
        "recipient": recipient,
        "correlation_id": headers[H.CORRELATION_ID],
        "api_call_id": headers[H.API_CALL_ID],
        "request_id": headers[H.REQUEST_ID],
        "workflow_id": H.get_string(headers, H.WORKFLOW_ID) or None,
        "hcx_status": H.get_string(headers, H.STATUS),
        "headers": headers,
        "fhir": fhir,
    }

    def record() -> str:
        try:
            return ledger.record(entry) or ""
        except Exception:  # noqa: BLE001
            logger.exception("nhcx: ledger write failed for an outbound message")
            return ""

    def fail(err: BaseException) -> SendError:
        g = as_gateway_error(err)
        entry["status"] = "failed"
        entry["error"] = {"code": g.code, "message": g.message}
        entry["duration_ms"] = int((time.monotonic() - start) * 1000)
        ledger_id = record()
        logger.warning(
            "nhcx: send failed path=%s code=%s correlation_id=%s",
            path,
            g.code,
            headers[H.CORRELATION_ID],
        )
        return SendError.from_error(g, ledger_id=ledger_id, headers=headers)

    if recipient == "":
        raise fail(GatewayError("NO_RECIPIENT", "x-hcx-recipient_code is required"))
    try:
        pub, _ = sender.certificate(recipient)
    except Exception as e:  # noqa: BLE001
        raise fail(e) from e
    try:
        jwe = crypto.encrypt(
            json.dumps(fhir, separators=(",", ":"), ensure_ascii=False), pub, headers
        )
    except Exception as e:  # noqa: BLE001
        raise fail(GatewayError("ENCRYPT_ERROR", str(e), cause=e)) from e
    try:
        res = dispatch(sender, path, jwe)
    except Exception as e:  # noqa: BLE001
        raise fail(e) from e

    ok = 200 <= res["status"] < 300  # noqa: PLR2004
    entry["duration_ms"] = res["duration"]
    entry["peer"] = {"url": res["url"], "status_code": res["status"], "response": res["body"]}
    if ok:
        entry["status"] = "accepted"
    else:
        entry["status"] = "rejected"
        entry["error"] = {
            "code": f"GATEWAY_HTTP_{res['status']}",
            "message": "NHCX did not accept the message",
        }
    ledger_id = record()
    logger.info(
        "nhcx: sent path=%s status=%s ledger_id=%s correlation_id=%s",
        path,
        res["status"],
        ledger_id,
        headers[H.CORRELATION_ID],
    )
    return SendResult(
        ok=ok,
        path=path,
        url=res["url"],
        headers=headers,
        gateway_status=res["status"],
        response=res["body"],
        duration_ms=res["duration"],
        ledger_id=ledger_id,
        txn_id=ledger_id,
        correlation_id=headers[H.CORRELATION_ID],
        api_call_id=headers[H.API_CALL_ID],
        request_id=headers[H.REQUEST_ID],
    )

