    "enhancement": "preauthorization",
    "preauth-queryupdate": "preauthorization",
    "predetermination": "predetermination",
    "claim": "claim",
    "claim-queryupdate": "claim",
}
QUERY_KINDS = {"preauth-queryupdate", "claim-queryupdate"}
DOCUMENT_CATEGORY_DISPLAYS = ("INV", "HDS", "OTH", "ODN")
FACTORS = (1, 0.5)


def practitioner_path(n):
    return "/practitioner" if n == 1 else f"/practitioner/{n}"


def _is_tier(line):
    return (line.kind or "").lower() == "stratification"


def _is_implant(line):
    return (line.kind or "").lower() == "implant"


def _quantity(line):
    q = line.quantity
    return fb.amount(q) if q not in (None, "", 0) else 1


def line_amount(line):
    """D16 amount, else quantity x unit_price."""
    if line.amount not in (None, ""):
        return float(line.amount)
    return float(_quantity(line)) * float(line.unit_price or 0)


def _days(start, end):
    first, last = fb.to_date(start), fb.to_date(end)
    if not first or not last:
        return 1
    from datetime import date

    return max((date.fromisoformat(last) - date.fromisoformat(first)).days, 1)


def lama_collapse(data, lines):
    """LAMA/DAMA before or during surgery: one LM100 line (claim leg only)."""
    mode = (data.discharge_mode or "").lower()
    stage = (data.discharge_stage or "").strip().lower()
    if mode not in ("lama", "dama") or stage not in LAMA_DAMA_STAGES:
        return lines
    package = data.lama_package or {}
    first = lines[0] if lines else LineInput()
    rate = float(package.get("rate") or 0)
    days = _days(data.admission_date, data.discharge_date)
    return [
        LineInput(
            kind="Procedure",
            code=LAMA_CODE,
            display=package.get("display") or LAMA_DISPLAY,
            category_code=package.get("category_code") or first.category_code,
            category_display=package.get("category_display")
            or first.category_display,
            unit_price=rate,
            quantity=days,
            amount=rate * days,
            seq=1,
        )
    ]


def _plan_items(lines):
    """Order lines by kind then seq; tiers ride on their procedure."""
    ordered = sorted(lines, key=lambda ln: ((ln.kind or "").lower(), ln.seq or 0))
    hosts = [ln for ln in ordered if not _is_tier(ln)]
    procedures = [ln for ln in hosts if not _is_implant(ln)]
    riders = {id(h): [] for h in hosts}
    loose = []
    for tier in (ln for ln in ordered if _is_tier(ln)):
        host = None
        if tier.parent_code:
            host = next((p for p in procedures if p.code == tier.parent_code), None)
        host = host or (procedures[0] if procedures else None)
        if host is None:
            loose.append(tier)
        else:
            riders[id(host)].append(tier)
    return [(ln, riders.get(id(ln), [])) for ln in hosts + loose]


def _document_info(doc):
    category = doc.category or "INV"
    code = doc.code or "ODN"
    title = doc.label or doc.filename
    return {
        "category": {
            "coding": [
                coding(
                    NDHM_SUPPORTINGINFO_CATEGORY,
                    category,
                    SUPPORTINGINFO_CATEGORIES.get(category)
                    if category in DOCUMENT_CATEGORY_DISPLAYS
                    else None,
                )
            ]
        },
        "code": {"coding": [coding(NHCX_DOCUMENT_CODE, code, title)]},
        "valueAttachment": {
            "contentType": doc.content_type or "application/pdf",
            "data": fb.b64(doc.data),
            "title": title,
        },
    }


def _scalar(category, code, value, code_display=None):
    return {
        "category": concept(
            NDHM_SUPPORTINGINFO_CATEGORY,
            category,
            SUPPORTINGINFO_CATEGORIES[category],
        ),
        "code": concept(
            NDHM_SUPPORTINGINFO_CODE,
            code,
            code_display or SUPPORTINGINFO_CODES[code],
        ),
        "valueString": value,
    }


def _answered_files(answers):
    return {
        a.answer.id
        for a in answers
        if isinstance(a.answer, DocumentInput) and a.answer.id is not None
    }


def _documents(data, is_claim):
    stage = "claim" if is_claim else "preauth"
    skip = _answered_files(data.answers)
    summary = data.discharge_summary
    if summary is not None and summary.id is not None:
        skip.add(summary.id)
    docs = []
    for doc in data.documents:
        if doc.stage and doc.stage != stage:
            continue
        if doc.id is not None and doc.id in skip:
            continue
        if is_claim and (doc.code or "").upper() == "HDS":
            continue
        docs.append(doc)
    return docs


def _supporting_info(data, is_claim, admission, responses):
    infos = [_document_info(doc) for doc in _documents(data, is_claim)]
    summary = data.discharge_summary
    if is_claim and summary is not None and summary.data:
        info = _document_info(summary)
        title = summary.label or "Hospital discharge summary"
        info["category"] = concept(
            NDHM_SUPPORTINGINFO_CATEGORY, "HDS", SUPPORTINGINFO_CATEGORIES["HDS"]
        )
        info["code"] = concept(NHCX_DOCUMENT_CODE, summary.code or "HDS", title)
        info["valueAttachment"]["title"] = title
        infos.append(info)
    infos.append(_scalar("ONS", "ADDD", admission))
    infos.append(_scalar("OTH", "EDT", admission))
    if is_claim:
        mode = (data.discharge_mode or "").lower()
        if data.surgery_date:
            infos.append(_scalar("ONS", "PSP", fb.to_instant(data.surgery_date)))
        end = data.death_date or data.discharge_date
        if end:
            infos.append(_scalar("ONS", "DSDE", fb.to_instant(end)))
        if mode == "death" and data.death_date:
            infos.append(_scalar("ONS", "DTM", fb.to_instant(data.death_date)))
        if mode in DISCHARGE_MODES:
            code, display, default = DISCHARGE_MODES[mode]
            infos.append(
                _scalar("DIS", code, data.discharge_stage or default, display)
            )
    if data.kind in QUERY_KINDS:
        infos.append(_scalar("NMI", "CQD", (data.reply_text or "").strip()))
    for n, (form, _resource) in enumerate(responses, start=1):
        stg = (form.kind or "").lower() == "stgquestionnaire"
        category, code = ("STG", "STG") if stg else ("INF", "ODN")
        infos.append(
            {
                "category": concept(
                    NDHM_SUPPORTINGINFO_CATEGORY,
                    category,
                    SUPPORTINGINFO_CATEGORIES[category],
                ),
                "code": concept(
                    NDHM_SUPPORTINGINFO_CODE, code, SUPPORTINGINFO_CODES[code]
                ),
                "valueReference": {
                    "reference": fb.url(f"/questionnaireresponse/{n}"),
                    "display": form.title or "Questionnaire",
                },
            }
        )
    out = []
    for n, info in enumerate(infos, start=1):
        out.append({"id": f"SupportingInformation/{n}", "sequence": n, **info})
    return out


def _care_team(practitioners):
    team = []
    for n, prac in enumerate(practitioners, start=1):
        member = {
            "sequence": n,
            "provider": fb.ref(practitioner_path(n)),
            "role": concept(CARE_TEAM_ROLE, "primary", "Primary provider")
            if n == 1
            else concept(CARE_TEAM_ROLE, "assist", "Assisting Provider"),
        }
        if prac.specialty_code:
            member["qualification"] = concept(
                SNOMED, prac.specialty_code, prac.specialty_display
            )
        elif prac.specialty_display:
            member["qualification"] = {"text": prac.specialty_display}
        team.append(member)
    return team


def _diagnoses(diagnoses):
    ordered = sorted(diagnoses, key=lambda d: d.seq or 0)
    return [
        {
            "sequence": n,
            "diagnosisCodeableConcept": concept(ICD10, d.icd10_code, d.icd10_display),
            "type": [concept(DIAGNOSIS_TYPE, "admitting", "Admitting Diagnosis")],
            "onAdmission": concept(DIAGNOSIS_ON_ADMISSION, "yes", "Yes"),
        }
        for n, d in enumerate(ordered, start=1)
    ]


def procedure_type(code, procedure_types):
    value = (procedure_types or {}).get(code) or "conservative"
    value = str(value).strip().lower() or "conservative"
    return value, value.capitalize()


def build(data):
    """F8 bundle from a ClaimInput (pre-checked by the services' refusals)."""
    use = USES[data.kind]
    is_claim = use == "claim"
    created = fb.to_instant(data.created) or fb.now_instant()
    admission = fb.to_instant(data.admission_date)
    if is_claim:
        end = fb.to_instant(data.discharge_date) or admission
    else:
        end = fb.to_instant(data.expected_discharge_date) or admission
    lines = list(data.lines)
    if is_claim:
        lines = lama_collapse(data, lines)
    planned = _plan_items(lines)

    procedure_date = admission
    if is_claim and data.surgery_date:
        procedure_date = fb.to_instant(data.surgery_date)

    responses = []
    if use != "predetermination":
        for form in data.forms:
            resource = questionnaire_response.build(
                form, data.answers, len(responses) + 1, authored=created
            )
            if resource is not None:
                responses.append((form, resource))

    supporting = _supporting_info(data, is_claim, admission, responses)
    care_team = _care_team(data.practitioners)
    diagnoses = _diagnoses(data.diagnoses)

    procedures, procedure_resources = [], []
    for line, _tiers in planned:
        if _is_tier(line) or _is_implant(line):
            continue
        n = len(procedures) + 1
        code, display = procedure_type(line.code, data.procedure_types)
        procedures.append(
            {
                "id": f"Procedure/{n}",
                "sequence": n,
                "type": [concept(NHCX_PROCEDURE_TYPE, code, display)],
                "date": procedure_date,
                "procedureReference": {
                    "reference": fb.url(f"/procedure/{n}"),
                    "display": line.display,
                },
            }
        )
        procedure_resources.append(
            other.build_procedure(n, line.display, procedure_date, completed=is_claim)
        )

    factors = {}
    if data.procedure_factor:
        ranked = sorted(
            (ln for ln, _t in planned if not _is_tier(ln) and not _is_implant(ln)),
            key=line_amount,
            reverse=True,
        )
        for rank, line in enumerate(ranked):
            factors[id(line)] = FACTORS[rank] if rank < len(FACTORS) else 0.25

    items, total, proc_n = [], 0.0, 0
    all_procedures = [p["sequence"] for p in procedures]
    for n, (line, tiers) in enumerate(planned, start=1):
        quantity = _quantity(line)
        net = line_amount(line) + sum(line_amount(t) for t in tiers)
        total += net
        item = {
            "id": f"Item/{n}",
            "sequence": n,
            "productOrService": concept(NDHM_PROCEDURE_CODE, line.code, line.display),
            "servicedPeriod": {"start": admission[:10], "end": end[:10]},
            "quantity": {"value": quantity},
            "unitPrice": fb.money(net / float(quantity)),
            "net": fb.money(net),
        }
        if line.category_code:
            item["category"] = concept(
                NDHM_BENEFIT_CATEGORY, line.category_code, line.category_display
            )
        if tiers:
            item["modifier"] = [
                {"coding": [coding(None, t.code, t.display)]} for t in tiers
            ]
        if data.program_code:
            item["programCode"] = [PROGRAM_PMJAY]
        if id(line) in factors:
            item["factor"] = factors[id(line)]
        item["careTeamSequence"] = [m["sequence"] for m in care_team]
        item["diagnosisSequence"] = [d["sequence"] for d in diagnoses]
        if _is_implant(line) or _is_tier(line):
            item["procedureSequence"] = list(all_procedures)
        else:
            proc_n += 1
            item["procedureSequence"] = [proc_n]
        item["informationSequence"] = [s["sequence"] for s in supporting]
        items.append(item)

    insurance = {"sequence": 1, "focal": True, "coverage": fb.ref("/coverage")}
    if is_claim and data.preauth_ref:
        insurance["preAuthRef"] = [data.preauth_ref]

    claim = {
        "resourceType": "Claim",
        "id": data.claim_no,
        "meta": {"profile": [PROFILES["Claim"]]},
        "identifier": [
            {
                "type": identifier_type("CLN"),
                "system": BASE_URL,
                "value": data.claim_no,
            }
        ],
        "status": "active",
        "type": CLAIM_TYPE,
        "use": use,
        "patient": fb.ref("/patient"),
        "billablePeriod": {"start": admission, "end": end},
        "created": created,
        "insurer": fb.ref("/payer"),
        "provider": fb.ref("/provider"),
        "priority": PRIORITY_NORMAL,
        "careTeam": care_team,
        "supportingInfo": supporting,
        "diagnosis": diagnoses,
        "procedure": procedures,
        "insurance": [insurance],
        "item": items,
        "total": fb.money(total),
    }
    if not procedures:
        del claim["procedure"]

    entries = [
        ("", claim),
        ("/patient", patient.build(data.patient)),
        ("/provider", organization.build_provider(data.facility, resource_id=1)),
        ("/payer", organization.build_payer(data.payer, resource_id=2)),
        ("/coverage", coverage.build(data.coverage, resource_id=1)),
    ]
    for n, prac in enumerate(data.practitioners, start=1):
        entries.append((practitioner_path(n), practitioner.build(prac, resource_id=n)))
    for n, resource in enumerate(procedure_resources, start=1):
        entries.append((f"/procedure/{n}", resource))
    for n, (_form, resource) in enumerate(responses, start=1):
        entries.append((f"/questionnaireresponse/{n}", resource))
    return fb.wrap(data.kind, entries)
