"""F10 claim-action Tasks: cancel, status, reprocess, release."""

from care.nhcx.fhir import bundle as fb
from care.nhcx.fhir.build import organization
from care.nhcx.fhir.codes import (
    BASE_URL,
    CANCEL_REASONS,
    FINANCIAL_TASK_CODE,
    NDHM_REASON_CODE,
    NDHM_TASK_INPUT_TYPE,
    NHCX_TASK_INPUT_TYPE,
    PROFILES,
    RELEASE_REASONS,
    REPROCESS_REASONS,
    coding,
    concept,
    identifier_type,
)
from care.nhcx.fhir.inputs import FhirBuildError

ACTIONS = ("cancel", "status", "reprocess", "release")


def kind_for(action, leg="preauth"):
    if action == "cancel":
        return "preauth-cancel"
    if action == "status":
        return "claim-status" if leg == "claim" else "preauth-status"
    return f"claim-{action}"


def description(action, claim_no, note="", reason=""):
    note = (note or "").strip()
    if action == "cancel":
        return note or f"Cancel the preauthorization {claim_no}"
    if action == "status":
        return f"Status of {claim_no}"
    if action == "reprocess":
        if note:
            return note
        if reason == "partialpayment":
            return f"Please cancel the preauth for claim {claim_no}"
        return f"Reprocess the claim {claim_no}"
    return note or f"Release the balance amount for claim {claim_no}"


def _reason(action, reason):
    if action == "release":
        reason = "partialpayment"
        table = RELEASE_REASONS
    elif action == "cancel":
        table = CANCEL_REASONS
    elif action == "reprocess":
        table = REPROCESS_REASONS
    else:
        return None
    reason = (reason or "").strip()
    if not reason:
        return None
    return concept(NDHM_REASON_CODE, reason, table.get(reason))


def _string_input(code, display, value):
    return {
        "type": concept(NDHM_TASK_INPUT_TYPE, code, display),
        "valueString": value,
    }


def build(data):
    """F10 bundle from a TaskInput."""
    action = data.action
    if action not in ACTIONS:
        raise FhirBuildError(f"'{action}' is not a claim action.")
    claim_no = data.claim_no
    task = {
        "resourceType": "Task",
        "meta": {"profile": [PROFILES["Task"]]},
        "status": "requested",
        "intent": "order",
        "code": {"coding": [coding(FINANCIAL_TASK_CODE, action)]},
        "authoredOn": fb.to_instant(data.authored_on) or fb.now_instant(),
        "requester": fb.ref("/provider"),
        "owner": fb.ref("/payer"),
        "description": description(action, claim_no, data.note, data.reason),
    }
    reason = _reason(action, data.reason)
    if reason:
        task["reasonCode"] = reason
    if action in ("reprocess", "release"):
        task["basedOn"] = [
            {
                "identifier": {
                    "type": identifier_type("CLN"),
                    "system": BASE_URL,
                    "value": claim_no,
                },
                "display": f"Claim {claim_no}",
            }
        ]
    inputs = [_string_input("claimNumber", "ClaimNumber", claim_no)]
    if action in ("cancel", "reprocess"):
        inputs.append(
            _string_input(
                data.intimation_type or "intimationNumber",
                "Intimation Number",
                data.intimation_number or claim_no,
            )
        )
    if action == "reprocess":
        for doc in data.documents:
            inputs.append(
                {
                    "type": concept(NDHM_TASK_INPUT_TYPE, "document", "Document"),
                    "valueAttachment": {
                        "contentType": doc.content_type or "application/pdf",
                        "data": fb.b64(doc.data),
                        "title": doc.label or doc.filename,
                    },
                }
            )
    if action == "release":
        inputs.append(
            {
                "type": concept(NHCX_TASK_INPUT_TYPE, "amount", "Amount"),
                "valueMoney": fb.money(data.amount),
            }
        )
    task["input"] = inputs
    if action == "reprocess":
        code = "PMJAY" if data.member_scheme == "pmjay" else "MB"
        task["for"] = {
            "identifier": {"type": identifier_type(code), "value": data.member_id}
        }
    return fb.wrap(
        kind_for(action, data.leg),
        [
            ("", task),
            ("/provider", organization.build_provider(data.facility)),
            ("/payer", organization.build_payer(data.payer)),
        ],
    )
