"""G8. Receive: decrypt an inbound NHCX message and hand it to C1 in-process."""

from __future__ import annotations

import json
import logging
import time
from dataclasses import dataclass, field
from datetime import UTC, datetime
from typing import TYPE_CHECKING, Any

from care.nhcx.gateway import crypto
from care.nhcx.gateway import headers as H  # noqa: N812
from care.nhcx.gateway.errors import GatewayError

if TYPE_CHECKING:
    from care.nhcx.gateway.embedding import Gateway

logger = logging.getLogger("care.nhcx.gateway")

STATUS = {
    "BODY_TOO_LARGE": 413,
    "BODY_READ": 400,
    "INVALID_BODY": 400,
    "INVALID_JWE": 400,
    "WRONG_RECIPIENT": 400,
    "DECRYPT_FAILED": 422,
    "RECEIVE_FAILED": 502,
    "MARSHAL_ERROR": 500,
    "INTERNAL": 500,
}
ACCEPTED = 202
ACCEPT_OUTCOMES = ("settled", "unmatched", "ignored", "rejected")
KIT_TYPES = {"insuranceplan": "insurance", "coverageeligibility": "coverage"}


@dataclass
class Inbound:
    path: str
    received_at: datetime
    remote_addr: str
    kind: str = "unknown"
    headers: dict = field(default_factory=dict)
    payload: Any = None
    profile: Any = None
    guest: str = ""
    redelivery: bool = False
    ledger_id: str = ""


@dataclass
class InboundAnswer:
    status: int
    body: dict
    headers: dict = field(default_factory=dict)
    outcome: str | None = None


def kit_type(path: str) -> str:
    e = H.entity_type(path)
    return KIT_TYPES.get(e, e)


def kit_flow(path: str) -> str:
    return "request" if H.is_response_path(path) else "on_request"


def normalise(h: dict | None) -> dict:
    out = {k: v for k, v in (h or {}).items() if v is not None}
    for k in (H.SENDER_CODE, H.RECIPIENT_CODE):
        if isinstance(out.get(k), str) and out[k].strip():
            out[k] = H.normalize_code(out[k])
    return out


def acceptance(path: str, headers: dict | None) -> dict:
    headers = headers or {}
    api = H.get_string(headers, H.API_CALL_ID)
    corr = H.get_string(headers, H.CORRELATION_ID)
    return {
        "timestamp": H.ack_timestamp(),
        "api_call_id": api if H.is_id(api) else H.new_id(),
        "correlation_id": corr if H.is_id(corr) else H.new_id(),
        "result": {
            "sender_code": H.get_string(headers, H.SENDER_CODE),
            "recipient_code": H.get_string(headers, H.RECIPIENT_CODE),
            "entity_type": H.entity_type(path),
            "protocol_status": "request.queued",
        },
        "error": None,
    }


def error_body(err: GatewayError, request_id: str | None, upstream: dict | None = None) -> dict:
    out: dict[str, Any] = {
        "ok": False,
        "error": {"code": err.code, "message": err.message, "retryable": err.retryable},
        "request_id": request_id or H.new_id(),
    }
    if upstream:
        out.update(upstream)
    return out


def _jwe_of(obj: dict) -> str | None:
    p = obj.get("payload")
    if isinstance(p, str):
        return p.strip()
    flat = crypto.flattened_to_compact(p) or crypto.flattened_to_compact(obj)
    return flat


def peek_headers(body: bytes) -> dict:
    """Protected header of an inbound body, without decrypting; `{}` when unreadable."""
    try:
        obj = json.loads(body)
    except (ValueError, TypeError):
        return {}
    if not isinstance(obj, dict):
        return {}
    jwe = _jwe_of(obj)
    if jwe:
        try:
            return crypto.parse_header(jwe)
        except crypto.CryptoError:
            return {}
    return {k: v for k, v in obj.items() if k.startswith("x-hcx-")}


def _is_encrypted(obj: dict) -> bool:
    if "payload" in obj:
        jwe = _jwe_of(obj)
        if obj.get("type") == "ProtocolResponse" and not crypto.is_compact_jwe(jwe):
            return False
        return True
    return crypto.flattened_to_compact(obj) is not None


def decrypt_for(gw: Gateway, code: str, jwe: str) -> tuple[Any, bytes]:
    tried: list[Any] = []
    first = gw.profiles.by_code(code)
    candidates = ([first] if first else []) + list(gw.profiles)
    for profile in candidates:
        if profile is None or profile.key is None or any(profile.key is k for k in tried):
            continue
        tried.append(profile.key)
        try:
            return profile, crypto.decrypt(jwe, profile.key)
        except crypto.CryptoError:
            continue
    raise GatewayError(
        "DECRYPT_FAILED",
        "payload could not be decrypted with any configured participant's private key",
    )


def receive(gw: Gateway, path: str, body: bytes, ip: str) -> Inbound:
    try:
        obj = json.loads(body)
    except (ValueError, TypeError) as e:
        raise GatewayError("INVALID_BODY", "body must be a JSON object", cause=e) from e
    if not isinstance(obj, dict):
        raise GatewayError("INVALID_BODY", "body must be a JSON object")
    inb = Inbound(path=H.clean_path(path), received_at=datetime.now(UTC), remote_addr=ip)
    if _is_encrypted(obj):
        jwe = _jwe_of(obj)
        if not crypto.is_compact_jwe(jwe):
            raise GatewayError("INVALID_JWE", crypto.NOT_COMPACT)
        try:
            hdr = crypto.parse_header(jwe)
        except crypto.CryptoError as e:
            raise GatewayError(
                "INVALID_JWE", "unreadable JWE protected header", cause=e
            ) from e
        rc = H.get_string(hdr, H.RECIPIENT_CODE)
        guest = rc != "" and not gw.profiles.is_local(rc)
        codes = ", ".join(gw.profiles.codes())
        if guest and not gw.guests:
            raise GatewayError(
                "WRONG_RECIPIENT",
                f"message is addressed to {H.normalize_code(rc)}, this adapter holds {codes}",
            )
        try:
            profile, plain = decrypt_for(gw, rc, jwe)
        except GatewayError as e:
            if guest:
                raise GatewayError(
                    "WRONG_RECIPIENT",
                    f"message is addressed to {H.normalize_code(rc)}, this adapter holds "
                    f"{codes}; none of its keys opens it; a guest is served once its "
                    "registry record carries this adapter's certificate",
                ) from e
            raise
        inb.profile = profile
        if guest:
            inb.guest = H.normalize_code(rc)
        try:
            payload = json.loads(plain)
        except (ValueError, TypeError):
            payload = plain.decode("utf-8", errors="replace")
        inb.kind = "fhir"
        inb.headers = normalise(hdr)
        inb.payload = payload
    else:
        inb.payload = obj
        hdrs = {k: v for k, v in obj.items() if k.startswith("x-hcx-")}
        inb.kind = "protocol" if hdrs or "type" in obj else "json"
        inb.headers = normalise(hdrs)
    try:
        inb.redelivery = gw.ledger.seen("in", H.get_string(inb.headers, H.API_CALL_ID))
    except Exception:  # noqa: BLE001
        logger.warning("nhcx: ledger seen() failed; treating as not seen", exc_info=True)
        inb.redelivery = False
    return inb


def participant(inb: Inbound) -> str:
    if inb.guest:
        return inb.guest
    if inb.profile is not None:
        return inb.profile.code
    return H.get_string(inb.headers, H.RECIPIENT_CODE)


def _outcome_of(result: Any) -> str:
    if isinstance(result, dict):
        result = result.get("outcome")
    if hasattr(result, "value"):
        result = result.value
    return str(result) if result is not None else ""


def deliver(gw: Gateway, inb: Inbound) -> tuple[dict, GatewayError | None]:
    who = participant(inb)
    envelope = {
        "meta": {
            "type": "in",
            "payloadType": inb.kind,
            "path": inb.path,
            "ip": inb.remote_addr,
            "time": inb.received_at.astimezone().isoformat(timespec="seconds"),
            "redelivery": inb.redelivery,
            "participant": who,
        },
        "jwe_headers": inb.headers,
        "fhir": inb.payload,
    }
    delivery = {
        "path": inb.path,
        "type": kit_type(inb.path),
        "flow": kit_flow(inb.path),
        "payload_kind": inb.kind,
        "correlation_id": H.get_string(inb.headers, H.CORRELATION_ID),
        "api_call_id": H.get_string(inb.headers, H.API_CALL_ID),
        "redelivery": inb.redelivery,
        "participant": who,
    }
    start = time.monotonic()
    try:
        result = gw.receive(envelope, delivery)
    except Exception as e:
        logger.exception("nhcx: C1.receive raised for path=%s", inb.path)
        took = int((time.monotonic() - start) * 1000)
        return (
            {"outcome": "error", "detail": str(e), "duration": took},
            GatewayError(
                "RECEIVE_FAILED", "C1 could not apply the message", retryable=True, cause=e
            ),
        )
    took = int((time.monotonic() - start) * 1000)
    outcome = _outcome_of(result)
    if outcome not in ACCEPT_OUTCOMES:
        detail = result.get("detail") if isinstance(result, dict) else None
        return (
            {"outcome": outcome or "error", "detail": detail, "duration": took},
            GatewayError(
                "RECEIVE_FAILED", "C1 could not apply the message", retryable=True
            ),
        )
    out = {"outcome": outcome, "duration": took}
    if isinstance(result, dict) and result.get("detail"):
        out["detail"] = result["detail"]
    return out, None


def record_inbound(
    gw: Gateway, inb: Inbound, result: dict | None, err: GatewayError | None
) -> None:
    if not gw.ledger.enabled:
        return
    h = inb.headers
    entry: dict[str, Any] = {
        "direction": "in",
        "created_at": inb.received_at.isoformat(),
        "path": inb.path,
        "format": inb.kind,
        "sender": H.get_string(h, H.SENDER_CODE),
        "recipient": H.get_string(h, H.RECIPIENT_CODE),
        "correlation_id": H.get_string(h, H.CORRELATION_ID),
        "api_call_id": H.get_string(h, H.API_CALL_ID),
        "request_id": H.get_string(h, H.REQUEST_ID),
        "workflow_id": H.get_string(h, H.WORKFLOW_ID) or None,
        "hcx_status": H.get_string(h, H.STATUS),
        "headers": h,
        "fhir": inb.payload,
        "redelivery": inb.redelivery,
        "duration_ms": int(
            (datetime.now(UTC) - inb.received_at).total_seconds() * 1000
        ),
    }
    if result:
        entry["peer"] = {
            "url": "C1.receive",
            "handler": "C1.receive",
            "status_code": 502 if err else ACCEPTED,
            "outcome": result.get("outcome"),
            "response": {k: v for k, v in result.items() if k != "duration"},
        }
        entry["duration_ms"] = result.get("duration", 0)
    if err is None:
        entry["status"] = "delivered"
    elif err.code == "RECEIVE_FAILED":
        entry["status"] = "delivery_failed"
        entry["error"] = {"code": err.code, "message": err.message}
    else:
        entry["status"] = "rejected"
        entry["error"] = {"code": err.code, "message": err.message}
    try:
        inb.ledger_id = gw.ledger.record(entry) or ""
    except Exception:  # noqa: BLE001
        logger.exception("nhcx: ledger write failed for an inbound message")


def handle_inbound(gw: Gateway, path: str, body: bytes, ip: str, request_id: str | None) -> InboundAnswer:
    try:
        inb = receive(gw, path, body, ip)
    except GatewayError as e:
        refused = Inbound(
            path=H.clean_path(path),
            received_at=datetime.now(UTC),
            remote_addr=ip,
            kind="unknown",
            headers=normalise(peek_headers(body)),
        )
        record_inbound(gw, refused, None, e)
        logger.warning("nhcx: inbound refused path=%s code=%s", path, e.code)
        return InboundAnswer(STATUS.get(e.code, 500), error_body(e, request_id))
    result, err = deliver(gw, inb)
    record_inbound(gw, inb, result, err)
    if err:
        upstream = {
            "upstream_status": 502,
            "upstream_body": {k: v for k, v in result.items() if k != "duration"},
        }
        return InboundAnswer(
            STATUS[err.code], error_body(err, request_id, upstream), outcome=result.get("outcome")
        )
    extra = {"X-Nhcx-Ledger-Id": inb.ledger_id} if inb.ledger_id else {}
    logger.info(
        "nhcx: inbound delivered path=%s outcome=%s ledger_id=%s",
        inb.path,
        result.get("outcome"),
        inb.ledger_id,
    )
    return InboundAnswer(
        ACCEPTED, acceptance(inb.path, inb.headers), extra, outcome=result.get("outcome")
    )


def not_open_answer(path: str, body: bytes) -> InboundAnswer:
    """Gateway not open: 202 with an `unmatched` outcome, never 503 (G8D)."""
    return InboundAnswer(
        ACCEPTED, acceptance(path, normalise(peek_headers(body))), outcome="unmatched"
    )

"""G10. Beneficiary registry: policy search and ABHA link pass-through."""

from __future__ import annotations

import json
from typing import Any

from care.nhcx.gateway.errors import GatewayError


def _s(v: Any) -> str:
    return v.strip() if isinstance(v, str) else ""


class BeneficiaryRegistry:
    """Runs as the default participant, whichever facility asks (G10D)."""

    def __init__(self, client: Any):
        self.client = client

    def post_registry(self, path: str, body: Any) -> dict:
        status, raw = self.client.post_registry(path, body)
        try:
            parsed = json.loads(raw)
        except (ValueError, TypeError):
            text = raw.decode("utf-8", errors="replace") if isinstance(raw, bytes) else raw
            parsed = {"error": text or ""}
        return {"status": status, "body": parsed}

    def policies_search(self, query: dict) -> dict:
        query = query or {}
        kind, value = _s(query.get("identifiertype")), _s(query.get("identifiervalue"))
        if kind == "":
            if _s(query.get("mobile")):
                kind, value = "MobileNo", _s(query.get("mobile"))
            elif _s(query.get("abhaNo")):
                kind, value = "AbhaNumber", _s(query.get("abhaNo"))
        if value == "":
            raise GatewayError(
                "NO_IDENTIFIER", "identifiervalue (or mobile / abhaNo) is required"
            )
        return self.post_registry(
            "participant/get/policies", {"identifiertype": kind, "identifiervalue": value}
        )

    def abha_link(self, body: Any) -> dict:
        return self.post_registry("participant/link/abha/policy", body)

    def abha_delink(self, body: Any) -> dict:
        return self.post_registry("participant/delink/abha/policy", body)

"""G11. Startup checks, liveness and readiness."""

from __future__ import annotations

import hashlib
import hmac
import json
import logging
import secrets
import threading
from typing import TYPE_CHECKING, Any

import requests

from care.nhcx.gateway import crypto
from care.nhcx.gateway.errors import GatewayError, as_gateway_error

if TYPE_CHECKING:
    from care.nhcx.gateway.embedding import Gateway

logger = logging.getLogger("care.nhcx.gateway")

SERVICE = "nhcx-adapter"
MAX_NONCE = 128
HEALTH_BODY_LIMIT = 4096
PROBE_BODY_LIMIT = 64 * 1024
PROBE_TIMEOUT = 15
CHECKS_TIMEOUT = 120
ENDPOINT_TIMEOUT = 30
HTTP_OK = 200


def probe_key(participant_id: str, client_secret: str, api_key: str) -> bytes:
    text = f"nhcx-adapter probe v1\0{participant_id}\0{client_secret}\0{api_key}"
    return hashlib.sha256(text.encode("utf-8")).digest()


def ack(key: bytes, nonce: str) -> str:
    return hmac.new(key, nonce.encode("utf-8"), hashlib.sha256).hexdigest()


def verify(key: bytes, nonce: str, answer: str) -> bool:
    return hmac.compare_digest(ack(key, nonce), answer or "")


def gateway_probe_key(gw: Gateway) -> bytes:
    d = gw.cfg.participant
    return probe_key(d.participantId, d.clientSecret, gw.cfg.api_key)


def healthz(gw: Gateway, method: str = "GET", body: bytes | None = None) -> dict:
    out = {
        "status": "ok",
        "service": SERVICE,
        "version": gw.version,
        "env": gw.cfg.env,
        "participant": gw.profiles.default.code,
    }
    if method.upper() == "POST" and body:
        try:
            req = json.loads(body[:HEALTH_BODY_LIMIT])
        except (ValueError, TypeError, UnicodeDecodeError):
            req = None
        nonce = req.get("probe") if isinstance(req, dict) else None
        if isinstance(nonce, str) and 0 < len(nonce) <= MAX_NONCE:
            out["probe_ack"] = ack(gateway_probe_key(gw), nonce)
    return out


def readyz(gw: Gateway) -> tuple[int, dict]:
    if gw.default_client.token_valid():
        return 200, {"status": "ready"}
    return 503, {"status": "no session token"}


def explain(e: BaseException) -> str:
    g = as_gateway_error(e)
    text = f"{g.code}: {g.message}"
    if g.body:
        text += f" ({g.body})"
    return text


def run_checks(gw: Gateway) -> dict:
    report: dict[str, Any] = {"checks": [], "cert": "unknown", "participant": None}

    def add(name: str, ok: bool, detail: str) -> None:
        report["checks"].append({"name": name, "ok": ok, "detail": detail})

    client = gw.default_client
    code = gw.profiles.default.code
    try:
        client.refresh_token()
    except Exception as e:  # noqa: BLE001
        add(
            "session token",
            False,
            explain(e)
            + " - check participant.clientId / clientSecret, auth.mode and urls.sessions",
        )
        return report
    add("session token", True, "issued by " + gw.cfg.url_sessions)

    try:
        p = client.fetch_participant(code)
        endpoint = (
            "endpoint " + p["endpointUrl"]
            if p.get("endpointUrl")
            else "no endpoint_url registered"
        )
        add(
            "participant record",
            True,
            f"{p['code']} · {p.get('name')} · {p.get('status')} · {endpoint}",
        )
        report["participant"] = p
    except Exception as e:  # noqa: BLE001
        add("participant record", False, explain(e))

    try:
        pub, _ = client.fetch_certificate(code)
        if crypto.public_numbers_equal(pub, client.own_key()):
            report["cert"] = "match"
            add("encryption certificate", True, "match")
        else:
            report["cert"] = "mismatch"
            add(
                "encryption certificate",
                False,
                "mismatch: does NOT match participant.privateKey, inbound messages "
                "could not be decrypted",
            )
    except Exception as e:  # noqa: BLE001
        g = as_gateway_error(e)
        if g.code == "CERT_NOT_FOUND":
            report["cert"] = "missing"
            add("encryption certificate", False, "registry has no encryption certificate")
        else:
            add("encryption certificate", False, explain(e))

    if len(gw.profiles.profiles) > 1:
        for prof in gw.profiles.profiles[1:]:
            name = "participant " + prof.code
            c = gw.identity_for(prof.code)
            try:
                c.token()
            except Exception as e:  # noqa: BLE001
                add(name, False, explain(e) + " - check its clientId / clientSecret")
                continue
            try:
                pub, _ = c.fetch_certificate(prof.code)
            except Exception as e:  # noqa: BLE001
                add(name, False, explain(e))
                continue
            if crypto.public_numbers_equal(pub, prof.public_key):
                add(name, True, "certificate matches · callback C1.receive (in-process)")
            else:
                add(name, False, "registry certificate does not match its private key")
    return report


def test_endpoint(http: Any, endpoint_url: str, key: bytes) -> tuple[bool, str]:
    url = endpoint_url.rstrip("/") + "/healthz"
    nonce = secrets.token_hex(16)
    try:
        resp = http.post(
            url,
            data=json.dumps({"probe": nonce}),
            headers={
                "Content-Type": "application/json",
                "Accept": "application/json",
                "Accept-Encoding": "identity",
                "User-Agent": "nhcx-adapter-check",
            },
            timeout=PROBE_TIMEOUT,
        )
    except requests.RequestException as e:
        return False, f"{url} unreachable from here: {e}"
    raw = (resp.content or b"")[:PROBE_BODY_LIMIT]
    try:
        ans = json.loads(raw)
    except (ValueError, TypeError):
        ans = None
    got = ans.get("probe_ack") if isinstance(ans, dict) else None
    if not isinstance(got, str) or not got:
        server = resp.headers.get("Server", "") if hasattr(resp, "headers") else ""
        excerpt = raw[:120].decode("utf-8", errors="replace")
        return False, (
            f"{url} answered {resp.status_code} (Server: {server}) without a probe "
            "acknowledgement: the proxy at that URL is not forwarding to this adapter's "
            f"listen address; body: {excerpt!r}"
        )
    if not verify(key, nonce, got):
        return False, (
            f"{url} is an nhcx-adapter, but not one running with this configuration "
            "(different participant or credentials)"
        )
    if resp.status_code != HTTP_OK:
        return False, f"{url} reaches this adapter but answered {resp.status_code}"
    return True, f"{url} reaches this adapter (probe acknowledged)"


def check(gw: Gateway) -> dict:
    """Run the setup checks and the endpoint probe; logs and returns the report, never raises."""
    holder: dict[str, Any] = {}

    def run() -> None:
        try:
            holder["report"] = run_checks(gw)
        except Exception as e:  # noqa: BLE001
            holder["report"] = {
                "checks": [{"name": "setup", "ok": False, "detail": explain(e)}],
                "cert": "unknown",
                "participant": None,
            }

    t = threading.Thread(target=run, name="nhcx-check", daemon=True)
    t.start()
    t.join(CHECKS_TIMEOUT)
    report = holder.get("report") or {
        "checks": [{"name": "setup", "ok": False, "detail": "timed out after 2 minutes"}],
        "cert": "unknown",
        "participant": None,
    }
    for c in report["checks"]:
        if c["ok"]:
            logger.info("nhcx: setup check %s: %s", c["name"], c["detail"])
        else:
            logger.warning("nhcx: setup check failed %s: %s", c["name"], c["detail"])
    p = report.get("participant")
    if p and p.get("endpointUrl"):
        try:
            ok, detail = test_endpoint(gw.http, p["endpointUrl"], gateway_probe_key(gw))
        except Exception as e:  # noqa: BLE001
            ok, detail = False, explain(e)
        report["endpoint"] = {"ok": ok, "detail": detail}
        if ok:
            logger.info("nhcx: registered endpoint verified: %s", detail)
        else:
            logger.warning(
                "nhcx: registered endpoint check failed: %s - NHCX cannot deliver "
                "callbacks until endpoint_url reaches this gateway",
                detail,
            )
    return report


__all__ = [
    "GatewayError",
    "ack",
    "check",
    "healthz",
    "probe_key",
    "readyz",
    "run_checks",
    "test_endpoint",
    "verify",
]

