cd care/care/nhcx/fhir/build && cat > communication.py <<'EOF'
"""F12 Communication: the reply to a payer query, and the acknowledgement of a notification."""

from care.nhcx.fhir import bundle as fb
from care.nhcx.fhir.build import coverage, organization, patient
from care.nhcx.fhir.codes import (
    BASE_URL,
    CLAIM_TYPE,
    COMMUNICATION_CATEGORY,
    FINANCIAL_TASK_CODE,
    FINANCIAL_TASK_INPUT_TYPE,
    NDHM_REASON_CODE,
    NDHM_TASK_CODES,
    PRIORITY_NORMAL,
    PROFILES,
    coding,
    concept,
    identifier_type,
    reason_word,
)
from care.nhcx.fhir.inputs import FhirBuildError

QUERY_NOT_FOUND = "Query not found."
NOT_A_QUESTION = (
    "That message is not a question: a notification is acknowledged and a note "
    "is read, neither takes an answer."
)
REPLY_SETTINGS = (
    "Set the facility's HFR ID and NHCX participant code under Settings before "
    "answering a query."
)
EMPTY_REPLY = (
    "Write a reply or attach a document, an empty answer tells the payer nothing."
)
DOCUMENT_NOT_ON_CLAIM = "One of the chosen documents is not on this claim."
ONLY_NOTIFICATION = (
    "Only a notification is acknowledged; a query is answered from the "
    "communication tab."
)
ACK_SETTINGS = (
    "Set the facility's HFR ID and NHCX participant code under Settings first."
)
CASE_TYPES = ("Claim", "Patient", "Organization", "Practitioner", "Coverage")


def _references(value):
    """Every reference string inside a resource."""
    if isinstance(value, dict):
        for key, inner in value.items():
            if key == "reference" and isinstance(inner, str):
                yield inner
            else:
                yield from _references(inner)
    elif isinstance(value, list):
        for inner in value:
            yield from _references(inner)


def _entry_with_url(entry):
    entry = fb.deep_copy(entry)
    if not entry.get("fullUrl"):
        rid = (entry.get("resource") or {}).get("id") or fb.new_uuid()
        entry["fullUrl"] = f"urn:uuid:{rid}"
    return entry


def _resolve_entry(pool, reference):
    for entry in pool:
        if entry.get("fullUrl") == reference:
            return entry
    key = reference.removeprefix("urn:uuid:").rstrip("/")
    tail = key.rsplit("/", 1)[-1]
    for entry in pool:
        rid = str((entry.get("resource") or {}).get("id") or "")
        if rid and rid in (key, tail):
            return entry
    return None


def _is_provider(resource):
    for t in resource.get("type") or []:
        for c in t.get("coding") or []:
            if c.get("code") == "prov":
                return True
    return False


def _split_organizations(entries):
    """(provider, payer) organization entries of a sent bundle."""
    orgs = [e for e in entries if e["resource"].get("resourceType") == "Organization"]
    if not orgs:
        return None, None
    provider = next((e for e in orgs if _is_provider(e["resource"])), None)
    provider = provider or next(
        (e for e in orgs if e.get("fullUrl") == fb.url("/provider")), orgs[0]
    )
    rest = [e for e in orgs if e is not provider]
    return provider, (rest[0] if rest else None)


def _stub_case(data):
    leg = "claim" if data.leg == "claim" else "preauth"
    claim = {
        "resourceType": "Claim",
        "id": data.claim_no,
        "meta": {"profile": [PROFILES["Claim"]]},
        "identifier": [
            {
                "type": identifier_type("CLN"),
                "system": BASE_URL,
                "value": data.claim_no,
            }
        ],
        "status": "active",
        "type": CLAIM_TYPE,
        "use": "claim" if leg == "claim" else "preauthorization",
        "patient": fb.ref("/patient"),
        "created": fb.now_instant(),
        "insurer": fb.ref("/payer"),
        "provider": fb.ref("/provider"),
        "priority": PRIORITY_NORMAL,
        "insurance": [
            {"sequence": 1, "focal": True, "coverage": fb.ref("/coverage")}
        ],
    }
    pat = data.patient
    if not pat.member_id:
        pat.member_id = data.coverage.member_id
    return [
        {"fullUrl": fb.url(f"/{leg}/request"), "resource": claim},
        {"fullUrl": fb.url("/patient"), "resource": patient.build(pat)},
        {
            "fullUrl": fb.url("/provider"),
            "resource": organization.build_provider(data.facility, resource_id=1),
        },
        {
            "fullUrl": fb.url("/payer"),
            "resource": organization.build_payer(data.payer, resource_id=2),
        },
        {
            "fullUrl": fb.url("/coverage"),
            "resource": coverage.build(data.coverage, resource_id=1),
        },
    ]


def _case_entries(data, extra_roots):
    """Case entries lifted from the sent bundle with their references, else stubs."""
    sent = [_entry_with_url(e) for e in fb.entries(data.sent_bundle or {})]
    sent = [e for e in sent if isinstance(e.get("resource"), dict)]
    request = [_entry_with_url(e) for e in fb.entries(data.request_bundle or {})]
    request = [
        e
        for e in request
        if (e.get("resource") or {}).get("resourceType")
        not in ("Task", "CommunicationRequest")
    ]
    if not any(e["resource"].get("resourceType") == "Claim" for e in sent):
        sent = _stub_case(data)
    provider, payer = _split_organizations(sent)
    chosen = []
    for rtype in CASE_TYPES:
        if rtype == "Organization":
            chosen += [e for e in (provider, payer) if e is not None]
            continue
        chosen += [e for e in sent if e["resource"].get("resourceType") == rtype]
    seen = {e["fullUrl"] for e in chosen}
    pool = sent + request
    queue = list(chosen) + list(extra_roots)
    while queue:
        entry = queue.pop(0)
        for reference in _references(entry.get("resource") or {}):
            target = _resolve_entry(pool, reference)
            if target is not None and target["fullUrl"] not in seen:
                seen.add(target["fullUrl"])
                chosen.append(target)
                queue.append(target)
    return chosen, provider, payer


def _request_parts(bundle):
    task = cr_entry = None
    for entry in fb.entries(bundle or {}):
        rtype = (entry.get("resource") or {}).get("resourceType")
        if rtype == "Task" and task is None:
            task = entry["resource"]
        if rtype == "CommunicationRequest" and cr_entry is None:
            cr_entry = _entry_with_url(entry)
    return task, cr_entry


def _reason_code(task, reason_code):
    if task and task.get("reasonCode"):
        return fb.deep_copy(task["reasonCode"])
    if reason_code:
        return concept(NDHM_REASON_CODE, reason_code, reason_word(reason_code))
    return None


def _org_ref(entry, fallback):
    return {"reference": entry["fullUrl"] if entry else fb.url(fallback), "display": "Organization"}


def build_reply(data):
    """F12 reply bundle from a ReplyInput (kind query). Raises FhirBuildError."""
    if data.kind != "query":
        raise FhirBuildError(NOT_A_QUESTION)
    if not data.facility.identifier_value or not data.facility.participant_code:
        raise FhirBuildError(REPLY_SETTINGS)
    text = (data.reply_text or "").strip()
    if not text and not data.documents:
        raise FhirBuildError(EMPTY_REPLY)

    request_task, cr_entry = _request_parts(data.request_bundle)
    if cr_entry is None:
        rid = data.request_id or fb.new_uuid()
        cr_entry = {
            "fullUrl": f"urn:uuid:{rid}",
            "resource": {
                "resourceType": "CommunicationRequest",
                "id": rid,
                "status": "active",
            },
        }
    case, provider, payer = _case_entries(data, [cr_entry])
    claim_entry = next(
        e for e in case if e["resource"].get("resourceType") == "Claim"
    )
    value = f"{data.claim_no}-Q{data.query_id}"
    identifiers = [
        fb.deep_copy(i)
        for i in cr_entry["resource"].get("identifier") or []
        if i.get("value")
    ] or [{"system": f"{data.payer_system}/communication", "value": value}]

    payload = []
    if text:
        payload.append({"contentString": text})
    for doc in data.documents:
        part = {
            "contentAttachment": {
                "contentType": doc.content_type or "application/pdf",
                "title": doc.label or doc.filename,
                "creation": fb.to_instant(doc.uploaded_at) or fb.now_instant(),
                "data": fb.b64(doc.data),
            }
        }
        if doc.code:
            part["extension"] = [
                {
                    "url": f"{data.payer_system}/StructureDefinition/document-type",
                    "valueString": doc.code,
                }
            ]
        payload.append(part)

    now = fb.now_instant()
    comm_id = fb.new_uuid()
    communication = {
        "resourceType": "Communication",
        "id": comm_id,
        "meta": {"profile": [PROFILES["Communication"]]},
        "identifier": identifiers,
        "basedOn": [
            {"reference": cr_entry["fullUrl"], "display": "CommunicationRequest"}
        ],
        "about": [
            {
                "reference": claim_entry["fullUrl"],
                "display": f"Claim {data.claim_ref or data.claim_no}",
            }
        ],
        "status": "completed",
        "category": [{"coding": [coding(COMMUNICATION_CATEGORY, "notification")]}],
        "priority": "routine",
        "recipient": [_org_ref(payer, "/payer")],
        "sender": _org_ref(provider, "/provider"),
        "payload": payload,
    }
    task_id = fb.new_uuid()
    task = {
        "resourceType": "Task",
        "id": task_id,
        "meta": {"profile": [PROFILES["Task"]]},
        "status": "completed",
        "intent": "order",
        "code": {"coding": [coding(NDHM_TASK_CODES, "deliver")]},
        "authoredOn": now,
        "requester": _org_ref(provider, "/provider"),
        "owner": _org_ref(payer, "/payer"),
        "input": [
            {
                "type": {"coding": [coding(FINANCIAL_TASK_INPUT_TYPE, "include")]},
                "valueReference": {
                    "reference": f"urn:uuid:{comm_id}",
                    "display": "Communication",
                },
            }
        ],
    }
    reason = _reason_code(request_task, data.reason_code)
    if reason:
        task["reasonCode"] = reason
    entries = [
        {"fullUrl": f"urn:uuid:{task_id}", "resource": task},
        {"fullUrl": f"urn:uuid:{comm_id}", "resource": communication},
        cr_entry,
    ] + case
    return {
        "resourceType": "Bundle",
        "id": fb.new_uuid(),
        "meta": {"lastUpdated": now, "profile": [PROFILES["TaskBundle"]]},
        "identifier": {"system": data.payer_system, "value": value},
        "type": "collection",
        "timestamp": now,
        "entry": entries,
    }


def build_acknowledgement(data):
    """F12 acknowledgement: the payer's notification bundle sent back, Task completed."""
    if data.kind != "notification":
        raise FhirBuildError(ONLY_NOTIFICATION)
    if not data.facility.identifier_value or not data.facility.participant_code:
        raise FhirBuildError(ACK_SETTINGS)
    request = fb.unwrap(data.request_bundle or {})
    entries = [_entry_with_url(e) for e in fb.entries(request)]
    task_entry = next(
        (e for e in entries if (e.get("resource") or {}).get("resourceType") == "Task"),
        None,
    )
    cr_entry = next(
        (
            e
            for e in entries
            if (e.get("resource") or {}).get("resourceType") == "CommunicationRequest"
        ),
        None,
    )
    orgs = [
        e for e in entries if (e.get("resource") or {}).get("resourceType") == "Organization"
    ]
    first_org = next((i for i, e in enumerate(entries) if e in orgs), None)

    pointers = []
    if task_entry:
        pointers.append((task_entry["resource"].get("owner") or {}).get("reference"))
    if cr_entry:
        pointers += [
            r.get("reference") for r in cr_entry["resource"].get("recipient") or []
        ]
    facility = None
    for pointer in filter(None, pointers):
        facility = _resolve_entry(orgs, pointer)
        if facility:
            break
    facility = facility or next((e for e in orgs if _is_provider(e["resource"])), None)
    others = [e for e in orgs if e is not facility]
    if facility is None:
        facility = {
            "fullUrl": fb.url("/provider"),
            "resource": organization.build_provider(data.facility),
        }
        if not others:
            others = [
                {
                    "fullUrl": fb.url("/payer"),
                    "resource": organization.build_payer(data.payer),
                }
            ]
    grouped = [facility] + others

    now = fb.now_instant()
    if task_entry is not None:
        task_entry["resource"]["status"] = "completed"
    else:
        task_id = fb.new_uuid()
        task = {
            "resourceType": "Task",
            "id": task_id,
            "meta": {"profile": [PROFILES["Task"]]},
            "status": "completed",
            "intent": "proposal",
            "code": {"coding": [coding(FINANCIAL_TASK_CODE, "poll")]},
            "authoredOn": now,
            "requester": {"reference": others[0]["fullUrl"]} if others else fb.ref("/payer"),
            "owner": {"reference": facility["fullUrl"]},
        }
        reason = _reason_code(None, data.reason_code)
        if reason:
            task["reasonCode"] = reason
        if cr_entry is not None:
            task["input"] = [
                {
                    "type": {"coding": [coding(FINANCIAL_TASK_INPUT_TYPE, "include")]},
                    "valueReference": {"reference": cr_entry["fullUrl"]},
                }
            ]
        task_entry = {"fullUrl": f"urn:uuid:{task_id}", "resource": task}

    rest = [e for e in entries if e is not task_entry and e not in orgs]
    position = (
        len([e for e in entries[:first_org] if e is not task_entry and e not in orgs])
        if first_org is not None
        else len(rest)
    )
    body = rest[:position] + grouped + rest[position:]
    identifier = request.get("identifier") or {
        "system": data.payer_system,
        "value": f"{data.claim_no}-N{data.query_id}",
    }
    return {
        "resourceType": "Bundle",
        "id": fb.new_uuid(),
        "meta": {"lastUpdated": now, "profile": [PROFILES["TaskBundle"]]},
        "identifier": fb.deep_copy(identifier),
        "type": "collection",
        "timestamp": now,
        "entry": [task_entry] + body,
    }


def build(data):
    """Reply for a query, acknowledgement for a notification."""
    if data.kind == "notification":
        return build_acknowledgement(data)
    return build_reply(data)
EOF

