"""G7. Send: one FHIR payload to one encrypted NHCX message, synchronously."""

from __future__ import annotations

import json
import logging
import time
from dataclasses import asdict, dataclass, field
from datetime import UTC, datetime
from typing import TYPE_CHECKING, Any

from django.db import connections

from care.nhcx.gateway import crypto
from care.nhcx.gateway import headers as H  # noqa: N812
from care.nhcx.gateway.errors import (
    GatewayError,
    SendError,
    SendInTransactionError,
    as_gateway_error,
)

if TYPE_CHECKING:
    from care.nhcx.gateway.embedding import Gateway

logger = logging.getLogger("care.nhcx.gateway")

ALIASES = {
    "sender": H.SENDER_CODE,
    "recipient": H.RECIPIENT_CODE,
    "correlation_id": H.CORRELATION_ID,
    "request_id": H.REQUEST_ID,
    "api_call_id": H.API_CALL_ID,
    "workflow_id": H.WORKFLOW_ID,
    "status": H.STATUS,
}


@dataclass
class OutboundRequest:
    path: str
    headers: dict
    fhir: Any


@dataclass
class SendResult:
    ok: bool
    path: str
    url: str
    headers: dict
    gateway_status: int
    response: Any
    duration_ms: int
    ledger_id: str
    txn_id: str
    correlation_id: str
    api_call_id: str
    request_id: str
    extra: dict = field(default_factory=dict, repr=False)

    def to_dict(self) -> dict:
        out = asdict(self)
        out.pop("extra", None)
        return out

    @property
    def error_code(self) -> str | None:
        """NHCX's own error code when `ok` is false, else `GATEWAY_HTTP_<status>`."""
        if self.ok:
            return None
        err = self.response.get("error") if isinstance(self.response, dict) else None
        if isinstance(err, dict) and err.get("code"):
            return str(err["code"])
        return f"GATEWAY_HTTP_{self.gateway_status}"

    @property
    def error_message(self) -> str | None:
        if self.ok:
            return None
        err = self.response.get("error") if isinstance(self.response, dict) else None
        if isinstance(err, dict) and err.get("message"):
            return str(err["message"])
        return "NHCX did not accept the message"


def ensure_not_in_transaction() -> None:
    """Refuse to send inside a database transaction (G7D, SCAFFOLDING 8).

    Blocks opened by Django's TestCase (`_from_testcase`) are not the caller's
    transaction and are ignored, so services can be tested under TestCase.
    """
    for conn in connections.all(initialized_only=True):
        if not conn.in_atomic_block:
            continue
        if all(getattr(b, "_from_testcase", False) for b in conn.atomic_blocks):
            continue
        msg = (
            "gateway.send must not be called inside a database transaction "
            f"(connection {conn.alias!r} is in an atomic block): send first, "
            "outside any transaction, then write the leg in a transaction of its own"
        )
        raise SendInTransactionError(msg)


def _as_string(v: Any) -> str:
    if isinstance(v, str):
        return v
    return json.dumps(v).strip('"')


def _non_empty(v: Any) -> bool:
    if v is None:
        return False
    if isinstance(v, (str, dict, list)) and len(v) == 0:
        return False
    return not (isinstance(v, str) and v.strip() == "")


def parse_outbound(path: str, envelope: Any) -> OutboundRequest:
    if not isinstance(envelope, dict):
        raise SendError("INVALID_ENVELOPE", "body must be a JSON object")
    headers: dict = {}
    if "jwe_headers" in envelope:
        jh = envelope["jwe_headers"]
        if not isinstance(jh, dict):
            raise SendError("INVALID_ENVELOPE", "jwe_headers must be an object")
        headers.update(jh)
    for k in H.HCX_HEADERS:
        if k in envelope:
            headers[k] = _as_string(envelope[k])
    for alias, k in ALIASES.items():
        if alias in envelope:
            headers[k] = _as_string(envelope[alias])
    if _non_empty(envelope.get("fhir")):
        fhir = envelope["fhir"]
    elif _non_empty(envelope.get("payload")):
        fhir = envelope["payload"]
    else:
        raise SendError(
            "INVALID_ENVELOPE",
            'body needs a "fhir" object or must itself be a FHIR resource',
        )
    return OutboundRequest(path=path, headers=headers, fhir=fhir)


def _payload(fhir: Any) -> Any:
    if isinstance(fhir, (bytes, bytearray)):
        fhir = fhir.decode("utf-8", errors="replace")
    if isinstance(fhir, str):
        if fhir.strip() == "":
            raise SendError("INVALID_PAYLOAD", "fhir payload must be a JSON value")
        try:
            return json.loads(fhir)
        except ValueError as e:
            raise SendError(
                "INVALID_PAYLOAD", "fhir payload must be a JSON value"
            ) from e
    try:
        json.dumps(fhir)
    except (TypeError, ValueError) as e:
        raise SendError("INVALID_PAYLOAD", "fhir payload must be a JSON value") from e
    return fhir


def dispatch(client: Any, path: str, jwe: str) -> dict:
    url = H.target_url(client.cfg.url_nhcx, path)
    body: dict = {"payload": jwe}
    if H.is_response_path(path):
        body["type"] = "JWEPayload"
    start = time.monotonic()
    status, raw = client.post_with_token(url, body, label="GATEWAY")
    duration = int((time.monotonic() - start) * 1000)
    if raw in (None, b"", ""):
        parsed = None
    else:
        try:
            parsed = json.loads(raw)
        except (ValueError, TypeError):
            parsed = (
                raw.decode("utf-8", errors="replace") if isinstance(raw, bytes) else raw
            )
    return {"url": url, "status": status, "body": parsed, "duration": duration}


def send(gw: Gateway, path: str, envelope: Any) -> SendResult:
    ensure_not_in_transaction()
    req = parse_outbound(path, envelope)
    path = H.clean_path(req.path)
    if path == "":
        raise SendError("NO_PATH", "path is required (for example v1/preauth/submit)")
    fhir = _payload(req.fhir)

    hdrs = req.headers
    ledger = gw.ledger
    if (
        ledger.enabled
        and H.is_response_path(path)
        and not H.is_id(H.get_string(hdrs, H.CORRELATION_ID))
    ):
        try:
            prev = ledger.last_inbound_request(
                H.entity_type(path),
                H.get_string(hdrs, H.RECIPIENT_CODE) or None,
                H.get_string(hdrs, H.WORKFLOW_ID) or None,
            )
        except Exception:  # noqa: BLE001
            logger.warning("nhcx: response threading lookup failed", exc_info=True)
            prev = None
        if prev:
            hdrs[H.CORRELATION_ID] = prev["correlation_id"]
            if prev.get("workflow_id") and not H.get_string(hdrs, H.WORKFLOW_ID):
                hdrs[H.WORKFLOW_ID] = prev["workflow_id"]

    headers = H.build_protected_headers(hdrs, path)
    if not H.get_string(headers, H.SENDER_CODE):
        headers[H.SENDER_CODE] = gw.profiles.default.code
    sender = gw.identity_for(headers[H.SENDER_CODE])
    recipient = H.get_string(headers, H.RECIPIENT_CODE)
    started_at = datetime.now(UTC)
    start = time.monotonic()
    entry = {
        "direction": "out",
        "created_at": started_at.isoformat(),
        "path": path,
        "format": "fhir",
        "sender": headers[H.SENDER_CODE],
        "recipient": recipient,
        "correlation_id": headers[H.CORRELATION_ID],
        "api_call_id": headers[H.API_CALL_ID],
        "request_id": headers[H.REQUEST_ID],
        "workflow_id": H.get_string(headers, H.WORKFLOW_ID) or None,
        "hcx_status": H.get_string(headers, H.STATUS),
        "headers": headers,
        "fhir": fhir,
    }

    def record() -> str:
        try:
            return ledger.record(entry) or ""
        except Exception:  # noqa: BLE001
            logger.exception("nhcx: ledger write failed for an outbound message")
            return ""

    def fail(err: BaseException) -> SendError:
        g = as_gateway_error(err)
        entry["status"] = "failed"
        entry["error"] = {"code": g.code, "message": g.message}
        entry["duration_ms"] = int((time.monotonic() - start) * 1000)
        ledger_id = record()
        logger.warning(
            "nhcx: send failed path=%s code=%s correlation_id=%s",
            path,
            g.code,
            headers[H.CORRELATION_ID],
        )
        return SendError.from_error(g, ledger_id=ledger_id, headers=headers)

    if recipient == "":
        raise fail(GatewayError("NO_RECIPIENT", "x-hcx-recipient_code is required"))
    try:
        pub, _ = sender.certificate(recipient)
    except Exception as e:  # noqa: BLE001
        raise fail(e) from e
    try:
        jwe = crypto.encrypt(
            json.dumps(fhir, separators=(",", ":"), ensure_ascii=False), pub, headers
        )
    except Exception as e:  # noqa: BLE001
        raise fail(GatewayError("ENCRYPT_ERROR", str(e), cause=e)) from e
    try:
        res = dispatch(sender, path, jwe)
    except Exception as e:  # noqa: BLE001
        raise fail(e) from e

    ok = 200 <= res["status"] < 300  # noqa: PLR2004
    entry["duration_ms"] = res["duration"]
    entry["peer"] = {"url": res["url"], "status_code": res["status"], "response": res["body"]}
    if ok:
        entry["status"] = "accepted"
    else:
        entry["status"] = "rejected"
        entry["error"] = {
            "code": f"GATEWAY_HTTP_{res['status']}",
            "message": "NHCX did not accept the message",
        }
    ledger_id = record()
    logger.info(
        "nhcx: sent path=%s status=%s ledger_id=%s correlation_id=%s",
        path,
        res["status"],
        ledger_id,
        headers[H.CORRELATION_ID],
    )
    return SendResult(
        ok=ok,
        path=path,
        url=res["url"],
        headers=headers,
        gateway_status=res["status"],
        response=res["body"],
        duration_ms=res["duration"],
        ledger_id=ledger_id,
        txn_id=ledger_id,
        correlation_id=headers[H.CORRELATION_ID],
        api_call_id=headers[H.API_CALL_ID],
        request_id=headers[H.REQUEST_ID],
    )

    """The ABDM client acting as one profile (G2 `identity_for`)."""

    def __init__(self, gateway_ctx: Any, profile: Any):
        self.ctx = gateway_ctx
        self.profile = profile

    @property
    def code(self) -> str:
        return self.profile.code

    @property
    def cfg(self):
        return self.ctx.cfg

    def credentials(self) -> tuple[str, str, str]:
        cid, secret = self.profile.participant.clientId, self.profile.participant.clientSecret
        if cid == "":
            d = self.cfg.participant
            cid, secret = d.clientId, d.clientSecret
        key = cid if cid != "" else "\0" + self.code
        return cid, secret, key

    # ---- tokens ----

    def token(self) -> str:
        cache = self.ctx.tokens
        with cache.lock:
            _, _, key = self.credentials()
            e = cache.get(key)
            if e and e[0] and e[1] - time.time() > FRESH_MARGIN:
                return e[0]
            return self._fetch_locked()

    def refresh_token(self) -> str:
        with self.ctx.tokens.lock:
            return self._fetch_locked()

    def token_info(self) -> tuple[str, float]:
        self.token()
        cache = self.ctx.tokens
        with cache.lock:
            _, _, key = self.credentials()
            return cache.tokens[key]

    def token_valid(self) -> bool:
        cache = self.ctx.tokens
        with cache.lock:
            _, _, key = self.credentials()
            e = cache.get(key)
        return bool(e and e[0] and time.time() < e[1])

    def _fetch_locked(self) -> str:
        cfg = self.cfg
        cid, secret, key = self.credentials()
        started = time.monotonic()
        headers = {"Accept": "application/json"}
        try:
            if cfg.auth_mode == "get-session":
                headers["Content-Type"] = "application/x-www-form-urlencoded"
                kwargs = {
                    "data": {
                        "client_id": cid,
                        "client_secret": secret,
                        "grant_type": "client_credentials",
                    }
                }
            else:
                headers.update(
                    {
                        "Content-Type": "application/json",
                        "REQUEST-ID": str(uuid.uuid4()),
                        "TIMESTAMP": utc_ms_timestamp(),
                        "X-CM-ID": cfg.cmId,
                    }
                )
                kwargs = {
                    "data": json.dumps(
                        {
                            "clientId": cid,
                            "clientSecret": secret,
                            "grantType": "client_credentials",
                        }
                    )
                }
        except (TypeError, ValueError) as e:
            raise GatewayError("TOKEN_REQUEST", "build session request", cause=e) from e
        try:
            resp = self.ctx.http.post(
                cfg.url_sessions, headers=headers, timeout=cfg.outbound_timeout, **kwargs
            )
        except requests.RequestException as e:
            raise GatewayError(
                "TOKEN_UNREACHABLE",
                "session endpoint unreachable",
                retryable=True,
                cause=e,
            ) from e
        raw = resp.content
        status = resp.status_code
        if not 200 <= status < 300:  # noqa: PLR2004
            raise GatewayError(
                f"TOKEN_HTTP_{status}",
                "session endpoint rejected the credentials",
                retryable=retryable_status(status),
                status=status,
                body=clip(raw),
            )
        try:
            out = json.loads(raw)
            if not isinstance(out, dict):
                raise ValueError("not an object")  # noqa: TRY301, EM101
        except ValueError as e:
            raise GatewayError(
                "TOKEN_BAD_JSON",
                "session response is not JSON",
                retryable=True,
                status=status,
                body=clip(raw),
                cause=e,
            ) from e
        token = _first_string(out, "accessToken", "access_token")
        if token == "":
            raise GatewayError(
                "TOKEN_MISSING", "session response carried no access token", status=status
            )
        ttl = float(cfg.token_ttl_seconds)
        n = _first_number(out, "expiresIn", "expires_in")
        if n > 0:
            ttl = n
        self.ctx.tokens.put(key, token, time.time() + ttl)
        logger.info(
            "nhcx: session token refreshed participant=%s mode=%s ttl=%s took_ms=%d",
            self.code,
            cfg.auth_mode,
            int(ttl),
            int((time.monotonic() - started) * 1000),
        )
        return token

    # ---- authenticated POST ----

    def post_with_token(
        self, url: str, body: Any, label: str = "CERT_FETCH"
    ) -> tuple[int, bytes]:
        try:
            payload = json.dumps(body)
        except (TypeError, ValueError) as e:
            raise GatewayError("MARSHAL_ERROR", "encode request body", cause=e) from e
        for attempt in (0, 1):
            token = self.token()
            headers = {
                "Content-Type": "application/json",
                "Accept": "application/json",
                "bearer_auth": "Bearer " + token,
                "Authorization": "Bearer " + token,
            }
            try:
                resp = self.ctx.http.post(
                    url, data=payload, headers=headers, timeout=self.cfg.outbound_timeout
                )
            except (requests.exceptions.InvalidURL, requests.exceptions.MissingSchema) as e:
                raise GatewayError(f"{label}_REQUEST", "build request", cause=e) from e
            except requests.RequestException as e:
                raise GatewayError(
                    f"{label}_UNREACHABLE", f"{url} unreachable", retryable=True, cause=e
                ) from e
            try:
                raw = resp.content
            except Exception as e:  # noqa: BLE001
                raise GatewayError(
                    f"{label}_READ_ERROR", "read response", retryable=True, cause=e
                ) from e
            if resp.status_code == HTTP_UNAUTHORIZED and attempt == 0:
                logger.warning("nhcx: upstream answered 401, refreshing session token")
                self.refresh_token()
                continue
            return resp.status_code, raw
        return resp.status_code, raw  # pragma: no cover


def token_payload(client: AbdmClient, token: str, expires: float) -> dict:
    exp = datetime.fromtimestamp(expires, UTC).replace(microsecond=0)
    return {
        "token": token,
        "token_type": "Bearer",
        "expires_at": exp.strftime("%Y-%m-%dT%H:%M:%SZ"),
        "expires_in": max(int(expires - time.time()), 0),
        "participant": client.code,
    }

class RegistryClient(AbdmClient):
    def _registry_url(self, path: str) -> str:
        return self.cfg.url_participant.rstrip("/") + "/" + path.lstrip("/")

    def certificate(self, code: Any) -> tuple[Any, str]:
        code = normalize_code(code)
        if code == "":
            raise GatewayError("NO_RECIPIENT", "participant code is empty")
        cache = self.ctx.certs
        with cache.lock:
            entry = cache.entries.get(code.lower())
        if entry and time.time() < entry["expires"]:
            return entry["key"], entry["pem"]
        return self.fetch_certificate(code)

    def fetch_certificate(self, code: Any) -> tuple[Any, str]:
        code = normalize_code(code)
        if code == "":
            raise GatewayError("NO_RECIPIENT", "participant code is empty")
        status, raw = self.post_with_token(
            self._registry_url("/fetch/certs"), {"participantid": code}, "CERT_FETCH"
        )
        if not _ok(status):
            raise GatewayError(
                f"CERT_FETCH_HTTP_{status}",
                f"participant registry refused the certificate lookup for {code}",
                retryable=retryable_status(status),
                status=status,
                body=clip(raw),
            )
        out = _parse_object(raw)
        if out is None:
            raise GatewayError(
                "CERT_FETCH_BAD_JSON",
                "registry response is not JSON",
                retryable=True,
                status=status,
                body=clip(raw),
            )
        pem = _first(out, "encryption_cert", "encryptionCert", "cert")
        if pem == "":
            raise GatewayError(
                "CERT_NOT_FOUND", f"registry returned no encryption certificate for {code}"
            )
        try:
            pub = crypto.parse_public_key(pem)
        except crypto.CryptoError as e:
            raise GatewayError(
                "CERT_NOT_FOUND",
                f"registry returned no usable certificate for {code}: "
                + json.dumps(pem[:120], ensure_ascii=False),
                cause=e,
            ) from e
        profiles = self.ctx.profiles
        if profiles.owns_key(pub) and not profiles.is_local(code):
            if self.cfg.refuse_self_key:
                raise GatewayError(
                    "SELF_ENCRYPTION_KEY",
                    f"registry certificate for {code} is this adapter's own key; "
                    "a payload encrypted with it would be unreadable at the far end",
                )
            logger.warning(
                "nhcx: registry certificate is this adapter's own key participant=%s", code
            )
        with self.ctx.certs.lock:
            self.ctx.certs.entries[code.lower()] = {
                "pem": pem,
                "key": pub,
                "expires": time.time() + self.cfg.cert_cache_hours * 3600,
            }
        logger.info("nhcx: certificate fetched participant=%s", code)
        return pub, pem

    def forget_certificate(self, code: Any) -> None:
        with self.ctx.certs.lock:
            self.ctx.certs.entries.pop(normalize_code(code).lower(), None)

    def own_key(self) -> Any:
        return self.profile.public_key if self.profile else None

    def fetch_participant(self, code: Any) -> dict:
        code = normalize_code(code)
        status, raw = self.post_with_token(
            self._registry_url("/participant/search"),
            {"participant_code": code, "participantcode": code, "participantid": code},
            "CERT_FETCH",
        )
        if not _ok(status):
            raise GatewayError(
                f"PARTICIPANT_HTTP_{status}",
                f"participant registry refused the search for {code}",
                retryable=retryable_status(status),
                status=status,
                body=clip(raw),
            )
        out = _parse_object(raw)
        if out is None:
            raise GatewayError(
                "PARTICIPANT_BAD_JSON",
                "registry response is not JSON",
                status=status,
                body=clip(raw),
            )
        rec: Any = out
        if isinstance(out.get("participants"), list):
            items = out["participants"]
            rec = next((r for r in items if same_code(_code_of(r), code)), None)
            if rec is None and items:
                rec = items[0]
        if rec is None or _code_of(rec) == "":
            raise GatewayError("PARTICIPANT_NOT_FOUND", f"registry has no record for {code}")
        roles = [r for r in rec.get("roles") or [] if isinstance(r, str)] if isinstance(
            rec.get("roles"), list
        ) else []
        if not roles and isinstance(rec.get("role_code"), list):
            roles = [r for r in rec["role_code"] if isinstance(r, str)]
        return {
            "code": normalize_code(_code_of(rec)),
            "name": _first(rec, "participant_name", "participantname", "name"),
            "status": _first(rec, "status"),
            "endpointUrl": _first(rec, "endpoint_url", "endpointurl", "endpointUrl"),
            "roles": roles,
            "raw": rec,
        }

    def post_registry(self, path: str, body: Any) -> tuple[int, bytes]:
        return self.post_with_token(self._registry_url(path), body, "CERT_FETCH")

