"""G8. Receive: decrypt an inbound NHCX message and hand it to C1 in-process."""

from __future__ import annotations

import json
import logging
import time
from dataclasses import dataclass, field
from datetime import UTC, datetime
from typing import TYPE_CHECKING, Any

from care.nhcx.gateway import crypto
from care.nhcx.gateway import headers as H  # noqa: N812
from care.nhcx.gateway.errors import GatewayError

if TYPE_CHECKING:
    from care.nhcx.gateway.embedding import Gateway

logger = logging.getLogger("care.nhcx.gateway")

STATUS = {
    "BODY_TOO_LARGE": 413,
    "BODY_READ": 400,
    "INVALID_BODY": 400,
    "INVALID_JWE": 400,
    "WRONG_RECIPIENT": 400,
    "DECRYPT_FAILED": 422,
    "RECEIVE_FAILED": 502,
    "MARSHAL_ERROR": 500,
    "INTERNAL": 500,
}
ACCEPTED = 202
ACCEPT_OUTCOMES = ("settled", "unmatched", "ignored", "rejected")
KIT_TYPES = {"insuranceplan": "insurance", "coverageeligibility": "coverage"}


@dataclass
class Inbound:
    path: str
    received_at: datetime
    remote_addr: str
    kind: str = "unknown"
    headers: dict = field(default_factory=dict)
    payload: Any = None
    profile: Any = None
    guest: str = ""
    redelivery: bool = False
    ledger_id: str = ""


@dataclass
class InboundAnswer:
    status: int
    body: dict
    headers: dict = field(default_factory=dict)
    outcome: str | None = None


def kit_type(path: str) -> str:
    e = H.entity_type(path)
    return KIT_TYPES.get(e, e)


def kit_flow(path: str) -> str:
    return "request" if H.is_response_path(path) else "on_request"


def normalise(h: dict | None) -> dict:
    out = {k: v for k, v in (h or {}).items() if v is not None}
    for k in (H.SENDER_CODE, H.RECIPIENT_CODE):
        if isinstance(out.get(k), str) and out[k].strip():
            out[k] = H.normalize_code(out[k])
    return out


def acceptance(path: str, headers: dict | None) -> dict:
    headers = headers or {}
    api = H.get_string(headers, H.API_CALL_ID)
    corr = H.get_string(headers, H.CORRELATION_ID)
    return {
        "timestamp": H.ack_timestamp(),
        "api_call_id": api if H.is_id(api) else H.new_id(),
        "correlation_id": corr if H.is_id(corr) else H.new_id(),
        "result": {
            "sender_code": H.get_string(headers, H.SENDER_CODE),
            "recipient_code": H.get_string(headers, H.RECIPIENT_CODE),
            "entity_type": H.entity_type(path),
            "protocol_status": "request.queued",
        },
        "error": None,
    }


def error_body(err: GatewayError, request_id: str | None, upstream: dict | None = None) -> dict:
    out: dict[str, Any] = {
        "ok": False,
        "error": {"code": err.code, "message": err.message, "retryable": err.retryable},
        "request_id": request_id or H.new_id(),
    }
    if upstream:
        out.update(upstream)
    return out


def _jwe_of(obj: dict) -> str | None:
    p = obj.get("payload")
    if isinstance(p, str):
        return p.strip()
    flat = crypto.flattened_to_compact(p) or crypto.flattened_to_compact(obj)
    return flat


def peek_headers(body: bytes) -> dict:
    """Protected header of an inbound body, without decrypting; `{}` when unreadable."""
    try:
        obj = json.loads(body)
    except (ValueError, TypeError):
        return {}
    if not isinstance(obj, dict):
        return {}
    jwe = _jwe_of(obj)
    if jwe:
        try:
            return crypto.parse_header(jwe)
        except crypto.CryptoError:
            return {}
    return {k: v for k, v in obj.items() if k.startswith("x-hcx-")}


def _is_encrypted(obj: dict) -> bool:
    if "payload" in obj:
        jwe = _jwe_of(obj)
        if obj.get("type") == "ProtocolResponse" and not crypto.is_compact_jwe(jwe):
            return False
        return True
    return crypto.flattened_to_compact(obj) is not None


def decrypt_for(gw: Gateway, code: str, jwe: str) -> tuple[Any, bytes]:
    tried: list[Any] = []
    first = gw.profiles.by_code(code)
    candidates = ([first] if first else []) + list(gw.profiles)
    for profile in candidates:
        if profile is None or profile.key is None or any(profile.key is k for k in tried):
            continue
        tried.append(profile.key)
        try:
            return profile, crypto.decrypt(jwe, profile.key)
        except crypto.CryptoError:
            continue
    raise GatewayError(
        "DECRYPT_FAILED",
        "payload could not be decrypted with any configured participant's private key",
    )


def receive(gw: Gateway, path: str, body: bytes, ip: str) -> Inbound:
    try:
        obj = json.loads(body)
    except (ValueError, TypeError) as e:
        raise GatewayError("INVALID_BODY", "body must be a JSON object", cause=e) from e
    if not isinstance(obj, dict):
        raise GatewayError("INVALID_BODY", "body must be a JSON object")
    inb = Inbound(path=H.clean_path(path), received_at=datetime.now(UTC), remote_addr=ip)
    if _is_encrypted(obj):
        jwe = _jwe_of(obj)
        if not crypto.is_compact_jwe(jwe):
            raise GatewayError("INVALID_JWE", crypto.NOT_COMPACT)
        try:
            hdr = crypto.parse_header(jwe)
        except crypto.CryptoError as e:
            raise GatewayError(
                "INVALID_JWE", "unreadable JWE protected header", cause=e
            ) from e
        rc = H.get_string(hdr, H.RECIPIENT_CODE)
        guest = rc != "" and not gw.profiles.is_local(rc)
        codes = ", ".join(gw.profiles.codes())
        if guest and not gw.guests:
            raise GatewayError(
                "WRONG_RECIPIENT",
                f"message is addressed to {H.normalize_code(rc)}, this adapter holds {codes}",
            )
        try:
            profile, plain = decrypt_for(gw, rc, jwe)
        except GatewayError as e:
            if guest:
                raise GatewayError(
                    "WRONG_RECIPIENT",
                    f"message is addressed to {H.normalize_code(rc)}, this adapter holds "
                    f"{codes}; none of its keys opens it; a guest is served once its "
                    "registry record carries this adapter's certificate",
                ) from e
            raise
        inb.profile = profile
        if guest:
            inb.guest = H.normalize_code(rc)
        try:
            payload = json.loads(plain)
        except (ValueError, TypeError):
            payload = plain.decode("utf-8", errors="replace")
        inb.kind = "fhir"
        inb.headers = normalise(hdr)
        inb.payload = payload
    else:
        inb.payload = obj
        hdrs = {k: v for k, v in obj.items() if k.startswith("x-hcx-")}
        inb.kind = "protocol" if hdrs or "type" in obj else "json"
        inb.headers = normalise(hdrs)
    try:
        inb.redelivery = gw.ledger.seen("in", H.get_string(inb.headers, H.API_CALL_ID))
    except Exception:  # noqa: BLE001
        logger.warning("nhcx: ledger seen() failed; treating as not seen", exc_info=True)
        inb.redelivery = False
    return inb


def participant(inb: Inbound) -> str:
    if inb.guest:
        return inb.guest
    if inb.profile is not None:
        return inb.profile.code
    return H.get_string(inb.headers, H.RECIPIENT_CODE)


def _outcome_of(result: Any) -> str:
    if isinstance(result, dict):
        result = result.get("outcome")
    if hasattr(result, "value"):
        result = result.value
    return str(result) if result is not None else ""


def deliver(gw: Gateway, inb: Inbound) -> tuple[dict, GatewayError | None]:
    who = participant(inb)
    envelope = {
        "meta": {
            "type": "in",
            "payloadType": inb.kind,
            "path": inb.path,
            "ip": inb.remote_addr,
            "time": inb.received_at.astimezone().isoformat(timespec="seconds"),
            "redelivery": inb.redelivery,
            "participant": who,
        },
        "jwe_headers": inb.headers,
        "fhir": inb.payload,
    }
    delivery = {
        "path": inb.path,
        "type": kit_type(inb.path),
        "flow": kit_flow(inb.path),
        "payload_kind": inb.kind,
        "correlation_id": H.get_string(inb.headers, H.CORRELATION_ID),
        "api_call_id": H.get_string(inb.headers, H.API_CALL_ID),
        "redelivery": inb.redelivery,
        "participant": who,
    }
    start = time.monotonic()
    try:
        result = gw.receive(envelope, delivery)
    except Exception as e:
        logger.exception("nhcx: C1.receive raised for path=%s", inb.path)
        took = int((time.monotonic() - start) * 1000)
        return (
            {"outcome": "error", "detail": str(e), "duration": took},
            GatewayError(
                "RECEIVE_FAILED", "C1 could not apply the message", retryable=True, cause=e
            ),
        )
    took = int((time.monotonic() - start) * 1000)
    outcome = _outcome_of(result)
    if outcome not in ACCEPT_OUTCOMES:
        detail = result.get("detail") if isinstance(result, dict) else None
        return (
            {"outcome": outcome or "error", "detail": detail, "duration": took},
            GatewayError(
                "RECEIVE_FAILED", "C1 could not apply the message", retryable=True
            ),
        )
    out = {"outcome": outcome, "duration": took}
    if isinstance(result, dict) and result.get("detail"):
        out["detail"] = result["detail"]
    return out, None


def record_inbound(
    gw: Gateway, inb: Inbound, result: dict | None, err: GatewayError | None
) -> None:
    if not gw.ledger.enabled:
        return
    h = inb.headers
    entry: dict[str, Any] = {
        "direction": "in",
        "created_at": inb.received_at.isoformat(),
        "path": inb.path,
        "format": inb.kind,
        "sender": H.get_string(h, H.SENDER_CODE),
        "recipient": H.get_string(h, H.RECIPIENT_CODE),
        "correlation_id": H.get_string(h, H.CORRELATION_ID),
        "api_call_id": H.get_string(h, H.API_CALL_ID),
        "request_id": H.get_string(h, H.REQUEST_ID),
        "workflow_id": H.get_string(h, H.WORKFLOW_ID) or None,
        "hcx_status": H.get_string(h, H.STATUS),
        "headers": h,
        "fhir": inb.payload,
        "redelivery": inb.redelivery,
        "duration_ms": int(
            (datetime.now(UTC) - inb.received_at).total_seconds() * 1000
        ),
    }
    if result:
        entry["peer"] = {
            "url": "C1.receive",
            "handler": "C1.receive",
            "status_code": 502 if err else ACCEPTED,
            "outcome": result.get("outcome"),
            "response": {k: v for k, v in result.items() if k != "duration"},
        }
        entry["duration_ms"] = result.get("duration", 0)
    if err is None:
        entry["status"] = "delivered"
    elif err.code == "RECEIVE_FAILED":
        entry["status"] = "delivery_failed"
        entry["error"] = {"code": err.code, "message": err.message}
    else:
        entry["status"] = "rejected"
        entry["error"] = {"code": err.code, "message": err.message}
    try:
        inb.ledger_id = gw.ledger.record(entry) or ""
    except Exception:  # noqa: BLE001
        logger.exception("nhcx: ledger write failed for an inbound message")


def handle_inbound(gw: Gateway, path: str, body: bytes, ip: str, request_id: str | None) -> InboundAnswer:
    try:
        inb = receive(gw, path, body, ip)
    except GatewayError as e:
        refused = Inbound(
            path=H.clean_path(path),
            received_at=datetime.now(UTC),
            remote_addr=ip,
            kind="unknown",
            headers=normalise(peek_headers(body)),
        )
        record_inbound(gw, refused, None, e)
        logger.warning("nhcx: inbound refused path=%s code=%s", path, e.code)
        return InboundAnswer(STATUS.get(e.code, 500), error_body(e, request_id))
    result, err = deliver(gw, inb)
    record_inbound(gw, inb, result, err)
    if err:
        upstream = {
            "upstream_status": 502,
            "upstream_body": {k: v for k, v in result.items() if k != "duration"},
        }
        return InboundAnswer(
            STATUS[err.code], error_body(err, request_id, upstream), outcome=result.get("outcome")
        )
    extra = {"X-Nhcx-Ledger-Id": inb.ledger_id} if inb.ledger_id else {}
    logger.info(
        "nhcx: inbound delivered path=%s outcome=%s ledger_id=%s",
        inb.path,
        result.get("outcome"),
        inb.ledger_id,
    )
    return InboundAnswer(
        ACCEPTED, acceptance(inb.path, inb.headers), extra, outcome=result.get("outcome")
    )


def not_open_answer(path: str, body: bytes) -> InboundAnswer:
    """Gateway not open: 202 with an `unmatched` outcome, never 503 (G8D)."""
    return InboundAnswer(
        ACCEPTED, acceptance(path, normalise(peek_headers(body))), outcome="unmatched"
    )

class Gateway:
    """An open gateway: configuration, profiles, caches, ledger and the C1 callable."""

    def __init__(
        self,
        cfg: Config,
        receive_fn: ReceiveFn,
        *,
        version: str = "embedded",
        http: Any = None,
        token_store: Any = None,
    ):
        self.cfg = cfg
        self.receive = receive_fn
        self.version = version or "embedded"
        self.guests = cfg.guests
        self.profiles = build_profiles(cfg)
        self.http = http if http is not None else requests.Session()
        self.tokens = TokenCache(shared=token_store)
        self.certs = CertCache()
        self.ledger = Ledger(
            cfg.ledger_dir if cfg.ledger_enabled else None,
            enabled=cfg.ledger_enabled,
            store_bodies=cfg.ledger_store_bodies,
            retention_days=cfg.ledger_retention_days,
        )
        self._clients: dict[str, RegistryClient] = {}
        for p in self.profiles:
            self._clients[p.code.lower()] = RegistryClient(self, p)
        self.default_client = RegistryClient(self, self.profiles.default)
        self.registry = beneficiary.BeneficiaryRegistry(self.default_client)
        self.beneficiary = self.registry
        self._stop = threading.Event()
        self._threads: list[threading.Thread] = []

    # ---- identities ----

    def identity_for(self, code: Any) -> RegistryClient:
        c = normalize_code(code)
        if c and c.lower() in self._clients:
            return self._clients[c.lower()]
        return self.default_client

    @property
    def participant_codes(self) -> list[str]:
        return self.profiles.codes()

    # ---- G7 ----

    def parse_outbound(self, path: str, envelope: Any) -> send.OutboundRequest:
        return send.parse_outbound(path, envelope)

    def send(self, path: str, envelope: Any) -> send.SendResult:
        return send.send(self, path, envelope)

    # ---- G3 ----

    def token(self, participant: str | None = None, *, refresh: bool = False) -> dict:
        client = self.default_client
        if participant:
            if self.profiles.by_code(participant) is None:
                raise GatewayError(
                    "UNKNOWN_PARTICIPANT",
                    f"no participant {participant} is configured; this adapter holds "
                    + ", ".join(self.profiles.codes()),
                )
            client = self.identity_for(participant)
        if refresh:
            client.refresh_token()
        tok, expires = client.token_info()
        return token_payload(client, tok, expires)

    def refresh_token(self, participant: str | None = None) -> dict:
        return self.token(participant, refresh=True)

    # ---- G8 ----

    def handle_inbound(
        self, path: str, body: bytes, ip: str = "", request_id: str | None = None
    ) -> receive.InboundAnswer:
        return receive.handle_inbound(self, path, body, ip, request_id)

    # ---- G11 ----

    def healthz(self, method: str = "GET", body: bytes | None = None) -> dict:
        return checks.healthz(self, method, body)

    def readyz(self) -> tuple[int, dict]:
        return checks.readyz(self)

    def check(self) -> dict:
        return checks.check(self)

    # ---- background work (G1) ----

    def refresh_all(self, deadline: float = 30.0) -> int:
        """Ask G3 for a token for every profile, default first; returns failures."""
        failures = 0
        until = time.monotonic() + deadline
        for p in self.profiles:
            if time.monotonic() > until:
                logger.error("nhcx: session token refresh failed: deadline exceeded")
                return failures + 1
            try:
                self.identity_for(p.code).token()
            except Exception as e:  # noqa: BLE001
                failures += 1
                logger.error(  # noqa: TRY400
                    "nhcx: session token refresh failed participant=%s: %s", p.code, e
                )
        return failures

    def sweep(self, now: datetime | None = None) -> int:
        n = self.ledger.sweep(now or datetime.now(UTC))
        if n > 0:
            logger.info("nhcx: ledger pruned count=%d", n)
        return n

    def _loop(self, fn: Callable[[], Any], interval: float) -> None:
        while not self._stop.is_set():
            try:
                fn()
            except Exception:
                logger.exception("nhcx: background loop failed")
            self._stop.wait(interval)

    def start(self) -> None:
        """Start the token and pruning loops as daemon threads.

        CARE runs these as Celery beat tasks instead (care/nhcx/tasks.py); this is
        for hosts without Celery.
        """
        if self._threads:
            return
        self._stop.clear()
        specs = [("nhcx-token", self.refresh_all, TOKEN_INTERVAL)]
        if self.ledger.enabled:
            specs.append(("nhcx-sweep", self.sweep, SWEEP_INTERVAL))
        for name, fn, interval in specs:
            t = threading.Thread(target=self._loop, args=(fn, interval), name=name, daemon=True)
            t.start()
            self._threads.append(t)

    def stop(self) -> None:
        self._stop.set()
        for t in self._threads:
            t.join(timeout=5)
        self._threads = []

    def log_startup(self) -> None:
        logger.info(
            "nhcx gateway embedded nhcx=%s participants=%d",
            self.cfg.url_nhcx,
            len(self.profiles.profiles),
        )
        for p in self.profiles:
            logger.info(
                "nhcx: hosting participant code=%s name=%s default=%s",
                p.code,
                p.participant.name,
                p.default,
            )
        if self.guests:
            logger.info("nhcx: hosting guests")


def open_gateway(
    config_path: str,
    receive_fn: ReceiveFn,
    *,
    host: dict[str, str] | None = None,
    guests: bool | None = None,
    version: str = "embedded",
    http: Any = None,
    token_store: Any = None,
) -> Gateway:
    """G1 `open`. No network call; raises ConfigError with the G2 messages."""
    cfg = load_config(config_path)
    held = {c.lower() for c in cfg.codes()}
    for code, name in (host or {}).items():
        code = normalize_code((code or "").strip())
        if code in ("", "@hcx") or code.lower() in held:
            continue
        cfg.participants.append(ParticipantEntry(participantId=code, name=name or ""))
        held.add(code.lower())
    if guests is True:
        cfg.guests = True
    elif guests is False:
        cfg.guests = False
    errs = validate_serve(cfg)
    if errs:
        raise ConfigError(f"{config_path}: " + "\n".join(errs))
    return Gateway(cfg, receive_fn, version=version, http=http, token_store=token_store)


