# Strict schema. `None` accepts any JSON value: the standalone-only keys the
# embedded gateway carries but neither reads nor validates (G2D).
_ANY = None
_PARTICIPANT = {
    "participantId": str,
    "name": str,
    "clientId": str,
    "clientSecret": str,
    "privateKey": str,
    "callback": _ANY,
    "callbackUrl": _ANY,
}
_SCHEMA = {
    "env": str,
    "publicUrl": str,
    "cmId": str,
    "participant": _PARTICIPANT,
    "participants": [_PARTICIPANT],
    "guests": {"callback": _ANY},
    "ledger": {
        "enabled": bool,
        "dir": str,
        "retentionDays": int,
        "storeBodies": bool,
    },
    "certs": {"cacheHours": (int, float), "refuseSelfKey": bool},
    "outboundTimeoutSeconds": (int, float),
    "maxBodyBytes": int,
    "auth": {"mode": str, "tokenTtlSeconds": int},
    "urls": {"nhcx": str, "participant": str, "sessions": str},
    "log": {"level": str, "format": _ANY},
    "callback": _ANY,
    "apiKey": str,
    "requireApiKey": _ANY,
    "listen": _ANY,
    "tls": _ANY,
    "panel": _ANY,
    "certificate": _ANY,
}

_VAR_RE = re.compile(r"\$\{([A-Za-z_][A-Za-z0-9_]*)\}")


class ConfigError(Exception):
    pass


def _check(value: Any, schema: Any, where: str) -> None:
    """Reject unknown keys and wrong types. `$comment` keys are allowed anywhere."""
    if schema is _ANY:
        return
    if isinstance(schema, dict):
        if not isinstance(value, dict):
            msg = f"{where or 'config'}: expected an object"
            raise ConfigError(msg)
        for k, v in value.items():
            if k.startswith("$comment"):
                continue
            if k not in schema:
                msg = f'unknown field "{k}"' + (f" in {where}" if where else "")
                raise ConfigError(msg)
            _check(v, schema[k], f"{where}.{k}" if where else k)
        return
    if isinstance(schema, list):
        if not isinstance(value, list):
            msg = f"{where}: expected an array"
            raise ConfigError(msg)
        for i, item in enumerate(value):
            _check(item, schema[0], f"{where}[{i}]")
        return
    types = schema if isinstance(schema, tuple) else (schema,)
    if value is None:
        return
    if isinstance(value, bool) and bool not in types:
        msg = f"{where}: wrong type"
        raise ConfigError(msg)
    if not isinstance(value, types):
        msg = f"{where}: wrong type"
        raise ConfigError(msg)


@dataclass
class ParticipantEntry:
    participantId: str = ""  # noqa: N815
    name: str = ""
    clientId: str = ""  # noqa: N815
    clientSecret: str = ""  # noqa: N815
    privateKey: str = ""  # noqa: N815

    @classmethod
    def from_dict(cls, d: dict | None) -> ParticipantEntry:
        d = d or {}
        return cls(
            participantId=d.get("participantId") or "",
            name=d.get("name") or "",
            clientId=d.get("clientId") or "",
            clientSecret=d.get("clientSecret") or "",
            privateKey=d.get("privateKey") or "",
        )


@dataclass
class Config:
    path: str = ""
    env: str = ""
    publicUrl: str = ""  # noqa: N815
    cmId: str = ""  # noqa: N815
    participant: ParticipantEntry = field(default_factory=ParticipantEntry)
    participants: list[ParticipantEntry] = field(default_factory=list)
    guests: bool = False
    ledger_enabled: bool = True
    ledger_dir: str = ""
    ledger_retention_days: int = 0
    ledger_store_bodies: bool = True
    cert_cache_hours: float = 0
    refuse_self_key: bool | None = None
    outbound_timeout: float = 0
    max_body_bytes: int = 0
    auth_mode: str = ""
    token_ttl_seconds: int = 0
    url_nhcx: str = ""
    url_participant: str = ""
    url_sessions: str = ""
    log_level: str = ""
    api_key: str = ""

    def all_participants(self) -> list[ParticipantEntry]:
        out = [self.participant]
        d = self.participant
        for p in self.participants:
            q = ParticipantEntry(**p.__dict__)
            if q.clientId == "" and q.clientSecret == "":
                q.clientId, q.clientSecret = d.clientId, d.clientSecret
            if q.privateKey.strip() == "":
                q.privateKey = d.privateKey
            out.append(q)
        return out

    def codes(self) -> list[str]:
        return [p.participantId for p in self.all_participants() if p.participantId]


def _expand(raw: str) -> tuple[str, list[str]]:
    missing: list[str] = []

    def sub(m: re.Match) -> str:
        name = m.group(1)
        if name not in os.environ:
            if name not in missing:
                missing.append(name)
            return ""
        return json.dumps(os.environ[name])[1:-1]

    return _VAR_RE.sub(sub, raw), missing


def _num(v: Any, default: float) -> Any:
    return v if isinstance(v, (int, float)) and not isinstance(v, bool) and v > 0 else default


def load_config(path: str | os.PathLike) -> Config:
    path = str(path)
    try:
        raw = Path(path).read_text(encoding="utf-8")
    except OSError as e:
        msg = f"read config: {e}"
        raise ConfigError(msg) from e
    text, missing = _expand(raw)
    if missing:
        msg = f"{path}: environment variable(s) not set: {', '.join(missing)}"
        raise ConfigError(msg)
    try:
        data = json.loads(text)
        _check(data, _SCHEMA, "")
    except (ValueError, ConfigError) as e:
        msg = f"{path}: parse config: {e}"
        raise ConfigError(msg) from e

    for var, fld in ENV_OVERRIDES:
        if var in os.environ:
            target = data
            for k in fld[:-1]:
                target = target.setdefault(k, {})
            target[fld[-1]] = os.environ[var].strip()

    cfg = _apply_defaults(path, data)

    base = Path(path).resolve().parent
    entries = [("participant", cfg.participant)] + [
        (f"participants[{i}]", p) for i, p in enumerate(cfg.participants)
    ]
    for label, entry in entries:
        key = entry.privateKey.strip()
        if key.startswith("@"):
            p = Path(key[1:])
            if not p.is_absolute():
                p = base / p
            try:
                entry.privateKey = p.read_text(encoding="utf-8")
            except OSError as e:
                msg = f"{label}.privateKey: {e}"
                raise ConfigError(msg) from e

    errors = validate(cfg)
    if errors:
        raise ConfigError(f"{path}: " + "\n".join(errors))
    return cfg


def _apply_defaults(path: str, data: dict) -> Config:
    ledger = data.get("ledger") or {}
    certs = data.get("certs") or {}
    auth = data.get("auth") or {}
    urls = data.get("urls") or {}
    log = data.get("log") or {}
    env = (data.get("env") or "").strip().lower() or "sandbox"
    table = ENV_TABLE["production" if env == "production" else "sandbox"]
    ledger_dir = (ledger.get("dir") or "").strip() or DEFAULT_LEDGER_DIR
    if not Path(ledger_dir).is_absolute():
        ledger_dir = str(Path(path).resolve().parent / ledger_dir)
    retention = ledger.get("retentionDays") or 0
    cfg = Config(
        path=path,
        env=env,
        publicUrl=(data.get("publicUrl") or "").strip(),
        cmId=(data.get("cmId") or "").strip() or table["cmId"],
        participant=ParticipantEntry.from_dict(data.get("participant")),
        participants=[ParticipantEntry.from_dict(p) for p in data.get("participants") or []],
        guests=isinstance(data.get("guests"), dict),
        ledger_enabled=ledger.get("enabled") is not False,
        ledger_dir=ledger_dir,
        ledger_retention_days=max(retention, 0),
        ledger_store_bodies=ledger.get("storeBodies") is not False,
        cert_cache_hours=_num(certs.get("cacheHours"), DEFAULT_CERT_HOURS),
        refuse_self_key=certs.get("refuseSelfKey"),
        outbound_timeout=_num(data.get("outboundTimeoutSeconds"), DEFAULT_TIMEOUT),
        max_body_bytes=_num(data.get("maxBodyBytes"), DEFAULT_MAX_BODY),
        auth_mode=(auth.get("mode") or "").strip() or "sessions",
        token_ttl_seconds=_num(auth.get("tokenTtlSeconds"), DEFAULT_TOKEN_TTL),
        url_nhcx=(urls.get("nhcx") or "").strip() or table["nhcx"],
        url_participant=(urls.get("participant") or "").strip() or table["participant"],
        url_sessions=(urls.get("sessions") or "").strip(),
        log_level=(log.get("level") or "").strip() or "info",
        api_key=(data.get("apiKey") or "").strip(),
    )
    if cfg.refuse_self_key is None:
        cfg.refuse_self_key = env == "production"
    if cfg.url_sessions == "":
        cfg.url_sessions = (
            cfg.url_participant.rstrip("/") + "/get/session"
            if cfg.auth_mode == "get-session"
            else table["sessions"]
        )
    for p in [cfg.participant, *cfg.participants]:
        p.participantId = normalize_code(p.participantId.strip())
    return cfg


def url_error(u: str) -> str | None:
    if not u:
        return "is required"
    try:
        parsed = urlparse(u)
    except ValueError:
        parsed = None
    if parsed is None or parsed.scheme not in ("http", "https") or not parsed.netloc:
        return f'"{u}" is not an absolute http(s) URL'
    return None


def validate(cfg: Config) -> list[str]:
    errs: list[str] = []
    if cfg.env not in ("sandbox", "production"):
        errs.append(f'env must be "sandbox" or "production", got "{cfg.env}"')
    d = cfg.participant
    if not d.participantId:
        errs.append("participant.participantId is required")
    if not d.clientId or not d.clientSecret:
        errs.append("participant.clientId and participant.clientSecret are required")
    if not d.privateKey.strip():
        errs.append(
            "participant.privateKey is required (PEM, base64 PEM, or @file)\n" + KEY_HINT
        )
    else:
        try:
            crypto.parse_private_key(d.privateKey)
        except crypto.CryptoError as e:
            errs.append(f"participant.privateKey is not a valid RSA private key: {e}")
    seen: dict[str, int] = {}
    for i, p in enumerate(cfg.participants):
        code = p.participantId
        if not code:
            errs.append(f"participants[{i}].participantId is required")
        else:
            low = code.lower()
            if d.participantId and low == d.participantId.lower():
                errs.append(
                    f"participants[{i}].participantId {code} duplicates participant.participantId"
                )
            elif low in seen:
                errs.append(
                    f"participants[{i}].participantId {code} duplicates participants[{seen[low]}]"
                )
            else:
                seen[low] = i
        if p.privateKey.strip():
            try:
                crypto.parse_private_key(p.privateKey)
            except crypto.CryptoError as e:
                errs.append(
                    f"participants[{i}].privateKey is not a valid RSA private key: {e}"
                )
        if bool(p.clientId) != bool(p.clientSecret):
            errs.append(
                f"participants[{i}]: clientId and clientSecret must be set together "
                "(or both left blank to inherit)"
            )
    if cfg.auth_mode not in ("sessions", "get-session"):
        errs.append(f'auth.mode must be "sessions" or "get-session", got "{cfg.auth_mode}"')
    for name, u in (
        ("urls.nhcx", cfg.url_nhcx),
        ("urls.participant", cfg.url_participant),
        ("urls.sessions", cfg.url_sessions),
    ):
        e = url_error(u)
        if e:
            errs.append(f"{name}: {e}")
    if cfg.log_level.lower() not in ("debug", "info", "warn", "warning", "error"):
        errs.append(f'log.level must be debug, info, warn or error, got "{cfg.log_level}"')
    return errs


def validate_serve(cfg: Config) -> list[str]:
    if cfg.publicUrl:
        e = url_error(cfg.publicUrl)
        if e:
            return [f"publicUrl: {e}"]
    return []


@dataclass
class Profile:

SUMMARY_FIELDS = (
    "id",
    "direction",
    "created_at",
    "path",
    "entity",
    "action",
    "kind",
    "format",
    "sender",
    "recipient",
    "correlation_id",
    "api_call_id",
    "request_id",
    "workflow_id",
    "hcx_status",
    "status",
    "error",
    "redelivery",
    "duration_ms",
)
ROW_FIELDS = (
    "id",
    "direction",
    "status",
    "sender",
    "recipient",
    "correlation_id",
    "api_call_id",
)


def b32(n: int, width: int) -> str:
    out = ""
    while n > 0:
        out = ALPHABET[n % 32] + out
        n //= 32
    return out.rjust(width, "0")


def unb32(s: str) -> int:
    n = 0
    for ch in s:
        n = n * 32 + ALPHABET.index(ch)
    return n


def day_code(t: datetime) -> str:
    t = t.astimezone(UTC)
    return b32((t.year % 100) * 10000 + t.month * 100 + t.day, 4)


def day_of_id(entry_id: str) -> str | None:
    """`YYYY-MM-DD` folder of an id (either scheme), or None if it is not an id."""
    if not isinstance(entry_id, str) or "/" in entry_id or "\\" in entry_id:
        return None
    if ID_RE.match(entry_id):
        n = unb32(entry_id[:4])
        yy, mm, dd = n // 10000, (n // 100) % 100, n % 100
        try:
            return date(2000 + yy, mm, dd).isoformat()
        except ValueError:
            return None
    if len(entry_id) >= LEGACY_ID_MIN and LEGACY_RE.match(entry_id):
        s = entry_id[:8]
        try:
            return date(int(s[:4]), int(s[4:6]), int(s[6:8])).isoformat()
        except ValueError:
            return None
    return None


def now_rfc3339(t: datetime | None = None) -> str:
    return (t or datetime.now(UTC)).astimezone().isoformat(timespec="milliseconds")


def parse_time(s: Any) -> datetime | None:
    if isinstance(s, datetime):
        return s if s.tzinfo else s.replace(tzinfo=UTC)
    if not isinstance(s, str) or not s:
        return None
    try:
        t = datetime.fromisoformat(s.replace("Z", "+00:00"))
    except ValueError:
        return None
    return t if t.tzinfo else t.replace(tzinfo=UTC)


def summarize(fhir: Any) -> dict | None:
    """`{resource_type, bundle_type, entries, resource_types, focus, identifier, patient, outcome}`."""
    if not isinstance(fhir, dict):
        return None
    out: dict[str, Any] = {"resource_type": fhir.get("resourceType")}
    resources = []
    if fhir.get("resourceType") == "Bundle":
        out["bundle_type"] = fhir.get("type")
        for e in fhir.get("entry") or []:
            r = e.get("resource") if isinstance(e, dict) else None
            if isinstance(r, dict):
                resources.append(r)
        out["entries"] = len(fhir.get("entry") or [])
    else:
        resources = [fhir]
    types: list[str] = []
    for r in resources:
        rt = r.get("resourceType")
        if isinstance(rt, str) and rt not in types:
            types.append(rt)
    out["resource_types"] = types
    focus = next(
        (
            r
            for r in resources
            if r.get("resourceType")
            in (
                "Claim",
                "ClaimResponse",
                "CoverageEligibilityRequest",
                "CoverageEligibilityResponse",
                "Task",
                "Communication",
                "CommunicationRequest",
                "PaymentNotice",
                "PaymentReconciliation",
                "InsurancePlan",
            )
        ),
        None,
    )
    if focus:
        out["focus"] = focus.get("resourceType")
        ident = focus.get("identifier")
        if isinstance(ident, list) and ident and isinstance(ident[0], dict):
            out["identifier"] = ident[0].get("value")
        elif isinstance(ident, dict):
            out["identifier"] = ident.get("value")
        pat = focus.get("patient")
        if isinstance(pat, dict):
            out["patient"] = pat.get("reference")
        if focus.get("outcome") is not None:
            out["outcome"] = focus.get("outcome")
    return out


class _FileLock:
    def __init__(self, path: Path):
        self.path = path
        self.local = threading.RLock()
        self.depth = 0
        self.fd: int | None = None

    def __enter__(self):
        self.local.acquire()
        if self.depth == 0:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            self.fd = os.open(self.path, os.O_RDWR | os.O_CREAT, 0o640)
            fcntl.flock(self.fd, fcntl.LOCK_EX)
        self.depth += 1
        return self

    def __exit__(self, *exc):
        self.depth -= 1
        if self.depth == 0 and self.fd is not None:
            try:
                fcntl.flock(self.fd, fcntl.LOCK_UN)
            finally:
                os.close(self.fd)
                self.fd = None
        self.local.release()


class Ledger:
    def __init__(
        self,
        directory: str | os.PathLike | None,
        *,
        enabled: bool = True,
        store_bodies: bool = True,
        retention_days: int = 0,
    ):
        self.enabled = bool(enabled and directory)
        self.dir = Path(directory) if directory else None
        self.store_bodies = store_bodies
        self.retention_days = max(int(retention_days or 0), 0)
        self.mu = threading.RLock()
        self.summaries: dict[str, dict] = {}
        self.ids: list[str] = []
        self.by_corr: dict[str, list[str]] = {}
        self.seen_set: set[str] = set()
        self.day_ids: dict[str, list[str]] = {}
        self.offsets: dict[str, int] = {}
        self.flock = _FileLock(self.dir / ".lock") if self.dir else None
        if self.enabled:
            self.dir.mkdir(parents=True, exist_ok=True)
            self.refresh()

    # ---- index maintenance ----

    def _drop_day(self, day: str) -> None:
        for i in self.day_ids.pop(day, []):
            s = self.summaries.pop(i, None)
            with contextlib.suppress(ValueError):
                self.ids.remove(i)
            if s:
                c = s.get("correlation_id") or ""
                lst = self.by_corr.get(c)
                if lst and i in lst:
                    lst.remove(i)
                    if not lst:
                        self.by_corr.pop(c, None)
                if s.get("api_call_id"):
                    self.seen_set.discard(f"{s.get('direction')}:{s.get('api_call_id')}")
        self.offsets.pop(day, None)

    def _index(self, s: dict, day: str) -> None:
        i = s.get("id")
        if not i or i in self.summaries:
            return
        self.summaries[i] = s
        if not self.ids or i > self.ids[-1]:
            self.ids.append(i)
        else:
            insort(self.ids, i)
        self.day_ids.setdefault(day, []).append(i)
        c = s.get("correlation_id") or ""
        if c:
            insort(self.by_corr.setdefault(c, []), i)
        if s.get("api_call_id"):
            self.seen_set.add(f"{s.get('direction')}:{s.get('api_call_id')}")

    def refresh(self) -> None:
        """Bring the in-memory indexes up to date with every process's appends."""
        if not self.enabled:
            return
        with self.mu:
            try:
                days = sorted(
                    p.name for p in self.dir.iterdir() if p.is_dir() and DAY_RE.match(p.name)
                )
            except FileNotFoundError:
                days = []
            for gone in set(self.offsets) - set(days):
                self._drop_day(gone)
            for day in days:
                idx = self.dir / day / "index.jsonl"
                off = self.offsets.get(day, 0)
                try:
                    size = idx.stat().st_size
                except FileNotFoundError:
                    continue
                if size < off:
                    self._drop_day(day)
                    off = 0
                if size == off:
                    self.offsets[day] = off
                    continue
                with idx.open("rb") as f:
                    f.seek(off)
                    data = f.read()
                end = data.rfind(b"\n") + 1
                for line in data[:end].splitlines():
                    if not line.strip():
                        continue
                    try:
                        s = json.loads(line)
                    except ValueError:
                        logger.warning("nhcx: unreadable ledger index line in %s", idx)
                        continue
                    if isinstance(s, dict):
                        self._index(s, day)
                self.offsets[day] = off + end

    # ---- writing ----

    def _next_id(self, t: datetime) -> str:
        day = day_code(t)
        top = 0
        lo = day + "0000"
        hi = day + "VVVV"
        for i in reversed(self.ids):
            if i <= hi and len(i) == ID_LEN:
                if i >= lo:
                    top = unb32(i[4:])
                break
        return day + b32(top + 1, 4)

    def record(self, e: dict) -> str | None:
        """Write one entry; returns its id. Errors propagate (the caller only logs)."""
        if not self.enabled:
            return None
        e = dict(e)
        t = parse_time(e.get("created_at")) or datetime.now(UTC)
        e["created_at"] = now_rfc3339(t)
        e["path"] = clean_path(e.get("path"))
        e["entity"] = e.get("entity") or entity_type(e["path"])
        e["action"] = e.get("action") or e["path"].split("/")[-1]
        e["kind"] = e.get("kind") or (
            "response" if is_response_path(e["path"]) else "request"
        )
        if e.get("fhir") is not None and not e.get("fhir_summary"):
            e["fhir_summary"] = summarize(e.get("fhir"))
        if not self.store_bodies:
            e["fhir"] = None
            if isinstance(e.get("peer"), dict):
                e["peer"] = {**e["peer"], "response": None}
        e.setdefault("redelivery", False)
        e.setdefault("duration_ms", 0)
        day = t.astimezone(UTC).date().isoformat()
        with self.mu, self.flock:
            self.refresh()
            if not e.get("id"):
                e["id"] = self._next_id(t)
            folder = self.dir / day
            folder.mkdir(parents=True, exist_ok=True)
            path = folder / f"{e['id']}.json"
            fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o640)
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(e, f, indent=2, ensure_ascii=False, default=str)
            summary = {k: e.get(k) for k in SUMMARY_FIELDS}
            with (folder / "index.jsonl").open("ab") as f:
                f.write(
                    json.dumps(summary, ensure_ascii=False, default=str).encode() + b"\n"
                )
            self.refresh()
        return e["id"]

    # ---- reads ----

    def _require(self) -> None:
        if not self.enabled:
            raise GatewayError("LEDGER_DISABLED", "the ledger is off")

    def get(self, entry_id: str) -> dict | None:
        self._require()
        day = day_of_id((entry_id or "").strip())
        if day is None:
            return None
        path = self.dir / day / f"{entry_id.strip()}.json"
        try:
            raw = path.read_bytes()
        except (FileNotFoundError, NotADirectoryError):
            return None
        try:
            out = json.loads(raw)
        except ValueError as e:
            raise GatewayError("LEDGER_CORRUPT", f"ledger entry {entry_id} is corrupt") from e
        return out

    def _entry(self, txn_id: str) -> dict:
        self._require()
        txn_id = (txn_id or "").strip() if isinstance(txn_id, str) else ""
        if not txn_id:
            raise GatewayError("NO_TXN_ID", "txn_id is required")
        e = self.get(txn_id)
        if e is None:
            raise GatewayError("TXN_NOT_FOUND", f"no transaction {txn_id} in the ledger")
        return e

    @staticmethod
    def row(s: dict) -> dict:
        out = {k: s.get(k) for k in ROW_FIELDS}
        out["type"] = s.get("entity")
        out["flow"] = s.get("action")
        out["created_at"] = s.get("created_at")
        return out

    def list_summaries(self, correlation_id: str | None = None, limit: int = 50) -> list[dict]:
        self.refresh()
        with self.mu:
            ids = self.by_corr.get(correlation_id, []) if correlation_id else self.ids
            return [self.summaries[i] for i in reversed(ids[-limit:]) if i in self.summaries]

    def related(self, txn_id: str) -> list[dict]:
        e = self._entry(txn_id)
        return [
            self.row(s)
            for s in self.list_summaries(e.get("correlation_id") or None, RELATED_LIMIT)
        ]

    def fhir(self, txn_id: str) -> dict:
        e = self._entry(txn_id)
        return {
            "meta": {
                "type": "in" if e.get("direction") == "in" else "out",
                "payloadType": e.get("format"),
                "path": e.get("path"),
                "time": e.get("created_at"),
            },
            "jwe_headers": e.get("headers"),
            "fhir": e.get("fhir"),
        }

    def dispatch(self, txn_id: str) -> dict:
        e = self._entry(txn_id)
        status = e.get("status")
        out: dict[str, Any] = {"txnId": e.get("id"), "status": status}
        if status in ("failed", "rejected"):
            out["status"] = "dispatch_failed"
        elif status in ("accepted", "delivered"):
            out["status"] = "dispatched"
        err = e.get("error")
        if isinstance(err, dict) and err:
            out["errorCode"] = err.get("code")
            out["errorMessage"] = err.get("message")
        return out

    def list(self, limit: Any = LIST_DEFAULT) -> list[dict]:
        if not self.enabled:
            return []
        if not isinstance(limit, int) or isinstance(limit, bool) or not 1 <= limit <= LIST_MAX:
            limit = LIST_DEFAULT
        return [self.row(s) for s in self.list_summaries(None, limit)]

    def seen(self, direction: str, api_call_id: str) -> bool:
        if not self.enabled or not api_call_id:
            return False
        self.refresh()
        with self.mu:
            return f"{direction}:{api_call_id}" in self.seen_set

    def last_inbound_request(
        self, entity: str, sender: str | None = None, workflow_id: str | None = None
    ) -> dict | None:
        if not self.enabled:
            return None
        self.refresh()
        with self.mu:
            for i in reversed(self.ids):
                s = self.summaries.get(i) or {}
                if (
                    s.get("direction") != "in"
                    or s.get("kind") != "request"
                    or s.get("entity") != entity
                    or not s.get("correlation_id")
                ):
                    continue
                if sender and not same_code(s.get("sender"), sender):
                    continue
                if workflow_id and s.get("workflow_id") != workflow_id:
                    continue
                return dict(s)
        return None

    def thread(self, correlation_id: str) -> dict | None:
        self._require()
        msgs = list(reversed(self.list_summaries(correlation_id, 10**6))) if correlation_id else []
        if not msgs:
            return None
        first = msgs[0]
        first_out = first.get("direction") == "out"
        if first.get("kind") == "response":
            first_out = not first_out
        state = "unknown"
        for m in msgs:
            hs = m.get("hcx_status") or ""
            is_resp = m.get("kind") == "response"
            if (
                m.get("status") in ("failed", "rejected")
                or (is_resp and m.get("status") == "delivery_failed")
                or m.get("format") == "protocol"
                or "error" in hs
            ):
                state = "error"
            elif not is_resp and m.get("direction") == "out":
                state = "awaiting_response"
            elif not is_resp and m.get("direction") == "in":
                state = "awaiting_our_response"
            elif is_resp and hs == "response.partial":
                state = "partial"
            elif is_resp:
                state = "completed"
        last = msgs[-1]
        counterparty = (
            first.get("recipient") if first.get("direction") == "out" else first.get("sender")
        )
        return {
            "correlation_id": correlation_id,
            "entity": first.get("entity"),
            "workflow_id": next((m.get("workflow_id") for m in msgs if m.get("workflow_id")), None),
            "counterparty": counterparty,
            "role": "initiator" if first_out else "responder",
            "state": state,
            "started": first.get("created_at"),
            "updated": last.get("created_at"),
            "messages": msgs,
        }

    def sweep(self, now: datetime | None = None) -> int:
        """Delete day folders older than the retention period; returns how many."""
        if not self.enabled or self.retention_days == 0:
            return 0
        now = now or datetime.now(UTC)
        cutoff = (now.astimezone(UTC) - timedelta(days=self.retention_days)).date().isoformat()
        removed = 0
        with self.mu, self.flock:
            for p in sorted(self.dir.iterdir()):
                if p.is_dir() and DAY_RE.match(p.name) and p.name < cutoff:
                    shutil.rmtree(p, ignore_errors=True)
                    self._drop_day(p.name)
                    removed += 1
        if removed:
            logger.info("nhcx: ledger pruned %d day folder(s) before %s", removed, cutoff)
        return removed

HTTP_OK = 200


def probe_key(participant_id: str, client_secret: str, api_key: str) -> bytes:
    text = f"nhcx-adapter probe v1\0{participant_id}\0{client_secret}\0{api_key}"
    return hashlib.sha256(text.encode("utf-8")).digest()


def ack(key: bytes, nonce: str) -> str:
    return hmac.new(key, nonce.encode("utf-8"), hashlib.sha256).hexdigest()


def verify(key: bytes, nonce: str, answer: str) -> bool:
    return hmac.compare_digest(ack(key, nonce), answer or "")


def gateway_probe_key(gw: Gateway) -> bytes:
    d = gw.cfg.participant
    return probe_key(d.participantId, d.clientSecret, gw.cfg.api_key)


def healthz(gw: Gateway, method: str = "GET", body: bytes | None = None) -> dict:
    out = {
        "status": "ok",
        "service": SERVICE,
        "version": gw.version,
        "env": gw.cfg.env,
        "participant": gw.profiles.default.code,
    }
    if method.upper() == "POST" and body:
        try:
            req = json.loads(body[:HEALTH_BODY_LIMIT])
        except (ValueError, TypeError, UnicodeDecodeError):
            req = None
        nonce = req.get("probe") if isinstance(req, dict) else None
        if isinstance(nonce, str) and 0 < len(nonce) <= MAX_NONCE:
            out["probe_ack"] = ack(gateway_probe_key(gw), nonce)
    return out


def readyz(gw: Gateway) -> tuple[int, dict]:
    if gw.default_client.token_valid():
        return 200, {"status": "ready"}
    return 503, {"status": "no session token"}


def explain(e: BaseException) -> str:
    g = as_gateway_error(e)
    text = f"{g.code}: {g.message}"
    if g.body:
        text += f" ({g.body})"
    return text


def run_checks(gw: Gateway) -> dict:
    report: dict[str, Any] = {"checks": [], "cert": "unknown", "participant": None}

    def add(name: str, ok: bool, detail: str) -> None:
        report["checks"].append({"name": name, "ok": ok, "detail": detail})

    client = gw.default_client

"""G10. Beneficiary registry: policy search and ABHA link pass-through."""

from __future__ import annotations

import json
from typing import Any

from care.nhcx.gateway.errors import GatewayError


def _s(v: Any) -> str:
    return v.strip() if isinstance(v, str) else ""


class BeneficiaryRegistry:
    """Runs as the default participant, whichever facility asks (G10D)."""

    def __init__(self, client: Any):
        self.client = client

    def post_registry(self, path: str, body: Any) -> dict:
        status, raw = self.client.post_registry(path, body)
        try:
            parsed = json.loads(raw)
        except (ValueError, TypeError):
            text = raw.decode("utf-8", errors="replace") if isinstance(raw, bytes) else raw
            parsed = {"error": text or ""}
        return {"status": status, "body": parsed}

    def policies_search(self, query: dict) -> dict:
        query = query or {}
        kind, value = _s(query.get("identifiertype")), _s(query.get("identifiervalue"))
        if kind == "":
            if _s(query.get("mobile")):
                kind, value = "MobileNo", _s(query.get("mobile"))
            elif _s(query.get("abhaNo")):
                kind, value = "AbhaNumber", _s(query.get("abhaNo"))
        if value == "":
            raise GatewayError(
                "NO_IDENTIFIER", "identifiervalue (or mobile / abhaNo) is required"
            )
        return self.post_registry(
            "participant/get/policies", {"identifiertype": kind, "identifiervalue": value}
        )

    def abha_link(self, body: Any) -> dict:
        return self.post_registry("participant/link/abha/policy", body)

    def abha_delink(self, body: Any) -> dict:
        return self.post_registry("participant/delink/abha/policy", body)

"""NHCX-facing HTTP routes (G1, G8, G11): no auth, CSRF exempt, no request transaction."""

from __future__ import annotations

import functools
import logging
import uuid

from django.db import transaction
from django.http import HttpRequest, JsonResponse
from django.views.decorators.csrf import csrf_exempt
from django.views.decorators.http import require_http_methods

from care.nhcx.gateway import gateway_status
from care.nhcx.gateway.errors import GatewayError
from care.nhcx.gateway.receive import error_body, not_open_answer

logger = logging.getLogger("care.nhcx.gateway")

MAX_REQUEST_ID = 128
DEFAULT_MAX_BODY = 100 * 1024 * 1024
HEALTH_BODY_LIMIT = 4096


class _BodyTooLarge(Exception):
    pass


def _request_id(request: HttpRequest) -> str:
    rid = (request.headers.get("X-Request-Id") or "").strip()
    if rid and len(rid) <= MAX_REQUEST_ID:
        return rid
    return str(uuid.uuid4())


def _answer(status: int, body: dict, rid: str, headers: dict | None = None) -> JsonResponse:
    resp = JsonResponse(body, status=status, json_dumps_params={"ensure_ascii": False})
    resp["X-Request-Id"] = rid
    for k, v in (headers or {}).items():
        resp[k] = v
    return resp


def _read_body(request: HttpRequest, limit: int) -> bytes:
    try:
        declared = int(request.headers.get("Content-Length") or 0)
    except ValueError:
        declared = 0
    if declared > limit:
        raise _BodyTooLarge
    data = request.read(limit + 1)
    if len(data) > limit:
        raise _BodyTooLarge
    return data


def gateway_route(view):
    """Panic recovery, then the request id; the body cap is applied in each view."""

    @functools.wraps(view)
    def wrapped(request: HttpRequest, *args, **kwargs):
        rid = _request_id(request)
        request.nhcx_request_id = rid
        try:
            return view(request, rid, *args, **kwargs)
        except Exception:
            logger.exception("nhcx: gateway route failed path=%s", request.path)
            return _answer(
                500,
                {"ok": False, "error": {"code": "INTERNAL", "message": "internal error"}},
                rid,
            )

    return csrf_exempt(transaction.non_atomic_requests(wrapped))


@gateway_route
@require_http_methods(["POST"])
def inbound(request: HttpRequest, rid: str, path: str = "", prefix: str = ""):
    gw, _ = gateway_status()
    limit = gw.cfg.max_body_bytes if gw else DEFAULT_MAX_BODY
    full_path = prefix + path
    try:
        body = _read_body(request, limit)
    except _BodyTooLarge:
        err = GatewayError("BODY_TOO_LARGE", f"request body exceeds {limit} bytes")
        return _answer(413, error_body(err, rid), rid)
    except OSError as e:
        err = GatewayError("BODY_READ", "request body could not be read", cause=e)
        return _answer(400, error_body(err, rid), rid)
    ip = request.META.get("REMOTE_ADDR", "")
    ans = (
        gw.handle_inbound(full_path, body, ip, rid)
        if gw
        else not_open_answer(full_path, body)
    )
    return _answer(ans.status, ans.body, rid, ans.headers)


@gateway_route
@require_http_methods(["GET", "POST"])
def healthz(request: HttpRequest, rid: str):
    gw, cause = gateway_status()
    body = b""
    if request.method == "POST":
        try:
            body = request.read(HEALTH_BODY_LIMIT)
        except OSError:
            body = b""
    if gw is None:
        return _answer(
            200,
            {
                "status": "ok",
                "service": "nhcx-adapter",
                "version": "embedded",
                "gateway": f"gateway not configured: {cause}",
            },
            rid,
        )
    return _answer(200, gw.healthz(request.method, body), rid)


@gateway_route
@require_http_methods(["GET"])
def readyz(request: HttpRequest, rid: str):
    gw, cause = gateway_status()
    if gw is None:
        return _answer(503, {"status": f"gateway not configured: {cause}"}, rid)
    status, body = gw.readyz()
    return _answer(status, body, rid)

def normalize_code(code: Any) -> str:
    code = (code or "").strip() if isinstance(code, str) else ""
    if code == "" or code.endswith(HCX_SUFFIX):
        return code
    return code + HCX_SUFFIX


def same_code(a: Any, b: Any) -> bool:
    return normalize_code(a).lower() == normalize_code(b).lower()


def clean_path(path: Any) -> str:
    return (path or "").strip().strip("/") if isinstance(path, str) else ""


def new_id() -> str:
    return str(uuid.uuid4())


def is_id(s: Any) -> bool:
    if not isinstance(s, str):
        return False
    s = s.strip()
    if len(s) != UUID_LENGTH:
        return False
    try:
        uuid.UUID(s)
    except ValueError:
        return False
    return True


def ensure_id(s: Any) -> str:
    return s.strip() if is_id(s) else new_id()


def _segments(path: str) -> list[str]:
    return clean_path(path).split("/")


def is_response_path(path: Any) -> bool:
    return _segments(path)[-1].startswith("on_")


def default_status(path: Any) -> str:
    return STATUS_RESPONSE if is_response_path(path) else STATUS_REQUEST


def entity_type(path: Any) -> str:
    segs = _segments(path)
    if len(segs) == 1:
        e = segs[0]
    else:
        e = segs[-2]
        if e == "v1":
            e = segs[-1]
    e = e.removeprefix("on_")
    return "payment" if e == "paymentnotice" else e


def get_string(headers: Any, key: str) -> str:
    if not isinstance(headers, dict):
        return ""
    v = headers.get(key)
    return v.strip() if isinstance(v, str) else ""


def build_protected_headers(given: Any, path: str) -> dict:
    out: dict = {}
    for k, v in (given or {}).items():
        if isinstance(v, str):
            if v.strip() != "":
                out[k] = v.strip()
        elif v is not None:
            out[k] = v
    for k in (SENDER_CODE, RECIPIENT_CODE):
        c = normalize_code(get_string(out, k))
        if c:
            out[k] = c
        else:
            out.pop(k, None)
    out[CORRELATION_ID] = ensure_id(get_string(out, CORRELATION_ID))
    out[REQUEST_ID] = ensure_id(get_string(out, REQUEST_ID))
    out[API_CALL_ID] = ensure_id(get_string(out, API_CALL_ID))
    if get_string(out, STATUS) == "":
        out[STATUS] = default_status(path)
    if get_string(out, TIMESTAMP) == "":
        out[TIMESTAMP] = timestamp()
    if get_string(out, WORKFLOW_ID) == "":
        out.pop(WORKFLOW_ID, None)
    return out


def timestamp(now: datetime | None = None) -> str:
    """`YYYY-MM-DDThh:mm:ss+hhmm`, process local time zone."""
    now = (now or datetime.now()).astimezone()
    return now.strftime("%Y-%m-%dT%H:%M:%S%z")


def ack_timestamp(t: datetime | None = None) -> str:
    """`DD/MM/YYYY hh:mm:ss:mmm` for the 202 acceptance body (G8)."""
    t = (t or datetime.now()).astimezone()
    return t.strftime("%d/%m/%Y %H:%M:%S") + f":{t.microsecond // 1000:03d}"


def target_url(base: str, path: str) -> str:
    base = (base or "").strip().rstrip("/")
    path = clean_path(path)
    if path == "":
        return base
    if base.endswith("/v1") and path.startswith("v1/"):
        base = base[: -len("/v1")]
    return base + "/" + path

