class TokenCache:
    """In-memory token map, guarded by one lock (G3D).

    `shared` is an optional Django-cache-like store (`get`/`set`) so the
    refresher in one process (the Celery role) warms the token for the web
    workers; nothing else is persisted.
    """

    def __init__(self, shared: Any = None):
        self.lock = threading.RLock()
        self.tokens: dict[str, tuple[str, float]] = {}
        self.shared = shared

    @staticmethod
    def _shared_key(key: str) -> str:
        return "nhcx:token:" + hashlib.sha256(key.encode()).hexdigest()

    def get(self, key: str) -> tuple[str, float] | None:
        e = self.tokens.get(key)
        if self.shared is not None and (e is None or e[1] - time.time() <= FRESH_MARGIN):
            try:
                s = self.shared.get(self._shared_key(key))
            except Exception:  # noqa: BLE001
                s = None
            if isinstance(s, (list, tuple)) and len(s) == 2 and (e is None or s[1] > e[1]):  # noqa: PLR2004
                e = (s[0], float(s[1]))
                self.tokens[key] = e
        return e

    def put(self, key: str, token: str, expires: float) -> None:
        self.tokens[key] = (token, expires)
        if self.shared is not None:
            try:
                self.shared.set(
                    self._shared_key(key),
                    (token, expires),
                    timeout=max(int(expires - time.time()), 1),
                )
            except Exception:  # noqa: BLE001
                logger.warning("nhcx: shared token cache unavailable", exc_info=True)


class SendError(GatewayError):
    """G7S `SendError`: code, message, retryable, upstream status/body and the ids."""

    def __init__(
        self,
        code: str,
        message: str,
        *,
        retryable: bool = False,
        upstream_status: int | None = None,
        upstream_body: Any = None,
        cause: Any = None,
        ledger_id: str | None = None,
        headers: dict | None = None,
    ):
        super().__init__(
            code,
            message,
            retryable=retryable,
            status=upstream_status,
            body=None,
            cause=cause,
        )
        self.upstream_status = upstream_status
        self.upstream_body = json_or_text(upstream_body) if isinstance(
            upstream_body, (str, bytes)
        ) else upstream_body
        self.ledger_id = ledger_id
        self.txn_id = ledger_id
        self.headers = headers
        h = headers or {}
        self.correlation_id = h.get("x-hcx-correlation_id")
        self.api_call_id = h.get("x-hcx-api_call_id")
        self.request_id = h.get("x-hcx-request_id") or None

    @property
    def names_ids(self) -> bool:
        return self.headers is not None

    @classmethod
    def from_error(
        cls, err: BaseException, *, ledger_id=None, headers=None
    ) -> SendError:
        g = as_gateway_error(err)
        return cls(
            g.code,
            g.message,
            retryable=g.retryable,
            upstream_status=g.status,
            upstream_body=g.body,
            cause=g.cause,
            ledger_id=ledger_id,
            headers=headers,
        )

    def to_dict(self) -> dict:
        out = {"code": self.code, "message": self.message, "retryable": self.retryable}
        if self.upstream_status is not None:
            out["upstream_status"] = self.upstream_status
        if self.upstream_body is not None:
            out["upstream_body"] = self.upstream_body
        if self.headers is not None:
            out["ledger_id"] = self.ledger_id or ""
            out["txn_id"] = self.ledger_id or ""
            out["headers"] = self.headers
            out["correlation_id"] = self.correlation_id
            out["api_call_id"] = self.api_call_id
            if self.request_id:
                out["request_id"] = self.request_id
        return out


