    <div className="grid grid-cols-2 gap-3 lg:grid-cols-3">{children}</div>
  );
}

export function Muted({
  children,
  className,
}: {
  children: ReactNode;
  className?: string;
}) {
  return <p className={cn("text-sm text-gray-500", className)}>{children}</p>;
}

export function ErrorText({ children }: { children: ReactNode }) {
  return <p className="text-sm text-red-700 whitespace-pre-wrap">{children}</p>;
}

// A button that asks for confirmation first when `confirm` is set.
export function ConfirmButton({
  confirm,
  title,
  onConfirm,
  children,
  variant = "primary",
  size = "sm",
  disabled,
  className,
}: {
  confirm?: string;
  title?: string;
  onConfirm: () => void;
  children: ReactNode;
  variant?: ButtonVariant;
  size?: "sm" | "default" | "xs";
  disabled?: boolean;
  className?: string;
}) {
  const { t } = useTranslation();
  const [open, setOpen] = useState(false);
  return (
    <>
      <Button
        type="button"
        variant={variant}
        size={size}
        disabled={disabled}
        className={className}
        onClick={() => (confirm ? setOpen(true) : onConfirm())}
      >
        {children}
      </Button>
      {confirm && (
        <ConfirmActionDialog
          open={open}
          onOpenChange={setOpen}
          title={title || t("confirm")}
          description={confirm}
          confirmText={t("confirm")}
          variant={variant === "destructive" ? "destructive" : "primary"}
          onConfirm={() => {
            setOpen(false);
            onConfirm();
          }}
        />
      )}
    </>
  );
}

