      </form>

      <Card>
        <CardHeader>
          <CardTitle>{t("nhcx_n_in_master", { n: filtered.length })}</CardTitle>
        </CardHeader>
        <CardContent>
          {!filtered.length ? (
            <Muted>{t("nhcx_nothing_matches")}</Muted>
          ) : (
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>{t("nhcx_code")}</TableHead>
                    <TableHead>{t("nhcx_package")}</TableHead>
                    <TableHead>{t("nhcx_speciality")}</TableHead>
                    <TableHead>{t("nhcx_type")}</TableHead>
                    <TableHead className="text-right">
                      {t("nhcx_rate")}
                    </TableHead>
                    <TableHead />
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filtered.slice((page - 1) * PAGE, page * PAGE).map((b) => (
                    <TableRow key={b.id}>
                      <TableCell>{b.code}</TableCell>
                      <TableCell>{b.display || b.code}</TableCell>
                      <TableCell>
                        {b.category_display || b.category_code || "-"}
                      </TableCell>
                      <TableCell>
                        <Chip tone={b.kind === "Procedure" ? "info" : "warning"}>
                          {b.kind}
                        </Chip>
                      </TableCell>
                      <TableCell className="text-right">
                        {formatMoney(b.rate)}
                      </TableCell>
                      <TableCell className="text-right">
                        {(b.kind === "Procedure" || b.kind === "Implant") && (
                          <Button
                            size="xs"
                            variant="primary"
                            disabled={add.isPending}
                            onClick={() =>
                              addLine({ kind: b.kind, code: b.code })
                            }
                          >
                            <Plus className="size-3" />
                            {t("add")}
                          </Button>
                        )}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
              {pages > 1 && (
                <div className="mt-3 flex items-center gap-3 text-sm">
                  <Button
                    size="sm"
                    variant="outline"
                    disabled={page <= 1}
                    onClick={() => setPage(page - 1)}
                  >
                    {t("previous")}
                  </Button>
                  <span>{t("nhcx_page_of", { page, pages })}</span>
                  <Button
                    size="sm"
                    variant="outline"
                    disabled={page >= pages}
                    onClick={() => setPage(page + 1)}
                  >
                    {t("next")}
                  </Button>
                </div>
              )}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

