                          )}
                        </TableCell>
                        <TableCell>
                          <Input
                            key={`${inputKey}-${r.code}`}
                            type="file"
                            accept={UPLOAD_TYPES.join(",")}
                            onChange={(e) =>
                              setPicked((cur) => ({
                                ...cur,
                                [r.code]: e.target.files?.[0] ?? null,
                              }))
                            }
                          />
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            </div>
            <Muted>{t("nhcx_documents_payer_named_note")}</Muted>
            <Button
              size="sm"
              variant="primary"
              disabled={attachRequired.isPending}
              onClick={submitRequired}
            >
              <Paperclip className="size-4" />
              {t("nhcx_attach_chosen_files")}
