class AdjudicatorError(common.ServiceRefusal):
    pass


def enabled() -> bool:
    return bool(getattr(settings, "NHCX_ADJUDICATOR_CONSOLE", False))


def _s(value) -> str:
    return "" if value is None else str(value).strip()


def _norm(text) -> str:
    return re.sub(r"[^a-z0-9]", "", _s(text).lower())


def _bare(code) -> str:
    return _s(code).split("@", 1)[0]


def step_for(role):
    key = _norm(role)
    return (
        next((row for row in WORKFLOW if _norm(row["role"]) == key), None)
        if key
        else None
    )


# ---- A16 ----


def token(claim) -> str:
    configured = _s(getattr(settings, "NHCX_PAYER_SERVICE_TOKEN", ""))
    if configured:
        return configured
    from care.nhcx.gateway import get_gateway

    profile = common.facility_profile(claim.facility)
    participant = _s(profile.participant_code) if profile else ""
    try:
        answer = get_gateway().token(participant or None)
    except Exception as e:
        raise AdjudicatorError(
            NO_TOKEN.format(
                code=getattr(e, "code", type(e).__name__),
                message=getattr(e, "message", None) or str(e),
            )
        ) from e
    return _s(answer.get("token") if isinstance(answer, dict) else answer)


# ---- extraction ----


def _flat(payload) -> dict:
    return (
        {_norm(k): v for k, v in payload.items()} if isinstance(payload, dict) else {}
    )


def extract_role(payload) -> str:
    if isinstance(payload, list):
        return extract_role(payload[0]) if payload else ""
    if not isinstance(payload, dict):
        return ""
    flat = _flat(payload)
    for key in ROLE_KEYS:
        if isinstance(flat.get(key), str) and flat[key].strip():
            return flat[key].strip()
    for key, value in flat.items():
        if "role" in key and isinstance(value, str) and value.strip():
            return value.strip()
    for key in ("data", "result", "response", "payload"):
        found = extract_role(flat.get(key))
        if found:
            return found
    return ""


def extract_error(payload, *, failed) -> str:
    flat = _flat(payload)
    keys = ERROR_KEYS + (("message",) if failed else ())
    for key in keys:
        if isinstance(flat.get(key), str) and flat[key].strip():
            return flat[key].strip()
    return ""


def _http(method, url, *, headers=None, body=None):
    try:
        resp = requests.request(
            method, url, headers=headers, json=body, timeout=TIMEOUT
        )
    except requests.RequestException as e:
        raise AdjudicatorError(
            UNREACHABLE.format(url=url, reason=str(e) or type(e).__name__)
        ) from e
    raw = resp.text or ""
    try:
        data = resp.json()
    except ValueError:
        data = None
    return resp.status_code, data, raw


def _service_headers(tok) -> dict:
    return {
        "Content-Type": "application/json",
        "accept": "application/json",
        "Authorization": "Bearer " + tok,
        "bearer_auth": "Bearer " + tok,
    }


# ---- A14 ----


def leg(claim, stage) -> dict | None:
    model = ClaimPreauth if stage == "preauth" else ClaimSubmission
    row = (
        model.objects.filter(claim=claim)
        .exclude(correlation_id__isnull=True)
        .exclude(correlation_id="")
        .first()
    )
    if row is None:
        return None
    adapter = payers.adapter_for_claim(claim)
    case_number = _s(row.claim_ref) or claim.claim_no
    if adapter.desk == "nhcx-payer-service":
        pre = ClaimPreauth.objects.filter(claim=claim).first()
        reference = _s(pre.preauth_ref) if pre else ""
        if "/" in reference:
            case_number = reference.rsplit("/", 1)[-1]
        elif reference:
            case_number = reference
    elif (
        adapter.desk == "irdai-payer"
        and _s(getattr(row, "preauth_ref", ""))
        and stage == "preauth"
    ):
        case_number = _s(row.preauth_ref)
    return {
        "row": row,
        "stage": stage,
        "case_number": case_number,
        "payer_code": _bare(claim.payer_id or common.default_payer_code()),
        "full_payer_code": _s(claim.payer_id) or common.default_payer_code(),
        "correlation_id": _s(row.correlation_id),
        "member_id": _s(claim.member_id),
        "desk": adapter.desk,
        "adapter": adapter,
    }


def _no_desk(claim):
    name = (
        _s(claim.payer_name)
        or payers.registry_name(claim.payer_id)
        or _s(claim.payer_id)
    )
    return AdjudicatorError(NO_DESK.format(name=name))


def role_for(claim, case_number, payer_code=None) -> dict:
    case_number = _s(case_number)
    if not case_number:
        raise AdjudicatorError(NO_CASE_NUMBER)
    payer_code = _bare(payer_code or claim.payer_id or common.default_payer_code())
    desk = payers.adapter_for_claim(claim).desk
    if desk == "irdai-payer":
        return irdai_role(claim, case_number)
    if desk != "nhcx-payer-service":
        raise _no_desk(claim)
    tok = token(claim)
    url = _s(getattr(settings, "NHCX_PAYER_SERVICE_USER_ROLE_URL", "")) or ROLE_URL
    status, data, raw = _http(
        "POST",
        url,
        headers=_service_headers(tok),
        body={"caseid": case_number, "payerid": payer_code},
    )
    reply = {
        "caseNumber": case_number,
        "payerCode": payer_code,
        "status": status,
        "response": data,
        "raw": raw if data is None else None,
        "transport": "nhcx-payer-service",
        "role": "",
    }
    if status >= HTTP_REDIRECT:
        reply["error"] = f"the payer service returned {status}: " + (
            extract_error(data, failed=True) or raw[:200]
        )
    else:
        reply["role"] = extract_role(data)
        error = extract_error(data, failed=False)
        if error:
            reply["error"] = error
    role = _s(reply["role"])
    step = step_for(role)
    if step:
        reply["step"] = step
    elif role:
        reply["warning"] = ROLE_WARNING.format(role=role)
    elif not reply.get("error"):
        reply["warning"] = NO_ROLE_WARNING
    return reply


def _desk_token(claim, payer_full) -> str:
    key = DESK_TOKEN_KEY.format(code=_norm(payer_full))
    kept = cache.get(key)
    if kept:
        return kept
    from care.nhcx.gateway import get_gateway

    try:
        session = _s(get_gateway().token().get("token"))
    except Exception as e:
        raise AdjudicatorError(
            NO_TOKEN.format(
                code=getattr(e, "code", type(e).__name__),
                message=getattr(e, "message", None) or str(e),
            )
        ) from e
    status, data, raw = _http(
        "POST", DESK + "/auth/token/login", body={"token": session}
    )
    desk_token = _s((data or {}).get("token")) if isinstance(data, dict) else ""
    if status >= HTTP_REDIRECT or not desk_token:
        raise AdjudicatorError(
            IRDAI_SIGN_IN.format(
                status=status, text=extract_error(data, failed=True) or raw[:200]
            )
        )
    status, _data, raw = _http(
        "PUT",
        DESK + "/auth/participants",
        headers={"Authorization": "Bearer " + desk_token},
        body={"participant_codes": [payer_full]},
    )
    if status >= HTTP_REDIRECT:
        raise AdjudicatorError(
            IRDAI_PARTICIPANT.format(code=payer_full, status=status, text=raw[:200])
        )
    cache.set(key, desk_token, 30 * 60)
    return desk_token


def _irdai_case(claim, case_number):
    payer_full = _s(claim.payer_id) or common.default_payer_code()
    desk_token = _desk_token(claim, payer_full)
    status, data, raw = _http(
        "GET",
        f"{DESK}/cases?search={case_number}",
        headers={"Authorization": "Bearer " + desk_token},
    )
    if status >= HTTP_REDIRECT:
        cache.delete(DESK_TOKEN_KEY.format(code=_norm(payer_full)))
        raise AdjudicatorError(IRDAI_LIST.format(status=status, text=raw[:200]))
    rows = data.get("items") if isinstance(data, dict) else data
    found = next(
        (
            r
            for r in rows or []
            if isinstance(r, dict) and _s(r.get("claim_no")) == case_number
        ),
        None,
    )
    if found is None:
        raise AdjudicatorError(IRDAI_NO_CASE.format(case=case_number))
    return found, desk_token


def irdai_role(claim, case_number) -> dict:
    found, _tok = _irdai_case(claim, case_number)
    stage = _s(found.get("stage"))
    return {
        "caseNumber": case_number,
        "status": 200,
        "transport": "irdai-payer",
        "role": "Adjudicator",
        "step": {
            "stage": stage.upper() or "CASE",
            "usecase": stage,
            "role": "Adjudicator",
            "actions": ["approve", "reject", "query"],
        },
        "response": {
            "id": found.get("id"),
            "stage": stage,
            "adjudication": found.get("adjudication"),
        },
    }


def read_role(claim, stage) -> dict:
    claim = common.get_claim(claim)
    found = leg(claim, stage)
    if found is None:
        raise AdjudicatorError(NOT_SENT)
    return role_for(claim, found["case_number"], found["payer_code"])


# ---- A15 ----


def _record(claim, found, reply, remarks, cycle_id):
    ClaimAdjudication.objects.create(
        claim=claim,
        stage=found["stage"],
        case_number=found["case_number"],
        role=reply.get("role") or None,
        action=reply.get("action") or None,
        usecase=reply.get("usecase") or None,
        correlation_id=found["correlation_id"] or None,
        remarks=_s(remarks) or None,
        success=bool(reply.get("success")),
        http_status=reply.get("status"),
        response_json=reply,
        desk=reply.get("transport"),
        cycle_id=cycle_id or None,
    )


def _leg_or_fail(claim, stage):
    found = leg(claim, stage)
    if found is None:
        model = ClaimPreauth if stage == "preauth" else ClaimSubmission
        if model.objects.filter(claim=claim).exists():
            raise AdjudicatorError(NO_CORRELATION)
        raise AdjudicatorError(NOT_SENT)
    return found


def process(claim, stage, role, action, remarks="", cycle_id="") -> dict:
    claim = common.get_claim(claim)
    found = _leg_or_fail(claim, stage)
    if found["desk"] == "irdai-payer":
        return irdai_process(claim, found, action, remarks, cycle_id)
    if found["desk"] != "nhcx-payer-service":
        raise _no_desk(claim)
    role = _s(role)
    if not role:
        raise AdjudicatorError(NO_ROLE)
    step = step_for(role)
    if step is None:
        raise AdjudicatorError(UNKNOWN_ROLE.format(role=role))
    spelled = next((a for a in step["actions"] if _norm(a) == _norm(action)), None)
    if spelled is None:
        raise AdjudicatorError(
            ILLEGAL_ACTION.format(
                role=role, actions=", ".join(step["actions"]), action=_s(action)
            )
        )
    profile = common.facility_profile(claim.facility)
    sender = _bare(profile.participant_code) if profile else ""
    tok = token(claim)
    body = {
        "casenumber": found["case_number"],
        "action": spelled,
        "receivercode": found["payer_code"],
        "usecase": step["usecase"],
        "correlationid": found["correlation_id"],
        "sendercode": sender,
        "memberid": found["member_id"],
        "remarks": _s(remarks) or "ok",
    }
    url = (
        _s(getattr(settings, "NHCX_PAYER_SERVICE_PROCESS_CASE_URL", "")) or PROCESS_URL
    )
    status, data, raw = _http("POST", url, headers=_service_headers(tok), body=body)
    service_error = extract_error(data, failed=False) if status < HTTP_REDIRECT else ""
    reply = {
        "success": status < HTTP_REDIRECT and not service_error,
        "status": status,
        "action": spelled,
        "role": step["role"],
        "usecase": step["usecase"],
        "correlationId": found["correlation_id"],
        "request": body,
        "response": data,
        "raw": raw if data is None else None,
        "transport": "nhcx-payer-service",
    }
    if not reply["success"]:
        reply["error"] = (
            service_error
            or extract_error(data, failed=True)
            or f"the payer service returned {status}: {raw[:200]}"
        )
    _record(claim, found, reply, remarks, cycle_id)
    return reply


def irdai_process(claim, found, action, remarks, cycle_id) -> dict:
    action = _s(action).lower()
    if action not in DECISION_INDEX:
        raise AdjudicatorError(IRDAI_ACTION.format(action=action))
    if action in {"reject", "query"} and not _s(remarks):
        raise AdjudicatorError(IRDAI_REMARKS)
    case, desk_token = _irdai_case(claim, found["case_number"])
    status, data, raw = _http(
        "POST",
        f"{DESK}/cases/{case.get('id')}/adjudicate",
        headers={"Authorization": "Bearer " + desk_token},
        body={"action": action, "remarks": _s(remarks)},
    )
    reply = {
        "success": status < HTTP_REDIRECT,
        "status": status,
        "action": action,
        "role": "Adjudicator",
        "usecase": _s(case.get("stage")),
        "correlationId": found["correlation_id"],
        "response": data,
        "raw": raw if data is None else None,
        "transport": "irdai-payer",
        "cycle_id": cycle_id or None,
    }
    if not reply["success"]:
        reply["error"] = (
            extract_error(data, failed=True) or f"HTTP {status}: {raw[:200]}"
        )
    _record(claim, found, reply, remarks, cycle_id)
    return reply


def cycle(claim, stage, decision, remarks="") -> dict:
    claim = common.get_claim(claim)
    decision = _s(decision).lower()
    if decision not in DECISION_INDEX:
        raise AdjudicatorError(BAD_DECISION)
    found = leg(claim, stage)
    if found is None:
        raise AdjudicatorError(NOT_SENT)
    if found["desk"] == "irdai-payer":
        cid = str(uuid.uuid4())
        reply = irdai_process(claim, found, decision, remarks, cid)
        return {
            "cycle_id": cid,
            "decision": decision,
            "steps": [
                {
                    "role": reply["role"],
                    "action": decision,
                    "success": reply["success"],
                    "error": reply.get("error"),
                }
            ],
            "stopped": "decided" if reply["success"] else "refused",
            "final_role": None,
        }
    if found["desk"] != "nhcx-payer-service":
        raise _no_desk(claim)
    cid = str(uuid.uuid4())
    steps, seen = [], []
    stopped, final_role = "exhausted", None
    for _ in range(8):
        lookup = role_for(claim, found["case_number"], found["payer_code"])
        role = _s(lookup.get("role"))
        final_role = role or None
        if lookup.get("error") and not role:
            steps.append(
                {
                    "role": None,
                    "action": None,
                    "success": False,
                    "error": lookup["error"],
                }
            )
            stopped = "role-unreadable"
            break
        if not role:
            stopped = "no-role"
            break
        step = step_for(role)
        if step is None:
            steps.append(
                {
                    "role": role,
                    "action": None,
                    "success": False,
                    "error": lookup.get("warning"),
                }
            )
            stopped = "unknown-role"
            break
        if seen and _norm(seen[-1]) == _norm(role):
            stopped = "not-moved"
            break
        seen.append(role)
        action = DECISIONS[step["role"]][DECISION_INDEX[decision]]
        reply = process(claim, stage, role, action, remarks, cid)
        steps.append(
            {
                "role": reply.get("role") or role,
                "action": reply.get("action") or action,
                "success": reply["success"],
                "error": reply.get("error"),
            }
        )
        if not reply["success"]:
            stopped = "refused"
            break
        if decision != "approve" and step["role"] != "CEX-Trust":
            stopped = "decided"
            break
        if step["role"] == "Claim Review Committee" or (
            stage == "preauth" and step["role"] == "PPD-Trust"
        ):
            stopped = "completed"
            break
    return {
        "cycle_id": cid,
        "decision": decision,
        "steps": steps,
        "stopped": stopped,
        "final_role": final_role,
    }


REASONS = {
    "completed": "the case went through every role",
    "decided": "the decision was taken at the role holding it",
    "no-role": "nobody holds the case any more",
    "not-moved": "the payer service kept the case at the same role",
    "refused": "the payer service refused the last action",
    "role-unreadable": "the role could not be read",
    "unknown-role": "the role holding it is not in the published workflow",
    "exhausted": "the step limit was reached",
}


def cycle_flash(result) -> str:
    taken = ", ".join(
        f"{s['action']} as {s['role']}" for s in result["steps"] if s.get("action")
    )
    tail = f" Taken: {taken}." if taken else " Nothing was taken."
    return f"Cycle {result['stopped']}: {REASONS.get(result['stopped'], '')}.{tail}"


def adjudicate(claim, data) -> dict:
    """The API door: {action: role|process|cycle, stage, role?, decision?, remarks?}."""
    action = _s(data.get("action")) or "role"
    stage = _s(data.get("stage")) or "preauth"
    if action == "role":
        return {"reply": read_role(claim, stage)}
    if action == "cycle":
        result = cycle(claim, stage, data.get("decision"), data.get("remarks"))
        ok = result["stopped"] in {"completed", "decided", "no-role"}
        return {"cycle": result, "message": cycle_flash(result), "success": ok}
    reply = process(
        claim,
        stage,
        data.get("role"),
        data.get("take") or data.get("decision"),
        data.get("remarks"),
    )
    msg = (
        "Decision sent to the payer service."
        if reply["success"]
        else (reply.get("error") or "The payer service refused it.")
    )
    return {"reply": reply, "message": msg, "success": reply["success"]}

"""Facility-scoped NHCX leg routes (api/CONTRACT.md "legs"), mounted by api/urls.py
under /api/v1/facility/<facility_external_id>/nhcx/.

Sending routes run outside ATOMIC_REQUESTS (``SendingView``): a gateway call
must not sit inside a transaction, and a failed send keeps its row and ids.
"""

from __future__ import annotations

from django.http import Http404

from care.nhcx.api.views_core import (
    NhcxFacilityView,
    SendingView,
    ok,
    refusals,
    refused,
)
from care.nhcx.models import ClaimPayment, ClaimQuery, FacilityProfile
from care.nhcx.services import (
    adjudicator,
    biometric,
    communication,
    draft,
    payment,
    preauth,
)
from care.nhcx.services import claim as claim_service
from care.nhcx.services.common import ServiceRefusal

EXCHANGE_FAILED = "The exchange failed."
PREAUTH_SUBMITTED = "Pre-authorisation submitted to the payer."
PREDETERMINATION_SENT = "Predetermination sent to the payer."
CANCEL_SENT = "Cancellation sent to the payer."
STATUS_SENT = "Status enquiry sent to the payer."
REPROCESS_SENT = "Reprocess request sent to the payer."
RELEASE_SENT = "Balance release request sent to the payer."
CLAIM_SUBMITTED = "Claim submitted to the payer."
REPLY_SENT = "Reply sent to the payer."
ACK_SENT = "Acknowledgement sent to the payer."
PAYMENT_ACKED = "Payment acknowledged to the payer."
ATTACHED = "{n} document(s) attached."
SETTINGS_SAVED = "Facility settings saved."
NO_FILE = "Choose a PDF or image to attach."
ENQUIRY_SENT = {
    "status": STATUS_SENT,
    "reprocess": REPROCESS_SENT,
    "release": RELEASE_SENT,
}
PROFILE_FIELDS = ("hfr_id", "participant_code", "email", "gstin")


def _s(value) -> str:
    return "" if value is None else str(value).strip()


def _body(request) -> dict:
    data = request.data
    if hasattr(data, "dict"):
        return data.dict()
    return dict(data or {})


def _sent(row, message, claim, **extra):
    """200 with the message, or 400 naming the failure when the send failed; the
    row (and the ids it already holds) is kept either way."""
    if _s(getattr(row, "status", "")) == "error":
        error = _s(getattr(row, "error_message", "")) or EXCHANGE_FAILED
        return refused(error) if claim is None else _failed(error, claim)
    return ok(message, claim, **extra)


def _failed(error, claim):
    response = refused(error)
    response.data["claim_id"] = str(claim.external_id)
    return response


def _upload(request):
    f = request.FILES.get("file")
    if f is None:
        return None
    return {
        "filename": f.name,
        "content_type": _s(f.content_type),
        "data": f.read(),
    }


class DraftView(NhcxFacilityView):
    @refusals
    def put(self, request, facility_external_id, claim_id):
        case = self.claim(claim_id)
        return ok(draft.save_draft(case, _body(request)), case)


class DocumentsView(NhcxFacilityView):
    @refusals
    def post(self, request, facility_external_id, claim_id):
        case = self.claim(claim_id)
        upload = _upload(request)
        if upload is None:
            raise ServiceRefusal(NO_FILE)
        data = request.data
        doc = draft.attach(
            case,
            upload,
            code=_s(data.get("code")),
            category=_s(data.get("category")),
            leg=_s(data.get("stage")) or "preauth",
            label=_s(data.get("label")),
        )
        return ok(ATTACHED.format(n=1), case, document_id=str(doc.external_id))


class DocumentDetailView(NhcxFacilityView):
    @refusals
    def delete(self, request, facility_external_id, claim_id, doc_id):
        case = self.claim(claim_id)
        return ok(draft.remove_document(case, doc_id), case)


class PreauthSubmitView(SendingView):
    @refusals
    def post(self, request, facility_external_id, claim_id):
        case = self.claim(claim_id)
        data = _body(request)
        row = preauth.submit_preauth(case, _s(data.get("reply")))
        return _sent(row, PREAUTH_SUBMITTED, case)


class PredeterminationView(SendingView):
    @refusals
    def post(self, request, facility_external_id, claim_id):
        case = self.claim(claim_id)
        row = preauth.ask_predetermination(case)
        return _sent(row, PREDETERMINATION_SENT, case)


class PreauthCancelView(SendingView):
    @refusals
    def post(self, request, facility_external_id, claim_id):
        case = self.claim(claim_id)
        data = _body(request)
        row = preauth.cancel_preauth(case, _s(data.get("reason")), _s(data.get("note")))
        if _s(row.status) == "error":
            return _failed(_s(row.error_message) or EXCHANGE_FAILED, case)
        return ok(CANCEL_SENT, case)


class EnquiryView(SendingView):
    @refusals
    def post(self, request, facility_external_id, claim_id):
        case = self.claim(claim_id)
        data = _body(request)
        action = _s(data.get("action")) or "status"
        row = claim_service.enquire(
            case,
            action,
            leg=_s(data.get("leg")),
            reason=_s(data.get("reason")),
            note=_s(data.get("note")),
            amount=data.get("amount"),
            reason_code=_s(data.get("reason_code")),
            document_ids=data.get("document_ids") or None,
        )
        return _sent(
            row,
            ENQUIRY_SENT.get(action, STATUS_SENT),
            case,
            enquiry_id=str(row.external_id),
        )


class ClaimSubmitView(SendingView):
    @refusals
    def post(self, request, facility_external_id, claim_id):
        case = self.claim(claim_id)
        data = _body(request)
        if _s(data.get("discharge_mode")):
            claim_service.record_discharge(case, data)
            case = self.claim(claim_id)
        row = claim_service.submit_claim(case, _s(data.get("reply")))
        return _sent(row, CLAIM_SUBMITTED, case)


class DischargeView(NhcxFacilityView):
    @refusals
    def post(self, request, facility_external_id, claim_id):
        case = self.claim(claim_id)
        claim_service.record_discharge(case, _body(request))
        return ok(claim_service.DISCHARGE_RECORDED, case)


class QueryReplyView(SendingView):
    @refusals
    def post(self, request, facility_external_id, claim_id, query_id):
        case = self.claim(claim_id)
        asked = ClaimQuery.objects.filter(claim=case, external_id=query_id).first()
        if asked is None:
            raise Http404
        data = request.data
        ids = data.getlist("document_ids") if hasattr(data, "getlist") else None
        ids = ids or data.get("document_ids") or []
        uploads = []
        for f in request.FILES.getlist("files") if request.FILES else []:
            uploads.append(
                {
                    "filename": f.name,
                    "content_type": _s(f.content_type),
                    "data": f.read(),
                }
            )
        communication.answer_query(
            asked.id,
            _s(data.get("text")),
            _document_pks(case, ids),
            uploads,
            claim=case,
        )
        return ok(REPLY_SENT, case)


class QueryAckView(SendingView):
    @refusals
    def post(self, request, facility_external_id, claim_id, query_id):
        case = self.claim(claim_id)
        asked = ClaimQuery.objects.filter(claim=case, external_id=query_id).first()
        if asked is None:
            raise Http404
        communication.acknowledge_notification(asked.id, claim=case)
        return ok(ACK_SENT, case)


def _document_pks(case, ids):
    from care.nhcx.models import ClaimDocument

    out = []
    for given in ids or []:
        ref = _s(given)
        if not ref:
            continue
        if ref.isdigit():
            out.append(int(ref))
            continue
        doc = ClaimDocument.objects.filter(claim=case, external_id=ref).first()
        if doc is None:
            raise ServiceRefusal(communication.f12.DOCUMENT_NOT_ON_CLAIM)
        out.append(doc.id)
    return out


class PaymentAckView(SendingView):
    @refusals
    def post(self, request, facility_external_id, claim_id, payment_id):
        case = self.claim(claim_id)
        money = ClaimPayment.objects.filter(claim=case, external_id=payment_id).first()
        if money is None:
            raise Http404
        payment.acknowledge_payment(money.id, claim=case)
        return ok(PAYMENT_ACKED, case)


class BiometricView(SendingView):
    def get(self, request, facility_external_id, claim_id):
        case = self.claim(claim_id)
        return ok(None, case, **biometric.listing(case))

    @refusals
    def post(self, request, facility_external_id, claim_id, action):
        case = self.claim(claim_id)
        data = _body(request)
        if action == "init":
            row, qr = biometric.init(
                case,
                _s(data.get("method")) or "FACE_AUTH",
                stage=_s(data.get("stage")) or None,
                abha_no=_s(data.get("abha_no")) or None,
                user=request.user,
                payer_code=_s(data.get("payer_code")) or None,
            )
            return ok(None, case, attempt=biometric.describe(row), qr_url=qr)
        row = biometric.attempt(case, data.get("attempt_id"))
        if action == "capture":
            row, state = biometric.capture(row)
            return ok(None, case, attempt=biometric.describe(row), capture=state)
        if action == "verify":
            row = biometric.verify(
                row,
                pid=_s(data.get("pid")),
                aadhaar_encrypted=_s(data.get("aadhaar_encrypted")),
                mobile=_s(data.get("mobile")),
            )
            return ok(_s(row.message) or None, case, attempt=biometric.describe(row))
        if action == "refresh":
            row = biometric.refresh(row)
            return ok(None, case, attempt=biometric.describe(row))
        raise Http404


class AdjudicateView(SendingView):
    def initial(self, request, *args, **kwargs):
        if not adjudicator.enabled():
            raise Http404
        super().initial(request, *args, **kwargs)

    @refusals
    def post(self, request, facility_external_id, claim_id):
        case = self.claim(claim_id)
        result = adjudicator.adjudicate(case, _body(request))
        message = result.pop("message", None)
        if result.get("success") is False:
            response = refused(message or EXCHANGE_FAILED)
            response.data.update(result)
            response.data["claim_id"] = str(case.external_id)
            return response
        return ok(message, case, **result)


class FacilityProfileView(NhcxFacilityView):
    def _profile(self):
        return FacilityProfile.objects.filter(facility=self.facility).first()

    def get(self, request, facility_external_id):
        found = self._profile()
        return ok(
            None,
            profile={k: _s(getattr(found, k, "")) for k in PROFILE_FIELDS},
        )

    def put(self, request, facility_external_id):
        data = _body(request)
        found = self._profile() or FacilityProfile(facility=self.facility)
        for k in PROFILE_FIELDS:
            if k in data:
                setattr(found, k, _s(data.get(k)) or None)
        found.save()
        return ok(
            SETTINGS_SAVED,
            profile={k: _s(getattr(found, k, "")) for k in PROFILE_FIELDS},
        )


