def check_draft(claim):
    """Refusals 5 to 9 of A4 (6 to 10 of A5); returns (diagnoses, practitioners, lines)."""
    if not claim.encounter_id:
        raise common.ServiceRefusal(NO_ENCOUNTER)
    if not claim.admission_date:
