def total(lines) -> float:
    out = 0.0
    for line in lines:
        if line.amount not in (None, ""):
            out += float(line.amount)
        elif line.unit_price not in (None, ""):
            out += float(line.unit_price) * float(line.quantity or 1)
    return round(out, 2)


def document_input(doc) -> DocumentInput:
