    if adapter.desk == "nhcx-payer-service":
        pre = ClaimPreauth.objects.filter(claim=claim).first()
        reference = _s(pre.preauth_ref) if pre else ""
        if "/" in reference:
            case_number = reference.rsplit("/", 1)[-1]
