"""The e2e report (T2X): one entry per test and runner, merged into one file."""

from __future__ import annotations

import json
from pathlib import Path

from django.utils import timezone

RESULTS = ("pass", "fail", "blocked", "skipped")


def read(path: Path) -> dict:
    try:
        data = json.loads(path.read_text())
    except (OSError, ValueError):
        data = {}
    return data if isinstance(data, dict) else {}


def summary(tests) -> dict:
    out = dict.fromkeys(RESULTS, 0)
    for t in tests:
        if t.get("result") in out:
            out[t["result"]] += 1
    return out


def _order(entry) -> tuple:
    tid = str(entry.get("id") or "")
    digits = "".join(ch for ch in tid if ch.isdigit())
    return (int(digits or 0), entry.get("runner") != "cli")


def merge(path: Path, config: dict, setup_checks=None, entries=()) -> dict:
    """Writes ``entries`` over any earlier entry of the same (id, runner)."""
    data = read(path)
    data["run_at"] = timezone.now().isoformat()
    data["config"] = config
    if setup_checks is not None:
        data["setup_checks"] = setup_checks
    data.setdefault("setup_checks", [])
    keep = {(t.get("id"), t.get("runner")): t for t in data.get("tests") or []}
    for e in entries:
        keep[(e.get("id"), e.get("runner"))] = e
    data["tests"] = sorted(keep.values(), key=_order)
    data["summary"] = summary(data["tests"])
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, indent=2, default=str) + "\n")
    return data

"""Setup checks run before the first test (T2S, G11)."""

from __future__ import annotations

import urllib.error
import urllib.request


def _row(check, ok, detail) -> dict:
    return {"check": check, "result": "pass" if ok else "fail", "detail": detail}


def _reachable(url) -> tuple[bool, str]:
    try:
        with urllib.request.urlopen(url, timeout=10) as r:  # noqa: S310
            return r.status < 400, f"{url} answered {r.status}"  # noqa: PLR2004
    except urllib.error.HTTPError as e:
        return False, f"{url} answered {e.code}"
    except (OSError, ValueError) as e:
        return False, f"{url} unreachable: {e}"


def run(conf, *, gui=False) -> list:
    """The G11 checks, the test data and, for the GUI, the screens' address."""
    from care.nhcx.gateway import get_gateway
    from care.nhcx.gateway.checks import check

    rows = []
    try:
        result = check(get_gateway())
    except Exception as e:  # noqa: BLE001
        return [_row("gateway", False, f"{type(e).__name__}: {e}")]
    rows.extend(_row(c["name"], c["ok"], c.get("detail") or "") for c in result["checks"])
    endpoint = result.get("endpoint") or {}
    rows.append(_row("endpoint probe", endpoint.get("ok"), endpoint.get("detail") or ""))
    missing = [
        key
        for key in (
            "NHCX_TEST_FACILITY",
            "NHCX_TEST_USER",
            "NHCX_TEST_PASSWORD",
            "NHCX_TEST_DOCTOR",
        )
        if not conf.get(key)
    ]
    rows.append(
        _row(
            "test data",
            not missing,
            "facility, operator and doctor set"
            if not missing
            else "run `nhcx_e2e setup`; missing " + ", ".join(missing),
        )
    )
    if gui:
        ok, detail = _reachable(conf.get("NHCX_TEST_APP_URL") or "http://localhost:4000")
        rows.append(_row("screens reachable", ok, detail))
    return rows


def failed(rows) -> list:
    return [r for r in rows if r["result"] != "pass"]

