import json
from pathlib import Path

from care.nhcx.tests.e2e import config as cfg

SEED_SOURCE = "test seed"


def load(conf=None) -> dict:
    conf = conf or cfg.load()
    path = Path(conf.get("NHCX_TEST_PMJAY_PLAN_SEED"))
    if not path.is_absolute():
        path = cfg.CARE_ROOT / path
    return json.loads(path.read_text())


def _identifier(plan) -> str:
    rows = plan.get("identifier") or []
    return next((r.get("value") for r in rows if r.get("type") != "NH"), "") or ""


def parsed(seed: dict) -> dict:
    """The seed in the shape ``care.nhcx.fhir.read.plan.read`` gives C4."""
    plan = seed.get("plan") or {}
    benefits = []
    for p in seed.get("packages") or []:
        speciality = p.get("speciality") or {}
        info = [
            {
                "category": d.get("category"),
                "category_display": "",
                "code": d.get("code"),
                "display": d.get("name"),
                "form": None,
            }
            for d in p.get("documents") or []
        ]
        info += [
            {
                "category": r.get("category"),
                "category_display": "",
                "code": r.get("code"),
                "display": r.get("display"),
                "form": None,
            }
            for r in p.get("requirements") or []
        ]
        benefits.append(
            {
                "category_code": speciality.get("code"),
                "category_display": speciality.get("display"),
                "code": p.get("code"),
                "display": p.get("name"),
                "kind": "Procedure",
                "rate": p.get("rate"),
                "currency": p.get("currency") or "INR",
                "cost_type": "Procedure",
                "requirement": None,
                "conditions": p.get("conditions") or {},
                "extras": [],
                "supporting_info": info,
            }
        )
    forms = [
        {
            "url": q.get("url"),
            "form_id": (q.get("url") or "").rstrip("/").rsplit("/", 1)[-1],
            "title": q.get("title"),
            "kind": "questionnaire",
            "items": [
                {
                    "linkId": i.get("linkId"),
                    "type": i.get("type"),
                    "text": i.get("text"),
                    "required": bool(i.get("required")),
                    "depth": 0,
                    "options": i.get("options") or [],
                    "initial": None,
                }
                for i in q.get("items") or []
            ],
        }
        for q in seed.get("questionnaires") or []
    ]
    return {
        "plan": {
            "plan_identifier": _identifier(plan),
            "plan_title": plan.get("name"),
            "plan_type": (plan.get("plan_type") or {}).get("display"),
            "sum_insured": None,
            "policy_documents": [],
        },
        "benefits": benefits,
        "forms": forms,
    }


def is_seeded(row) -> bool:
    body = row.response_json if row is not None else None
    return isinstance(body, dict) and body.get("source") == SEED_SOURCE


def apply(claim, conf=None) -> tuple[bool, str]:
    """Seeds the claim's plan unless a real plan is already ready."""
    from care.nhcx.callbacks.plan import apply_plan
    from care.nhcx.models import ClaimPlan

    seed = load(conf)
    row = ClaimPlan.objects.filter(claim=claim).order_by("-id").first()
    if row is not None and row.status == "ready" and not is_seeded(row):
        return False, "the payer's own plan is ready; the seed is not written"
    if row is None:
        row = ClaimPlan.objects.create(
            claim=claim, status="fetching", policy_code=claim.policy_code
        )
    apply_plan(row, parsed(seed), {"source": SEED_SOURCE, "seed": seed})
    row.refresh_from_db()
    return True, f"{row.status}, {row.benefits.count()} packages, {row.forms.count()} forms"


def remove(claims) -> int:
    from care.nhcx.models import ClaimPlan

    gone = 0
    for row in ClaimPlan.objects.filter(claim__in=claims):
        if is_seeded(row):
            row.delete()
            gone += 1
    return gone

"""The payer-side driver both runners use (T2X "Deciding the payer's side").

A decision is always read then taken: the role or case first (A14), then the
action (A15), through ``care.nhcx.services.adjudicator`` - the IRDAI payer desk
for the IRDAI test payer, the NHCX Payer Service role walk for PMJAY. The
IRDAI desk's other acts (per-line decisions, payments) use the same desk
sign-in.
"""

from __future__ import annotations

from care.nhcx.services import adjudicator as adj

NO_DATA = "no data found"


def _claim(claim):
    from care.nhcx.services import common

    return common.get_claim(claim)


def read(claim, stage) -> dict:
    """A14: who holds the case (PMJAY) or the case itself (IRDAI)."""
    claim = _claim(claim)
    try:
        reply = adj.read_role(claim, stage)
    except adj.AdjudicatorError as e:
        return {"error": str(e), "role": ""}
    return reply


def auto_decided(reply) -> bool:
    """The PMJAY sandbox decided by itself: the role read finds no case."""
    text = f"{reply.get('error') or ''} {reply.get('response') or ''}".lower()
    return not reply.get("role") and NO_DATA in text


def decide(claim, stage, decision, remarks="") -> dict:
    """A14 then A15; returns the record the report keeps for the decision."""
    claim = _claim(claim)
    looked = read(claim, stage)
    record = {
        "stage": stage,
        "decision": decision,
        "remarks": remarks,
        "read": {
            k: looked.get(k)
            for k in ("caseNumber", "role", "status", "error", "warning", "response")
        },
    }
    if auto_decided(looked):
        record["skipped"] = "sandbox auto-decided"
        return record
    if looked.get("error") and not looked.get("role"):
        record["error"] = looked["error"]
        return record
    try:
        result = adj.cycle(claim, stage, decision, remarks)
    except adj.AdjudicatorError as e:
        record["error"] = str(e)
        return record
    record["cycle_id"] = result["cycle_id"]
    record["stopped"] = result["stopped"]
    record["trail"] = result["steps"]
    return record


# ---- the IRDAI desk's other acts (A15 "the payer's other acts") ----


def _irdai(claim, stage):
    claim = _claim(claim)
    found = adj.leg(claim, stage)
    if found is None:
        raise adj.AdjudicatorError(adj.NOT_SENT)
    case, tok = adj._irdai_case(claim, found["case_number"])  # noqa: SLF001
    return claim, case, {"Authorization": "Bearer " + tok}


def irdai_case(claim, stage) -> dict:
    """The case on the desk, with its line items where the desk lists them."""
    _claim_row, case, headers = _irdai(claim, stage)
    status, data, raw = adj._http(  # noqa: SLF001
        "GET", f"{adj.DESK}/cases/{case.get('id')}", headers=headers
    )
    if status < adj.HTTP_REDIRECT and isinstance(data, dict):
        return data
    return {**case, "_detail_status": status, "_detail_raw": raw[:200]}


def _line_items(case) -> list:
    for key in ("line_items", "lineItems", "items"):
        rows = case.get(key)
        if isinstance(rows, list):
            return rows
    return []


def irdai_lines(claim, stage, amounts, remarks="e2e line decision") -> dict:
    """Decides each line at the given approved amount (``None`` keeps it)."""
    _c, case, headers = _irdai(claim, stage)
    detail = irdai_case(claim, stage)
    rows = _line_items(detail)
    out = []
    for row, amount in zip(rows, amounts, strict=False):
        if amount is None:
            continue
        status, data, raw = adj._http(  # noqa: SLF001
            "PATCH",
            f"{adj.DESK}/cases/{case.get('id')}/line-items/{row.get('id')}",
            headers=headers,
            body={
                "status": "approved",
                "approved_amount": amount,
                "remarks": remarks,
            },
        )
        out.append(
            {
                "line": row.get("id"),
                "amount": amount,
                "status": status,
                "error": None if status < adj.HTTP_REDIRECT else raw[:200],
            }
        )
    return {"case": case.get("id"), "lines": out, "listed": len(rows)}


def irdai_pay(claim, amount, utr, *, stage="claim") -> dict:
    """Raises a payment with its UTR, so the desk completes it in one step."""
    claim, case, headers = _irdai(claim, stage)
    status, data, raw = adj._http(  # noqa: SLF001
        "POST",
        f"{adj.DESK}/payments",
        headers=headers,
        body={
            "case_id": case.get("id"),
            "payment_amount": amount,
            "mode": "NEFT",
            "beneficiary": {
                "name": claim.facility.name,
                "account_no": "000123456789",
                "ifsc": "SBIN0000001",
            },
            "utr_no": utr,
        },
    )
    return {
        "case": case.get("id"),
        "amount": amount,
        "utr": utr,
        "status": status,
        "response": data if data is not None else raw[:300],
        "error": None if status < adj.HTTP_REDIRECT else raw[:300],
    }

