      let quantity = Number(line.quantity);
      if (edit.quantity.trim() !== "") {
        const q = Number(edit.quantity);
        if (!Number.isFinite(q) || q <= 0) {
          toast.error(t("nhcx_enter_quantity", { code: line.code }));
          return;
        }
        if (!Number.isInteger(q)) {
