async function attachDocuments(page: Page, e: Entry) {
  const p = panel(page);
  const attach = p.getByRole("button", { name: "Attach chosen files" });
  if (!(await attach.isVisible().catch(() => false))) return;
  const card = p.locator("div.rounded-lg, [class*=card]").filter({ has: attach }).last();
  const rows = card.getByRole("row").filter({ hasText: "Not attached yet" });
  const n = await rows.count();
  const codes: string[] = [];
  for (let i = 0; i < n; i++) {
    const row = rows.nth(i);
    codes.push(((await row.getByRole("cell").first().textContent()) || "").trim());
    await row.locator("input[type=file]").setInputFiles({
      name: `e2e-${codes[i] || i}.pdf`,
      mimeType: "application/pdf",
      buffer: PDF,
    });
  }
  if (!n) return;
  await attach.click();
  await expect(card.getByText("Not attached yet")).toHaveCount(0, { timeout: 30000 });
  await e.step("provider attaches the required documents", codes.join(", "));
}

async function answerForms(page: Page, e: Entry) {
  const p = panel(page);
  const card = p
    .locator("div.rounded-lg, [class*=card]")
    .filter({ has: page.getByText("Forms the payer requires", { exact: true }) })
    .last();
  if (!(await card.count())) return;
  const triggers = card.getByRole("button", { expanded: false });
  const titles: string[] = [];
  const total = await card.locator("[data-state][data-orientation] > h3 button").count();
  for (let i = 0; i < total; i++) {
    const trigger = card.locator("[data-state][data-orientation] > h3 button").nth(i);
    titles.push(((await trigger.textContent()) || "").trim());
    if ((await trigger.getAttribute("aria-expanded")) !== "true") await trigger.click();
    const region = card.getByRole("region").last();
    await fillQuestions(page, region);
    await region.getByRole("button", { name: "Save answers" }).click();
    await expect(page.getByText(/Answers saved/i).first()).toBeVisible();
  }
  void triggers;
  if (titles.length) await e.step("provider answers the pre-authorisation forms", titles.join("; "));
}

async function fillQuestions(page: Page, region: Locator) {
  const fields = region.locator("[id^=nhcx-q-]");
  const n = await fields.count();
  for (let i = 0; i < n; i++) {
    const f = fields.nth(i);
    const tag = await f.evaluate((el) => el.tagName.toLowerCase());
    const type = (await f.getAttribute("type")) || "";
    const role = await f.getAttribute("role");
    if (type === "file") {
      await f.setInputFiles({ name: "e2e-form.pdf", mimeType: "application/pdf", buffer: PDF });
    } else if (role === "combobox") {
      await f.click();
      const options = page.getByRole("option");
      await options.nth((await options.count()) > 1 ? 1 : 0).click();
    } else if (type === "date") {
      await f.fill(iso(new Date()));
    } else if (type === "datetime-local") {
      await f.fill(`${iso(new Date())}T10:00`);
    } else if (type === "number") {
      await f.fill("1");
    } else if (tag === "textarea" || tag === "input") {
      if (!(await f.inputValue())) await f.fill("e2e");
    }
  }
}

