/** The payer's decision through the shared payer driver (T2G). */
export async function payerDecides(
  e: Entry,
  claimId: string,
  stage: string,
  decision: string,
) {
  const record = backend<Record<string, unknown>>(
    "payer",
    "decide",
    claimId,
    decision,
    "--stage",
    stage,
    "--remarks",
    "e2e gui",
  );
  e.decisions.push(record);
  const trail = ((record.trail as { action?: string; role?: string }[]) || [])
    .map((s) => `${s.action} as ${s.role}`)
    .join(", ");
  if (record.skipped) {
    await e.step(`payer desk takes ${decision}`, String(record.skipped), "skipped");
    return record;
  }
  const ok = ["decided", "completed"].includes(String(record.stopped));
  if (!ok && /not enough cover left/i.test(trail + String(record.error || ""))) {
    throw new Stop(`payer desk refuses ${decision}: the member's cover is used up (${trail})`, "blocked", "sandbox");
  }
  await e.check(
    ok,
    `payer desk takes ${decision}`,
    `${record.stopped}, ${trail || record.error || ""}`,
    "sandbox",
  );
  return record;
}

