  if (!(await attach.isVisible().catch(() => false))) return;
  const card = p.locator("div.rounded-lg, [class*=card]").filter({ has: attach }).last();
  const rows = card.getByRole("row").filter({ hasText: "Not attached yet" });
  const n = await rows.count();
  const codes: string[] = [];
