        "x-hcx-status request.initiated with a new correlation (nhcx-docs flows claim-query-response, "
        "preauth-query-response; NHCX-1011 otherwise); RESPONSE_KINDS removed",
    ),
    "care/nhcx/tests/network_guard.py": ("tests", "exemption for the e2e runner (unit suite stays network-free)"),
    "care/nhcx/tests/test_gap_coverage.py": ("tests", "d12, d17, a15, a17"),
    "care/nhcx/tests/test_callbacks_legs.py": ("tests", "c8"),
    "care/nhcx/tests/test_dry_flow.py": ("tests", "query answer goes out as request.initiated"),
}
corrections = [
    {"path": f"care/{p}", "status": "modified", "plan_step": "L8.4", "implements": v[0], "why": v[1]}
    for p, v in MODIFIED.items()
]

report = json.loads((PLAN / "e2e.json").read_text())
agent = {
    "files": files,
    "tests": {
