    "notes": [
        "skill CORE.md:90 / A5 say query answers carry response.complete; nhcx-docs and the live "
        "gateway (NHCX-1011) require request.initiated on submit paths; code follows nhcx-docs",
        "e2e modules are not named test*.py, so manage.py test never discovers them",
    ],
}
(PLAN / "_agent" / "e2e.json").write_text(json.dumps(agent, indent=2) + "\n")

# ---- e2e-log ----
log = []
for f in files:
    log.append(
        {
            "substep": "L8.2",
            "item": f["path"],
            "summary": "e2e harness file for " + ", ".join(f["implements"]["tests"]),
