            "result": "written",
        }
    )


def hunks(path):
    out = []
    for line in git(CARE, "diff", "-U0", "--", path).splitlines():
        m = re.match(r"@@ -\S+ \+(\d+)(?:,(\d+))? @@", line)
        if m:
            start, cnt = int(m.group(1)), int(m.group(2) or 1)
            if cnt:
                out.append(f"{start}-{start + cnt - 1}")
    return ",".join(out)


