    ("T17 cli", "care/nhcx/tests/e2e/scenarios/common.py", "open_preauths ignores claims the gateway refused (status error), so free_beneficiary cancels their pre-auth (PAYR-1238)"),
    ("T3..T5 gui", "care_fe/tests/nhcx/helpers.ts", "selectors by visible labels and chips"),
]
for item, path, why in HARNESS_FIXES:
